INSERT INTO `w_bo_gd_20250707155940` VALUES ('2056647417612165121', '0', '0', '17253690046572896', '周宇', '2026-05-19 16:05:30', '113845370124130976', '彭佳庆', '2026-09-21 17:50:36', '1', '2056647417893126146', 'RUNNING', '运行中', '909783222', '评香部', '10', 'YPGD-20260519-0025', '2056242808708096001', '培蘑--百香果创香20260518', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000以内', '113845370124130976,16466317325076496', NULL, '2056240351974219777', '冷先生', '冷先生\n17717022237\n上海慈竹路608弄3号楼1005 冷先生 17717022237\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '07/06反馈，需要两个方向创香，07/17\n1：花香+百香果\n2：草本＋百香果', 'LYP2420ALY-百果辛香1，LYP2422ALY-草本百香1，LYP2422CLY-草本百香2，LYP2422BLY-百果焚香2\n\nLYP2492ELY-百香果-V3\nLYP2492ELY-百香果-V5', '自提', '2026-06-04 00:00:00', 'false', NULL, '彭佳庆,梁皓', '冷先生项目\nSYP2043DSY 百香果香基\n调香师：刘扬\n1.加入多汁、精纯的果香状态。\n百香果香基未经稀释的状态是最好的，果香饱满，目前果香的状态比较偏平，经过多轮普通消费者测试，大家反馈平平。增\n加多汁意向可在前调迅速抓住鼻子。\n2.降糖\n百香果被Pape Moe定位为热卖选题（同草莓、芭乐）为了更好的销量希望适当降低甜度，去适配更多的中国消费者。\n3.多样的搭配增加耐闻度，与市面上单一果香品牌拉开距离\n我们提出一些搭配思路供调香师参考\nA.焚香+百香果\n轻盈的日式焚香与百香果的热情碰撞\nB.草本+百香果\n罗勒、尤加利、薄荷、斑斓一些比较受欢迎的草本都可以尝试。\nC.辛香+百香果\n一些比较芳香偏绿的辛香，芫荽、黑胡椒、小豆蔻、月桂叶等等\n\n需要根据客户需求提供3个方向递样\nSYP2043DSY 百香果香基整体减低甜感，增加热带果感\n该项目指定调香师：刘扬\n1、焚香+百香果\n2、草本+百香果\n3、辛香+百香果\n\n需求价格：2000以内\n需要15%香水加香产品\n需求时间：6.5寄出', '-', NULL, NULL, NULL, NULL, NULL);
