INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057277237421367297', '0', '0', '17253690046572896', '周宇', '2026-05-21 09:48:10', '17201757871959617', '赵倩', '2026-06-16 13:19:59', '1', '2057277237643608066', 'RUNNING', '运行中', '909783222', '评香部', '15', 'YPGD-20260521-0003', '2057029494580928514', '山下有松--陈皮青柑藤条修改20260520', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-06-05 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,16466317325076496', NULL, '2048619010949341186', '王妍', '王妍\n13581841518\n北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '香精10g, 要加香产品10%\n\n06/09 反馈\n减绿、减壤香，更陈皮，接近原版，注意闪点', NULL, 'SF5134069979490', NULL, 'false', NULL, '彭佳庆,梁皓', '北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n--\n陈皮青柑（新改版4#） JKP2209JJK8B\n客户目前改版香精用于香水现需要同款藤条产品\n做降价至400以内\n-\n需注意闪点问题！！！！！！\n需要爆发力和扩香表现力\n-\n需要50g，10% 无火加香产品，溶剂MMB\n需求价格：400以内\n需求时间：6.5', '-', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057280551647141889', '0', '0', '17253690046572896', '周宇', '2026-05-21 10:01:21', '17201757871959617', '赵倩', '2026-06-01 15:56:25', '1', '2057280551856799745', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260521-0006', '2057025984380493825', '昆山永青--泰国出口唇部香精修改20260520', NULL, '1', '需求明确', '1', '客户新品开发', '206', '口腔护理', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '113845370124130976,16466317325076496', NULL, '2034161062508478465', '刘柳', '刘柳\n15962636827\n昆山市千灯镇石浦声荣路188号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'DXR778CDX 香草吉拉托（唇部）\nDXR751ADX 草莓限定（唇部）\n冰淇淋主题，减甜，加薄荷，增加清爽感\n--欧盟法规\n--可先递10g 样\n\n06/01 -- IFRA 法规核验OK', NULL, 'SF5135534947202', NULL, 'false', NULL, '彭佳庆,梁皓', '刘柳 15962636827 昆山市千灯镇石浦声荣路188号\n-\n客户选中四款奶油、冰淇凌主题唇部用香精，反馈目前香气过甜\n需要降低甜感，增加薄荷凉感，增加夏日清爽感\n出口泰国，需确认修改后符合欧盟法规\nDXR778CDX 香草吉拉托（唇部）\nDXR751ADX 草莓限定（唇部）\nLJR168ALJ 北海道雪顶（唇部）\nSYR624ASY 夏日薄巧（唇部）\n需求价格300\n需求时间：6.3\n需要20g香精', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057281611795226626', '0', '0', '17253690046572896', '周宇', '2026-05-21 10:05:33', '17201757871959617', '赵倩', '2026-06-04 16:19:20', '1', '2057281612025856002', 'RUNNING', '运行中', '909783222', '评香部', '8', 'YPGD-20260521-0007', '2056937516610576385', '粉合--初气--伪体香香水系列推荐20260520', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,16466317325076496', NULL, '2036287340661424130', 'Mia', 'Mia\n18817591984\n上海市黄浦区淮海中路300号 香港新世界大厦52F 粉合集团 Mia收 18817591984\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '需要打样3款，烦请帮安排~ 谢谢！', NULL, 'SF5198039741098', NULL, 'true', NULL, '彭佳庆,梁皓', 'Mia项目\n客户需要推荐伪体香类型香气\n产品用于香水\n之前已推荐过伊甸之果、茶瀑、自己等近期仿香伪体香作品，需推荐一批新的伪体香不与之前重合\n客户已指定香气：JKP872AJK 夏日\n另需推荐3~5款大牌伪体香概念香气\n需要10%香水加香产品\n香精需要10g\n需求时间：5.27寄出\n需求价格：400以内', '-', NULL, NULL, NULL, NULL, NULL);
