INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057337791091531777', '0', '0', '16825006662777257', '齐钰', '2026-05-21 13:48:48', '17201757871959617', '赵倩', '2026-05-27 13:49:34', '1', '2057337791380881409', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260521-0022', '2056920311051280386', '船王-推荐香精乌木玫瑰和温木玫瑰-20260520', NULL, '1', '需求明确', '5', '香精库推荐', '202', '身体清洁', '2027-05-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '130-140以内的', '17400514601408872,05035817437137', NULL, '2056631105192157186', '开心', '开心\n17824244552\n浙江省杭州市萧山区宁围街道望京C2座802\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0221876625768', NULL, 'true', NULL, '于姗姗,宣二鹏', '要求：上次乌木玫瑰香精，没有选中，你这边还有合适的推荐吗 另外 温木玫瑰 变色严重，然后我们这边安排皂粒寄过去，预计明天寄出，直接用我们的皂粒打皂寄过来给我们，添香量一般1.2%，但是上次那个温木玫瑰比较淡，我们加到了1.5%。您看看推荐的那几个香精如果也是一样比较淡的话，添加到1.5%试试\n用途：香皂用，不变色，香精50克\n地址收件人; 开心', '-', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2057343658503397377', '0', '0', '17253690046572896', '周宇', '2026-05-21 14:12:06', '113845370124130976', '彭佳庆', '2026-05-22 13:58:54', '1', '2057343658742415361', 'RUNNING', '运行中', '909783222', '评香部', '12', 'YPGD-20260521-0025', '2057308009419202561', '东方鼻子--新品推荐20260521', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500', '113845370124130976,16466317325076496', NULL, '2034161060709122050', '黄子晨', '黄子晨\n17608026017\n浙江省杭州市滨江区长河古镇泽街23-2 黄子晨 17608026017\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '黄子辰项目\nLYP2054JLY LYP2054LLY，现有样每个10g, 还需分给Wildsniff寄样和加香,  本次最多可寄香精2g左右；\n-\n05/22 寄样', NULL, '74100578132328', '2026-05-22 00:00:00', 'false', NULL, '彭佳庆,梁皓', '黄子晨项目1\n-\n推荐LYP2054JLY LYP2054LLY两款香樟树香型\n产品用于喷雾\n需求时间5.21\n寄样15%香水加香产品2~3g\n香精3g\n需求价格：500', '东方鼻子--新品推荐20260521', NULL, NULL, NULL, NULL, NULL);
