INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059807594851033089', '0', '0', '17253690046572896', '周宇', '2026-05-28 09:22:55', '113845370124130976', '彭佳庆', '2026-09-02 11:52:00', '1', '2059807595119411201', 'RUNNING', '运行中', '909783222', '评香部', '30', 'YPGD-20260528-0004', '2059546834954575874', '上海运动服饰品牌--香片仿香20260527', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"香包-酒精浸泡.xlsx\",\"timestamp\":\"GfS5L3lIqdfrJ0nbqGzS\",\"size\":13006,\"secret\":null,\"fileId\":\"33fd6452-b686-4ea6-a934-22a8fed5f6f9\",\"showSize\":\"13KB\",\"fileClass\":\"iconBox excelBox\"}]', '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '350', '113845370124130976,16466317325076496', NULL, '2059545551136841730', '菲菲', '菲菲\n13504734443\n上海上海市松江区九亭镇松港工坊1栋2楼 13504734443 菲菲\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '继续在 LYA2432BLY 该版本上做修改，需要用花香做柔化\n需要提供三个方向，需要10%无火加香产品\n有出口需求需注意法规！', 'LYA2432ALY-药檀1\nLYA2432CLY-药檀3\n\nLYA2432DLY-药檀4（藤条） LYA2432ELY-药檀5（藤条） LYA2432FLY-药檀6（藤条）\n\nLYA2432ILY-药檀9（藤条） LYA2432JLY-药檀10（藤条）\n\nLYA2432GLY-药檀7（藤条）LYA2432HLY-药檀8（藤条）', 'SF1572353142265', '2026-09-02 00:00:00', 'false', NULL, '彭佳庆,梁皓', 'Loranzo介绍\n上海某运动服饰品牌仿香项目\n根据客户提供香包标样进行萃取分析仿香\n已联系客户提供10g标样\n气味类似檀香33+药香苦感\n产品用于无火藤条和蜡烛\n需要10%无火加香产品\n需求价格350左右\n需求时间：6.10', '上海运动服饰品牌--香片仿香20260527', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059813071815139329', '0', '0', '17253690046572896', '周宇', '2026-05-28 09:44:40', '113845370124130976', '彭佳庆', '2026-06-15 16:17:07', '1', '2059813072079323138', 'RUNNING', '运行中', '909783222', '评香部', '12', 'YPGD-20260528-0005', '2059567858823684098', '上海寄舟--个护香型新品推荐20260527', NULL, '1', '需求明确', '5', '香精库推荐', '202', '身体清洁', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '113845370124130976,16466317325076496', NULL, '2059565895910383618', '李伟佳', '李伟佳\n13816153729\n上海市黄浦区延安东路175号旺角广场1502室，李伟佳13816153729\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '绯红乌木 -- 暂无仿香\n\n06/15 备注\n需求样品价格较高，已与销售沟通确认，先行请客户选香；', NULL, 'SF0226238287267', NULL, 'false', NULL, '彭佳庆,梁皓', '寄上海办Gary\n根据客户提供三调进行推荐\n每款推荐3个香型\n柑橘果香花香\n头香：西柚，青绿香，香橙，苹果\n中调：菠萝，大黄，铃兰\n底蕴：花香，麝香                         \n可选拿破仑之水、绿意盎然\n\n描述：花香香草木香琥珀 \n头 香：天竺葵，苦橙叶，玫瑰 \n中 调：丁香，玫瑰，檀香，乌木 \n底 蕴：焦糖，香草，广藿香，琥珀，麝香，香根草\n可选绯红乌木、血色之木\n\n应用类型：沐浴油、喷雾、护理油\n需求价格：300以内\n需求时间：5.29寄上海办', '寄舟', NULL, NULL, NULL, NULL, NULL);
