INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059896301155213313', '0', '0', '16455177663846080', '常晓爽', '2026-05-28 15:15:24', '16455177663846080', '常晓爽', '2026-07-07 17:37:10', '1', '2059896301431980033', 'SUCCESS_END', '成功结束', '909783222', '评香部', '9', 'YPGD-20260528-0033', '2059879779334578178', '述之有味--大地之母创香20250528', NULL, '99', '关闭', '1', '客户新品开发', '301', '个人香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000', '113845370124130976,16466317325076496', NULL, '2034161061422153730', '肖小姐', '肖小姐\n18566186055\n四川省成都市锦江区锦官驿街道 详细地址: 青莲上街5号附10号述之有味\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20-25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, '大地之母-阳光：茶 柑橘方向，添加柠檬香桃木，藏红花醛，奇华酮\n大地之母-绿洲：添加乳香、榄香、没药，天竺葵，广藿沉香\n样品加香量20%，同时寄出 人类祖母-取暖 的香水', 'SF5135130225909', NULL, 'false', NULL, '彭佳庆,梁皓', '四川省成都市锦江区锦官驿街道  青莲上街5号附10号 述之有味  肖小姐 18566186055\n气味想象：\n山西的麦子，黄土高坡阳光充足，充满了小麦的甘香；\n木头与膏腴：姥姥的家有种木头黑黑、油腻，那是常年生活留下的膏腴，是岁月的油脂，气味像酥油、也\n像羊脂羊膏。\n气味颜色是红色，大地母亲的画像会联想到寺庙佛像，充满慈悲地看着众生。\n可以有山茶花、红枣和普洱茶的融合。\n香精价位：2000 左右，售价跟浮沉浪和过乌一致。\n需要20%香水加香产品\n需求时间：5.28\n需求价格：2000', '述之有味大地之母创香', '2', '加香', NULL, NULL, NULL);
