INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059914683862704130', '0', '0', '16825006662777257', '齐钰', '2026-05-28 16:28:27', '17201757871959617', '赵倩', '2026-06-16 11:36:52', '1', '2059914684118499329', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260528-0042', '2059882985456361473', '嘉美化妆-香水工单-20260528', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-28 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0227529173280', NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各20克\n\n【岚・苍柏 —— 祁连煮雪听松】\n意境：清晨祁连山，雪后松林，铁壶煮雪，水汽氤氲，炉灰余温。\n前调：冷杉叶的清苦 + 刚剥开的橘子皮（不带甜），背景有微弱的水汽感（像煮雪时壶嘴冒出的蒸气）\n中调：湿松针 + 潮湿泥土 + 微弱的烟熏（像远处烧柴的烟，不是焦油味）\n后调：旧木头 + 微苦的树脂（像安息香，但不甜） + 快要熄灭的炭火余温（无烟）\n不想要出现的味道：任何甜味、浓烈柠檬、糖果、暖感，花香、粉感、甜味、刺鼻烟熏，香草、琥珀、皮革、明显甜暖', '岚・苍柏 —— 祁连煮雪听松', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059915237825404929', '0', '0', '16825006662777257', '齐钰', '2026-05-28 16:30:39', '17201757871959617', '赵倩', '2026-06-16 11:59:15', '1', '2059915238039257089', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260528-0043', '2059882985456361473', '嘉美化妆-香水工单-20260528', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-28 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0227529173280', NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各20克\n\n【岚・惊鸿 —— 蓬莱踏浪问潮】\n意境：蓬莱海边，少年独立潮头，海风冷冽，外冷内热。\n前调：冷冽海风（类似海盐 + 臭氧，但不腥） + 鲜姜的辛辣感（干净，不暖）\n中调：海岸边的鼠尾草 + 淡淡薰衣草（冷感草本），背景有清亮的水润感（像溪流，不晕）\n后调：干净的雪松木 + 几乎察觉不到的皮肤温度感（无甜），留香贴肤\n不想出现的味道：甜、暖、老式古龙水、晕水生，甜花香、脂粉、暖意，甜、粉、皮革、浓木', '岚・惊鸿 —— 蓬莱踏浪问潮', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059915674884464641', '0', '0', '16825006662777257', '齐钰', '2026-05-28 16:32:23', '17201757871959617', '赵倩', '2026-06-17 09:44:55', '1', '2059915675052179458', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260528-0044', '2059882985456361473', '嘉美化妆-香水工单-20260528', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-28 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '6.16邮寄', NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各20克\n\n【岚・锦书 —— 留园煎花读帖】\n前调：黑加仑的微甜果香（像咬破新鲜浆果） + 柑橘的清亮，整体清爽不齁\n中调：玫瑰和牡丹的花瓣感（像新鲜花瓣，非干花） + 旧书纸的淡墨香（干燥、微尘感）\n后调：干净的浅色木头（像铅笔芯的雪松味） + 麝香的柔和基底（无粉感），甜味几乎消失\n不想出现的味道：糖果甜、热带水果、浓果汁，浓脂粉、老式花露水、甜腻花香，浓木、皮革、广藿香药味', '岚・锦书 —— 留园煎花读帖', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059918118431449090', '0', '0', '16825006662777257', '齐钰', '2026-05-28 16:42:06', '17201757871959617', '赵倩', '2026-06-16 11:59:06', '1', '2059918118829850625', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260528-0045', '2059882985456361473', '嘉美化妆-香水工单-20260528', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-28 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0227529173280', NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各20克\n\n【岚・疏影 —— 颐和路裁月拂尘】\n意境：南京颐和路，秋夜梧桐影，民国女子端庄清冷。\n前调：清透的佛手柑（像刚切开，不带甜） + 微弱的青绿感（紫罗兰叶）\n中调：深红色的玫瑰（像老式胭脂，不甜） + 广藿香的泥土药感 + 极淡的旧皮革（像老书封面）\n后调：广藿香和雪松的木质底 + 琥珀带来的温润（无甜），像陈年衣柜的气味\n不想出现的味道：甜、水果糖、暖，果味、浓艳脂粉，香草、皮革', '岚・疏影 —— 颐和路裁月拂尘', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059918706212823042', '0', '0', '16825006662777257', '齐钰', '2026-05-28 16:44:26', '17201757871959617', '赵倩', '2026-06-17 09:44:48', '1', '2059918706380537858', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260528-0046', '2059882985456361473', '嘉美化妆-香水工单-20260528', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-28 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '6.16邮寄', NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各20克\n\n【岚・寒玫 —— 黄山打雾独坐】\n意境：黄山晨雾，空山石阶，一株野玫独自开，雾散无痕。\n前调：凉凉的豆蔻药感 + 苦艾的青苦 + 山雾的湿润（像清晨雾气）\n中调：极淡的冷玫瑰（像高山野玫，只留一丝花香） + 纸莎草的干燥木质 + 雾感（不甜）\n后调：干燥的雪松木 + 麝香的洁净底（无粉），像雾散后石头上残留的冷木香\n不想出现的味道：任何甜、暖、水果，任何甜、暖、粉、红玫瑰浓香，任何甜、暖、残留花香', '岚・寒玫 —— 黄山打雾独坐', NULL, NULL, NULL, NULL, NULL);
