INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059922829075243009', '0', '0', '16825006662777257', '齐钰', '2026-05-28 17:00:49', '17201757871959617', '赵倩', '2026-06-15 13:14:51', '1', '2059922829268123649', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260528-0054', '2059565257604423681', '嘉美化妆品-推荐香精-20260527', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-27 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '价格350以内', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各15克 收件人郭思敏\n\n【祁连融雪】\n意象祁连山巅的积雪在清晨开始融化，第一滴水从冰凌上落下，渗入草原，唤醒沉睡的土地。空气清冽，带着雪水、冷杉和远处牧场的淡淡奶香。气质清冽、纯净、初醒。像清晨推开窗户时的那一口深呼吸。\n前调：融雪水汽、冷雾、微量薄荷\n中调：冷杉、青草、淡淡奶香（高原牧场）\n后调：雪松、白麝香、龙涎', '祁连融雪', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059923341329784834', '0', '0', '16825006662777257', '齐钰', '2026-05-28 17:02:51', '16825006662777257', '齐钰', '2026-05-28 17:02:51', '1', '2059923341572997122', 'CANCEL', '作废', '909783222', '评香部', '1', 'YPGD-20260528-0055', '2059565257604423681', '嘉美化妆品-推荐香精-20260527', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-27 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '价格350以内', '0549274114954944,17400514601408872', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各15克 收件人郭思敏\n\n【丹霞流火】\n意象正午的丹霞，阳光直射在红色山体上，大地像在燃烧。热浪从地面升腾，空气中是干燥的泥土、矿物和一丝若有若无的野草焦香。气质热烈、神秘、原始。像大地深处的心跳，像时间在燃烧。\n前调：干燥岩石、粉红胡椒、藏红花\n中调：广藿香、没药、干燥的草木\n后调：皮革、劳丹脂、琥珀', '丹霞流火', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2059923843207618561', '0', '0', '16825006662777257', '齐钰', '2026-05-28 17:04:50', '16825006662777257', '齐钰', '2026-06-10 13:36:11', '1', '2059923843400499201', 'SUCCESS_END', '成功结束', '909783222', '评香部', '2', 'YPGD-20260528-0056', '2059565257604423681', '嘉美化妆品-推荐香精-20260527', NULL, '99', '关闭', '1', '客户新品开发', '301', '个人香氛', '2026-07-27 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '价格350以内', '0549274114954944,17400514601408872', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, 'false', NULL, '王鑫,于姗姗', '详见附件 用途 香水 各15克 收件人郭思敏\n\n【莫高觉色】\n意象洞窟里，手电筒的光照在壁画上，千年的颜色一下子活过来。朱砂、石青、金箔——它们等了多久，才等到这一刻被人看见。气质神秘、绚烂、唤醒。像黑暗里突然亮起的光，像被遗忘的梦重新想起。\n前调：藏红花、微量无花果、朱砂般的暖意\n中调：乳香、没药、蓝莲花的幽深\n后调：檀香、龙涎香、琥珀', '莫高觉色', NULL, NULL, NULL, NULL, NULL);
