INSERT INTO `w_bo_gd_20250707155940` VALUES ('2060190566049603586', '0', '0', '16275212368889684', '赵文雅', '2026-05-29 10:44:42', '17201757871959617', '赵倩', '2026-06-16 15:37:09', '1', '2060190566297010177', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260529-0007', '2057311598682267650', '山东名联香精推荐26-05-21', NULL, '1', '需求明确', '5', '香精库推荐', '401', '宠物护理', '2027-05-21 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '02461210300720808373', NULL, '2057308131741884417', '孙宗军', '孙宗军\n18396716868\n山东省临沂市费县胡阳镇北尹村工业园8号山东名联生物科技有限公司\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '已邮寄', NULL, NULL, NULL, '余鹏程', '1、请安排“茉莉”和“柠檬”味的香型，油质、水质（用于宠物除臭剂，需无色）和粉末（用于宠物洗护产品，类似爆炸盐）都需要，每个类型尽量各安排3款，液体香精价位100~150以内，粉末60~80左右；\n2、请推荐爆款洗护香型3~5款，用于宠物玩具清洗液，需油质，价位150以内\n3、爆款喷雾香型5款，用于宠物喷雾，需水质，不要有颜色，价位100左右\n4、爆款爆炸盐香型5款，用于宠物洗护产品，价位80左右\n*标签请注明“产品名称、油质/水质”', '宠物护理', '3', '粉末', NULL, NULL, NULL);
