INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061378338148016129', '0', '0', '17253690046572896', '周宇', '2026-06-01 17:24:29', '050363634136321790', '逯柏松', '2026-09-04 10:18:44', '1', '2061378338382839810', 'SUCCESS_END', '成功结束', '909783222', '评香部', '8', 'YPGD-20260601-0081', '2061346700357754881', '云中月桂+桂花JDL-爆香提升（宋朝）重要', NULL, '6', '输单', '1', '客户新品开发', '302', '空间香氛', '2026-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"桂花JDL2710.xlsx\",\"timestamp\":\"50xg3i2OVPSwxNSipZfg\",\"size\":16192,\"secret\":null,\"fileId\":\"b2dd35df-2cb2-4bfd-be36-7be1ef347e39\",\"showSize\":\"16KB\",\"fileClass\":\"iconBox excelBox\"},{\"fileName\":\"云中月桂.xlsx\",\"timestamp\":\"yjOfjbOODYcBGZZ9gdwP\",\"size\":15653,\"secret\":null,\"fileId\":\"9d8dabdf-fe25-461f-9375-bd9e79e6f445\",\"showSize\":\"15KB\",\"fileClass\":\"iconBox excelBox\"}]', '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '220', '113845370124130976,050363634136321790', NULL, '2034161060021256193', '鲸鱼', '鲸鱼\n17395712317\n浙江省杭州市滨江浙江省杭州市滨江区长河街道笨鸟De第一园区D座6楼前台  鲸鱼 17395712317\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '云中月桂/桂花JDL 仿香\n- 先仿香，后加香基提升扩香；\n\n06/09 日志：原版降价后，加香基', 'LYA2435ALY-云中月桂1，LYA2436ALY-桂花1', '74100603680960', '2026-06-09 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '两款香型仿香：提升空间爆发力\n1.云中月桂-加茶香香基,想要桂花+茶香(整体爆发力要比标样明显提升）；加香10%（异构体系）；用DPMA溶剂+异构溶剂\n2.桂花JDL-增加爆发力就好 （尽量不改变香气），沟通下看看哪款爆香香基适合；加香10%（异构体系）；用DPMA溶剂+异构溶剂\n\n香精：10ml\n应用：无火（异构体系）\n价格：220以内\n收件人：鲸鱼', '宋朝-云中月桂/桂花DL 仿香_爆香提升(重要)_260601', '1', '无', NULL, NULL, NULL);
