INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061383734338215937', '0', '0', '16825006662777257', '齐钰', '2026-06-01 17:45:56', '17201757871959617', '赵倩', '2026-06-11 10:28:13', '1', '2061383734518513666', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260601-0087', '2059565257604423681', '嘉美化妆品-推荐香精-20260527', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-07-27 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '价格350以内', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5137514723343', NULL, NULL, NULL, '王鑫,于姗姗', '详见附件 用途 香水 各15克 收件人郭思敏\n\n【丹霞流火】\n意象正午的丹霞，阳光直射在红色山体上，大地像在燃烧。热浪从地面升腾，空气中是干燥的泥土、矿物和一丝若有若无的野草焦香。气质热烈、神秘、原始。像大地深处的心跳，像时间在燃烧。\n前调：干燥岩石、粉红胡椒、藏红花\n中调：广藿香、没药、干燥的草木\n后调：皮革、劳丹脂、琥珀', '【丹霞流火】', '1', '无', NULL, NULL, NULL);
