INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061386928678199297', '0', '0', '16455177663846080', '常晓爽', '2026-06-01 17:58:37', '17201757871959617', '赵倩', '2026-06-18 09:56:05', '1', '2061386929072406530', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260601-0089', '2056941287788994562', '欧菲丽生物-推荐香精-20260520', NULL, '1', '需求明确', '5', '香精库推荐', '207', '其他个人护理', '2027-05-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '17400514601408872,05035817437137', NULL, '2057014658904055809', '晁工', '晁工\n13363950390\n陕西省西安市浐灞生态区咸宁东路24号长安时间.西安灯泡厂\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5137669533540', NULL, NULL, NULL, '于姗姗,宣二鹏', '有没有 这几个品牌的仿香产品\n观夏、野兽派、独特艾琳、且悠\n30–40岁｜月季主调 × 花香+木香+幻想香｜香型方案\n 整体气质：优雅成熟、温柔有距离感、带一丝梦幻朦胧，不甜腻、不幼稚，适配30–40岁轻熟女日常/通勤/轻社交。\n用途：成人用品润滑油，香精各10克\n这4个品牌推荐，爆款香精推荐3款左右。每一个品牌另外一个客户有需求的这个brief的话，根据客户需求做几款或推荐几款香精，嗯，推荐5款吧\n特别要求:不能有日化香精那种刺鼻的气味，这是领导特别提出来的\n邮寄给晁工', '欧菲丽润滑油推荐', '1', '无', NULL, NULL, NULL);
