INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061651592926420994', '0', '0', '16825006662777257', '齐钰', '2026-06-02 11:30:18', '17201757871959617', '赵倩', '2026-07-01 13:24:51', '1', '2061651593295462402', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260602-0032', '2061301914905042946', '船王-粉末的香精-20260601', NULL, '1', '需求明确', '5', '香精库推荐', '105', '其他家庭护理', '2027-06-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '17400514601408872,05035817437137', NULL, '2056631105192157186', '开心', '开心\n17824244552\n浙江省杭州市萧山区宁围街道望京C2座802\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5197415385455', NULL, NULL, NULL, '于姗姗,宣二鹏', '粉末的香精，桂花和檀香两种香味有吗，要求是耐酸，用在尿碱溶解剂里面的，或者其他花香也行\n用途洁厕\n各100克\n收件人 开心', '船王-粉末', '3', '粉末', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2061658988075769858', '0', '0', '16275212368889684', '赵文雅', '2026-06-02 11:59:41', '17201757871959617', '赵倩', '2026-06-04 16:30:52', '1', '2061658988323176449', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260602-0033', '2060257982901346306', '夏朵-很多香精对香-20260529', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-05-29 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '仿香价格的话就200左右，coco是130块钱左右的', '17400514601408872,05035817437137', NULL, '2061657505825513474', '吴黎昌', '吴黎昌\n18137665155\n河南省郑州市管城区南三环赣江路蓝佩路十里铺新村二号院\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0228457800675', NULL, NULL, NULL, '于姗姗,宣二鹏', '这几款呢，先对香，如果能对出来，相似度很高的话，就直接寄样品，然后如果对不出来的话，就方向\n仿香价格的话就200左右，coco是130块钱左右的，直接找一个就行\n用途 酒店香氛\n香精各10克\n收件人吴黎昌', '对香推荐', '1', '无', NULL, NULL, NULL);
