INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062446074827595777', '0', '0', '16455177663846080', '常晓爽', '2026-06-04 16:07:17', '17201757871959617', '赵倩', '2026-06-10 17:19:11', '1', '2062446075033059329', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260604-0032', '2062371602770649089', '仙迪刷酸清爽沐浴慕斯', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体清洁', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '待确认', '1638968357988946', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '何家文', 'LCC2177ALC，更改溶剂，并加入苔藓等有潮湿氛围感的原料\n沐浴慕斯，然后主打一个刷酸刷酶，然后去掉身上鸡皮的这个概念。然后希望在夏天比较热的时候去主推，所以这个味道要相对比较清新比较清爽，然后有一点带酸味，然后有一种雨后的这种苔藓的这种留香\n清爽、自然、舒适\n1）普宁的青梅-酸酸的雨后苔藓\n2）牛油果\n3）其他方向杨桃、白葡萄酒', '仙迪沐浴慕斯', '1', '无', NULL, NULL, NULL);
