INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062718323304378370', '0', '0', '17253690046572896', '周宇', '2026-06-05 10:09:06', '113845370124130976', '彭佳庆', '2026-10-27 15:01:19', '1', '2062718323543404545', 'RUNNING', '运行中', '909783222', '评香部', '17', 'YPGD-20260605-0014', '2062387560184766465', '柔山--山竹香氛创香修改20260604', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000左右', '113845370124130976,16466317325076496', NULL, '2057740365871407106', '荣奇奇', '荣奇奇\n18621812720\n上海市浦东新区勤政路88弄16号402室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '方向1 -- 偏清雅；方向2 -- 偏果香；\n\n07/07 -- LYP2131DLY 微调 追加尾调软绵果肉（奶感的）', 'LYP2131CLY-悠然海岸3（瓜）LYP2131DLY-悠然海岸4（果）\nLYP2131FLY-山竹1（香水）\nLYP2131GLY-山竹2（香水）-原样反打', 'SF1572353133715', '2026-10-27 00:00:00', NULL, NULL, '彭佳庆,梁皓', '上海浦东新区勤政路88弄16号402室 Gigi 18621812720\n根据客户需求进行创香修改\nLYP2131ALY 作为山竹的主体，做两个方向创香调整\n方向1：增加铃兰、密瓜的瓜瓤感不需要太甜腻\n方向2：可根据调香师、评香师需求进行创作\n产品用于香氛喷雾与香水内\n需要提供20%香水加香产品\n需求价格：1000左右\n需求时间：6.18', '柔山--山竹香氛创香修改20260604', '1', '无', NULL, NULL, NULL);
