INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062775538275004418', '0', '0', '17253690046572896', '周宇', '2026-06-05 13:56:27', '17201757871959617', '赵倩', '2026-06-18 14:39:47', '1', '2062775538509836290', 'RUNNING', '运行中', '909783222', '评香部', '10', 'YPGD-20260605-0047', '2062757991509078017', '不蟹--海洋木质调推荐20260605', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500', '113845370124130976,16466317325076496', NULL, '2054826672351305730', '韩-高尚领域', '韩-高尚领域\n13818000683\n上海市普陀区曹杨路1788号高尚领域T9栋212室 韩 13818000683\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '请优先试闻香气； LYP757ALY -- IFRA 10A 3.75%；\n----\n06/12 反馈\nFLC2010AFL --改溶剂为 ACM；', NULL, 'SF0220938234683', NULL, NULL, NULL, '彭佳庆,梁皓', '高尚领域--韩\n此为客户Brief\n前调是清冽的柠檬马鞭草和微咸的海盐，像那阵穿透蓝调时刻的凉风，唤醒空气的湿润质地。\n中调是核心的蓝色氛围——薰衣草带来金属般清冷的光泽，紫罗兰贡献粉质的花香和微甜绿意，再以鸢尾的泥土感和木质调支撑结构，仿佛凝视那片渐深的蓝色天幕。\n后调是归于平静的柔软：白麝香包裹一切，留下洁净的肌肤感；雪松提供干燥木质的骨架；零陵香豆则透出一点琥珀色的暖意——提醒你，蓝调之后，灯火将起。\n推荐带有蓝色联想的香气\n需要海洋木质调\n另需要LYP1050ALY 类似蓝风铃气味的推荐\n应用品类喷雾 蜡烛 香包 香卡\n需要选择有库存的样品\n需求价格500\n需求时间：6.8寄出', '不蟹--海洋木质调推荐20260605', '1', '无', NULL, NULL, NULL);
