INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062783663027728386', '0', '0', '16455177663846080', '常晓爽', '2026-06-05 14:28:45', '17201757871959617', '赵倩', '2026-06-16 11:35:53', '1', '2062783663254171650', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260605-0054', '2061687389155188737', '锦意-洗发水-20260605非常着急', NULL, '1', '需求明确', '1', '客户新品开发', '201', '头发洗护', '2027-06-02 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '110元左右', '17400514601408872,05035817437137', NULL, '2061688553456230401', '辛宁', '辛宁\n18802017559\n广东省佛山市三水区大塘镇佛泽美妆科技园 A8栋1楼（嘉宁）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5197098934409', NULL, NULL, NULL, '于姗姗,宣二鹏', 'DHR1394ADH	，改日化配方并降价，加入甜橙和橙花元素\n用途：洗护，发膜，精油  ，每款香精成分，也要合规，洗发水、冲洗型发膜/护发素属于IFRA 7B类（冲洗型美发产品）；\n免洗护发素/精油属于7A类（驻留型美发产品）。\n中性标签，30克左右，香型见图片：香型是三种味道复配\n1.树莓&百香果&茉莉\n2.椰子&芒果&白玫瑰\n…\n收件人 辛宁', '锦意洗发水', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2062784674962288641', '0', '0', '16825006662777257', '齐钰', '2026-06-05 14:32:46', '17201757871959617', '赵倩', '2026-06-11 15:41:20', '1', '2062784675268423682', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260605-0048', '2062454983822893057', '嘉美-推荐希腊无花果EDT等香精-20260604', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2027-06-04 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '0549274114954944,17400514601408872', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5137514723343', NULL, NULL, NULL, '王鑫,于姗姗', '1：希腊无花果EDT\n对标香型：蒂普提克「希腊无花果」\n体感：周末晒太阳的松弛感、自然不做作、男女皆可但更讨喜于女性\n前调：无花果叶（青绿但要柔）+ 轻柑橘提亮\n中调：无花果果肉（水润）+ 轻奶雾感（非常克制）\n后调：白麝香 + 柔木（留香骨架）\n优化点:\n绿叶无花果别太青：避免“青汁/折断树枝汁液”的生涩\n奶感只做“奶雾”：避免“防晒霜/椰奶甜品/奶糖”联想\n尾调用“白麝香 + 柔木”撑留香：让它贴肤耐闻、但不厚重\n避免西普底：不要用重广藿香/橡木苔/香根草去撑（会把松弛感做脏做苦）\n香水2：玫瑰荔枝EDT\n对标香型基底（参考香）：佩德玛利「黛丽娜」\n体感：一闻就觉得“好闻、精致、适合约会/送礼”，但不甜腻、不冲鼻\n前调：荔枝（果肉水润）+ 轻清爽果酸（克制）\n中调：玫瑰花瓣 + 牡丹/水润花束（提升透明感）\n后调：白麝香 + 柔木（干净收尾）\n优化点：\n荔枝做“水润果肉感”，不要糖精甜、不要酸到刺\n玫瑰做“新鲜花瓣感”，避免皂感玫瑰油/药感玫瑰\n尾调必须干净：用白麝香+柔木收住，不要厚重香草甜与过多琥珀\n\n香水3：清新花果EDT\n对标香型基底（参考香）：祖·玛珑「英国梨与小苍兰」\n体感：通勤不出错、干净耐闻、\n前调：清脆梨（带皮的清爽感）+ 轻柑橘\n中调：小苍兰/牡丹一类轻花束（不粉不厚）\n后调：白麝香 + 柔木 + 一点点轻琥珀（只做支撑）\n优化点：\n梨要清脆带皮，不要甜腻熟梨\n花香做“轻花束”，别粉别厚\n尾调支撑留香：用白麝香+柔木+一点点轻琥珀即可\n\n\n香水4：白床单慵懒EDT\n对标香型基底（参考香）：梅森马吉拉「慵懒周末」\n体感：干净床单、白衬衫、贴肤白麝香；松弛但更“洁净”\n前调：轻醛香（干净空气）+ 轻清爽果/花提亮\n中调：透明白花/轻鸢尾雾感（克制，避免粉）\n后调：柔白麝香 + 柔木（干净耐闻）\n优化点：\n避免像洗洁精/消毒水：醛香不要尖锐\n白麝香要柔软：不要粉尘、不要动物感\n尾调用柔木撑留香，广藿香存在感压到很低\n\n\n三.香水EDP\n香水1：白茶桂花贴肤麝香EDP\n对标香型（参考香）：宝格丽「白茶」思路（干净茶香）\n体感：轻东方、干净、松弛、男女可用\n既能给入门者“好闻不出错”，也能让爱好者觉得“耐闻、有质感”\n前调：白茶清香 + 轻柑橘提亮（非常克制）\n中调：桂花花瓣气息（轻、透、非甜）+ 轻白花/轻茶韵\n后调：白麝香 + 柔木为主，琥珀点到为止\n优化点：：\n白茶做“清香+微暖”，不要苦涩\n桂花只做“花瓣气息”：增加中国识别点，但不要甜腻桂花糖\n尾调必须贴肤：白麝香+柔木为主，琥珀点到为止\n用途;香水\n各15克', '嘉美需求推荐', '1', '无', NULL, NULL, NULL);
