INSERT INTO `w_bo_gd_20250707155940` VALUES ('2063803670104846338', '0', '0', '17253690046572896', '周宇', '2026-06-08 10:01:53', '113845370124130976', '彭佳庆', '2026-06-23 15:01:31', '1', '2063803670339670017', 'RUNNING', '运行中', '909783222', '评香部', '8', 'YPGD-20260608-0003', '2062733351080374273', '芬寸--田园主题推荐20260605', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500~800', '113845370124130976,16466317325076496', NULL, '2037362401694695425', 'Peggie', 'Peggie\n18779270160\n上海市黄浦区SOHO复兴广场B座607 Peggie 18779270160\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '06/23 日志 -- 添加销售需求样 16 sku;', NULL, 'SF5137407589357', NULL, NULL, NULL, '彭佳庆,梁皓', '寄上海办Gary收\n根据客户需求推荐6~8款田园主题香氛\n目前客户在选取香气主题搭配，产品会应用于香水内\n销售推荐：\nLYP1555CLY 青瓜\nYQP017AYQ 甜菜根\n产品用于香水\n需求价格500~800\n只寄香精即可\n需求时间：6.12寄上海办Gary收', '芬寸--田园主题推荐20260605', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2063808138682773505', '0', '0', '17253690046572896', '周宇', '2026-06-08 10:19:39', '113845370124130976', '彭佳庆', '2026-07-28 16:12:07', '1', '2063808138921791490', 'RUNNING', '运行中', '909783222', '评香部', '21', 'YPGD-20260608-0005', '2062850929626918913', '璞菏--伊甸之果、棉花糖81推荐修改20260605', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200以内', '113845370124130976,16466317325076496', NULL, '2062847647814725633', '简汇青', '简汇青\n15026703626\n上海市奉贤区环城西路3111号-8号璞菏化妆品有限公司（放入丰巢柜边上的专用蓝色框）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '样1# 在头香调中将柑橘香气表现力提升约30至 40%，侧重凸显明亮感与清透鲜爽度，而非甜感。整体要求在前调拥有更突出的灵动鲜活、沁凉清爽的嗅觉体验，同时保留海滨繁花系列标志性花香基调。\n样2# 将柑橘香气表现力提升约 40%-50%\n需要样 20-30g， 最晚 07/28 寄样\n*** 本项目为 出口单，需看好法规 \n-------------\n07/28 客户需求紧急，优先安排寄样，同步查验法规。\n--------\nLYB1670CLY Beach Blossom  修改；\n项目时间紧迫，06/09 寄样，同步请翟姐查看国际法规；\n-------\n07/02  LYP1670ELY  修改，230元，50g, 07/06出样', 'LYP1670DLY-伊甸之果4（原）LYP1670ELY-伊甸之果5（花） LYP1670FLY-伊甸之果6（果）\nLYP1670GLY-伊甸之果7（香水）\n\nLYP1670ILY-伊甸之果9（香水）LYP1670JLY-伊甸之果10（香水）\n', '74100603681625', '2026-07-28 00:00:00', NULL, NULL, '彭佳庆,梁皓', '上海市奉贤区环城西路3111号-8号璞菏化妆品有限公司（放入丰巢柜边上的专用蓝色框），简汇青，15026703626\n---\n应客户需求进行仿香推荐和修改\n\n出口至美国的香体喷雾用产品，其中含高比例酒精添加，加香量6%；\n需要符合出口美国的相关法务要求！！！！！！！！！\n\n需注意IFRA10A类以及4类加香量，以及美国出口法规（欧盟法规&加州法案关于身体喷雾相关是否符合）\n\nLYB1670CLY Beach Blossom 直接寄样需要20~30g\nLCP2100ALC Yum Boujee Marshmallow 需要做降价溶剂优化需要寄样20~30g\n均需3个方向修改-- 01/花香增强 02/果香增强 03/原版降价\n\n\n此客户为潜力客户需要周一尽快安排寄样\n需求价格：200以内\n需求时间：6.9寄出\n产品用于身体喷雾', '璞菏--伊甸之果、棉花糖81推荐修改20260605', '1', '无', NULL, NULL, NULL);
