INSERT INTO `w_bo_gd_20250707155940` VALUES ('2064228911419437058', '0', '0', '17253690046572896', '周宇', '2026-06-09 14:11:39', '050363634136321790', '逯柏松', '2026-09-04 10:29:18', '1', '2064228911616512001', 'SUCCESS_END', '成功结束', '909783222', '评香部', '12', 'YPGD-20260609-0033', '2064223629872148481', '清梦三花修改260609-逐本', NULL, '5', '赢单', '1', '客户新品开发', '201', '头发洗护', '2026-07-10 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400', '113845370124130976,050363634136321790', NULL, '2034161060763648001', '金秀', '金秀\n15216875508\n浙江省杭州市萧山区金鸡路与平澜路交叉口北协和辉丰大厦A座25楼电梯出门向右(逐本研发)  金秀15216875508，\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '06/16 反馈\n需加强基料的遮盖力，做2个方向--01/原版加强；02/ 原版加绿意 或柑橘果香加强版；\n\n*** 清雅白花（加花）-- LYP1656BLY : LYS2114FLY = 1:1 复配', 'LYS2114ELY-清雅白花5（面霜）第二次-LYS2114FLY-清雅白花6、LYS2114GLY-清雅白花7', 'SF1574204101117', '2026-06-18 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '这两款香精我们这边已经试过加到base中了，目前最大的问题是加到1%了都遮不住基料味，需要增强香精对基料味道的掩盖，但是香气的爆发性、香调感觉不要变。两款-（LYS2114ALY清梦三花1；LYS2114CLY清雅白花3）\n\n应用：护发精油\n价格：400\n香精：15ml\n寄金秀', '逐本_清梦三花修改_260609', '1', '无', NULL, NULL, NULL);
