INSERT INTO `w_bo_gd_20250707155940` VALUES ('2065265953255444482', '0', '0', '17253690046572896', '周宇', '2026-06-12 10:52:29', '050363634136321790', '逯柏松', '2026-09-20 17:21:25', '1', '2065265953469349890', 'SUCCESS_END', '成功结束', '909783222', '评香部', '8', 'YPGD-20260612-0014', '2065263756639719425', '26主题下券推荐-予里山人', NULL, '5', '赢单', '1', '客户新品开发', '301', '个人香氛', '2026-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '600', '113845370124130976,050363634136321790', NULL, '2034161062168739842', '张丽微', '张丽微\n18603812396\n地址：河南省郑州市高新区 西四环冬青街 企业公园15号楼1302室 收件人 张丽微 18603812396\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '秋冬款，香水，木质基调（与后土一致）, 东方基调，药香元素', 'LYP2061BLY-荷渡慈航1 LYP2449ALY-板定风云1 LYP2438BLY-葫纳清宁1', '74100603680985', '2026-06-26 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '鼓已定--用后土\n后面三款希望与鼓放一起不违和，也有归定安心的中药感香韵\n\n香气方向\n1；葫纳清宁，\n草本木质，东方玄妙感，中药的清明净化感\n\n2板定风云，\n深邃悠远木质，沉稳感，适合冥想安定\n\n荷渡慈航，\n馥郁棉柔，微微水韵，包裹感的母性光辉\n价格；600以内\n香精：15ml\n时间;6月底寄出\n\n地址：河南省郑州市高新区 西四环冬青街 企业公园15号楼1302室 收件人 张丽微 18603812396', '26主题下券推荐-予里山人', '1', '无', NULL, NULL, NULL);
