INSERT INTO `w_bo_gd_20250707155940` VALUES ('2066373803574808577', '0', '0', '16275212368889684', '赵文雅', '2026-06-15 12:14:41', '17201757871959617', '赵倩', '2026-06-18 10:14:20', '1', '2066373803977457666', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260615-0015', '2065325451479339009', '朴一香薰   蜡烛新品推荐', NULL, '1', '需求明确', '3', '双马香精升级', '302', '空间香氛', '2027-06-12 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '1638968357988946', NULL, '2065325397435731969', '朴一手作', '朴一手作\n15820264822\n广东省广州市从化区太平镇神岗珠江国际城C1区11-1-1304【请送上门，谢谢】\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'DXP2362BDX傣味舂 300-400蜡烛', NULL, 'SF5197681253349', NULL, NULL, NULL, '何家文', '该客户只要选中，就会立马下单，麻烦优先推荐一些好的香。\n需求一：DXP2362BDX傣味舂，客户希望能做一个300-400元之间的版本；产品：蜡烛；系统价格：300-400元之间\n需求二：推荐5个方向的香型；产品：蜡烛；系统价格：400元以内\n1、成熟的橘子、血橙，类似于赤霞橘光这种成熟爆汁大橘子的味道\n2、檀香类的味道，比如檀香木33类似的\n3、荷花、莲花、荷塘月色类似的味道\n4、荔枝味（比较还原荔枝本事的清甜的果香，可以有其他的花香，但是不要花大于荔枝）\n5、之前给客户推荐SYC1122ASY葡萄，麻烦看下有没有比这个样品的葡萄味更浓郁，扩香更好一些的葡萄\n\n地址：广东省广州市从化区太平镇神岗珠江国际城C1区11-1-1304【请送上门，谢谢】；朴一手作15820264822', '修改', '1', '无', NULL, NULL, NULL);
