INSERT INTO `w_bo_gd_20250707155940` VALUES ('2066755991562604545', '0', '0', '16455177663846080', '常晓爽', '2026-06-16 13:33:22', '17201757871959617', '赵倩', '2026-06-18 09:04:38', '1', '2066755991977836546', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260616-0012', '2066455166567043073', '（非常紧急）北京丽质华堂香精推荐26-06-15', NULL, '1', '需求明确', '1', '客户新品开发', '205', '面部护肤', '2027-06-15 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '80000', '02461210300720808373', NULL, '2066452775822151682', 'fiona', 'fiona\n15010510565\n北京朝阳区紫檀大厦17层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5197147102904', NULL, NULL, NULL, '余鹏程', '【需求说明】\n香型要求：客户公司主打成分为紫檀木提取物，创始人亦有“紫檀女王”之称。因此希望该系列护肤品能呈现明显且高级的檀香气息，以呼应产品定位。\n香精类型：可为普通香精或复配精油形式。\n目标人群：25–35岁轻熟龄女性。\n产品功效：主打敏感肌抗初老。\n肤感与安全要求：需温和无刺激，符合护肤品添加标准，不影响产品稳定性与安全性。\n\n【推荐逻辑】\n方向一：请推荐是市面上比较高端的沉檀香型（包括商业香和沙龙香）2~4款\n方向二：我司原创的古方复刻香型2~4款，需寄原版（标签标注清楚，跟性价版区分开），同时可做适当降价处理，注意天然油的含量比例\n\n【加香要求】\n用于所有剂型，包括洁面水乳精华面霜身体乳等；\n客户会寄来一点面霜基料，同时评香可根据我司目前可制作的加香小样种类，酌情安排其他类型产品的加香；\n加香量万分之2~5之间，价位控制在8w以内；\n需将香精和加香小样一并寄出，并出具送样清单', '紫檀香型推荐', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2066756837444669442', '0', '0', '16455177663846080', '常晓爽', '2026-06-16 13:36:43', '17201757871959617', '赵倩', '2026-06-18 10:02:46', '1', '2066756837679546370', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260616-0013', '2066455166567043073', '（非常紧急）北京丽质华堂香精推荐26-06-15', NULL, '1', '需求明确', '1', '客户新品开发', '205', '面部护肤', '2027-06-15 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '80000', '02461210300720808373', NULL, '2066452775822151682', 'fiona', 'fiona\n15010510565\n北京朝阳区紫檀大厦17层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5197147102904', NULL, NULL, NULL, '余鹏程', 'DHA1576ADH	，汉宫香方，修改沉香油规格，用最好的沉香油\n【需求说明】\n香型要求：客户公司主打成分为紫檀木提取物，创始人亦有“紫檀女王”之称。因此希望该系列护肤品能呈现明显且高级的檀香气息，以呼应产品定位。\n香精类型：可为普通香精或复配精油形式。\n目标人群：25–35岁轻熟龄女性。\n产品功效：主打敏感肌抗初老。\n肤感与安全要求：需温和无刺激，符合护肤品添加标准，不影响产品稳定性与安全性。\n\n【推荐逻辑】\n方向一：请推荐是市面上比较高端的沉檀香型（包括商业香和沙龙香）2~4款\n方向二：我司原创的古方复刻香型2~4款，需寄原版（标签标注清楚，跟性价版区分开），同时可做适当降价处理，注意天然油的含量比例\n\n【加香要求】\n用于所有剂型，包括洁面水乳精华面霜身体乳等；\n客户会寄来一点面霜基料，同时评香可根据我司目前可制作的加香小样种类，酌情安排其他类型产品的加香；\n加香量万分之2~5之间，价位控制在8w以内；\n需将香精和加香小样一并寄出，并出具送样清单', '紫沉檀护肤推荐', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2066757079414067201', '0', '0', '16455177663846080', '常晓爽', '2026-06-16 13:37:41', '17201757871959617', '赵倩', '2026-06-18 09:04:31', '1', '2066757079632166913', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260616-0014', '2066455166567043073', '（非常紧急）北京丽质华堂香精推荐26-06-15', NULL, '1', '需求明确', '1', '客户新品开发', '204', '面部清洁', '2027-06-15 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '80000', '02461210300720808373', NULL, '2066452775822151682', 'fiona', 'fiona\n15010510565\n北京朝阳区紫檀大厦17层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5197147102904', NULL, NULL, NULL, '余鹏程', '杨贵妃古方调整\n【需求说明】\n香型要求：客户公司主打成分为紫檀木提取物，创始人亦有“紫檀女王”之称。因此希望该系列护肤品能呈现明显且高级的檀香气息，以呼应产品定位。\n香精类型：可为普通香精或复配精油形式。\n目标人群：25–35岁轻熟龄女性。\n产品功效：主打敏感肌抗初老。\n肤感与安全要求：需温和无刺激，符合护肤品添加标准，不影响产品稳定性与安全性。\n\n【推荐逻辑】\n方向一：请推荐是市面上比较高端的沉檀香型（包括商业香和沙龙香）2~4款\n方向二：我司原创的古方复刻香型2~4款，需寄原版（标签标注清楚，跟性价版区分开），同时可做适当降价处理，注意天然油的含量比例\n\n【加香要求】\n用于所有剂型，包括洁面水乳精华面霜身体乳等；\n客户会寄来一点面霜基料，同时评香可根据我司目前可制作的加香小样种类，酌情安排其他类型产品的加香；\n加香量万分之2~5之间，价位控制在8w以内；\n需将香精和加香小样一并寄出，并出具送样清单', '沉檀护肤品', '2', '加香', NULL, NULL, NULL);
