INSERT INTO `w_bo_gd_20250707155940` VALUES ('2068943270838259714', '0', '0', '16275212368889684', '赵文雅', '2026-06-22 14:24:50', '17201757871959617', '赵倩', '2026-07-15 14:30:20', '1', '2068943271119273985', 'RUNNING', '运行中', '909783222', '评香部', '17', 'YPGD-20260622-0019', '2068891319316500482', '艾森推荐粉末焦糊咖啡+香草等-20260622', NULL, '1', '需求明确', '5', '香精库推荐', '401', '宠物护理', '2027-06-22 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '粉末香精每种30克.价格55公斤/公斤', '17400514601408872,05035817437137', NULL, '2068891890320658433', 'KH07-江南THU TRANG 222', 'KH07-江南THU TRANG 222\n19569907668\n广西壮族自治区崇左凭祥市凭祥镇南大路汉邕大夏对面3号仓库(KH07-江南THU TRANG 222)\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '（咖啡+香草）需要咖啡粉末香精15g+香草粉末香精15g混合\n（爽身粉+檀香)需要爽身粉粉末香精15g+檀香粉末香精15g混合\n玫瑰需要30g粉末香精 如果没有香精或者不明白怎么做需要跟销售沟通一下\n', NULL, 'SF0228809971774，SF5194231164736', NULL, NULL, NULL, '于姗姗,宣二鹏', '工单要求：\n客户目前采购一下香精明细如下：（液体香精做成粉末25%含量）\nLJA2097ALJ	咖啡\nLJA2242ALJ	香草	\nLJA1408HLJ玫瑰\nLCA856BLC	粉香\n8435檀香\n客户需求：\n寄样品粉末香精各30克，用于越南客户确认香气。样品需求：\n1.LJA2097ALJ咖啡粉末香精50%+LJA2242ALJ香草粉末香精50%混合后30克，名称打：焦糊咖啡+香草粉末香精\n2.LCA856BLC粉香粉末香精50%+8435檀香粉末香精50%混合后30克，名称打：婴儿爽身粉+檀香粉末香精\n3.LJA1408HLJ玫瑰粉末香精 名称打：玫瑰粉末香精\n\n备注：客户猫砂加两种香精，加香量0.1%，咖啡粉末香精加0.05%，香草粉末香精加0.05%。', '粉末香精', '3', '粉末', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2068946372618342401', '0', '0', '16275212368889684', '赵文雅', '2026-06-22 14:37:09', '17201757871959617', '赵倩', '2026-06-22 15:19:18', '1', '2068946372836442114', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260622-0020', '2068942232001433601', '宠爱一世-推荐花香，浓的-20260622', NULL, '1', '需求明确', '5', '香精库推荐', '401', '宠物护理', '2027-06-22 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '价格100元以下', '17400514601408872,05035817437137', NULL, '2068942561262686209', '王云燕', '王云燕\n18636248868\n大同市平城区开源街永和路千禧御东画卷2-2-103\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF0220109997974', NULL, NULL, NULL, '于姗姗,宣二鹏', '用途;猫砂\n推荐花香，浓的。\n发顺丰着急。发几个浓郁花香的小样。各样发一种，不要各样发几瓶。\n各10克\n大同市平城区开源街永和路千禧御东画卷2-2-103王云燕18636248868', '推荐花香', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2068961528832315394', '0', '0', '17253690046572896', '周宇', '2026-06-22 15:37:23', '113845370124130976', '彭佳庆', '2026-07-27 14:29:16', '1', '2068961529079775234', 'RUNNING', '运行中', '909783222', '评香部', '29', 'YPGD-20260622-0021', '2068940469739442178', '回家本能--仙人掌对香推荐20260622', NULL, '1', '需求明确', '5', '香精库推荐', '203', '身体护肤', '2027-07-11 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '16466317325076496,113845370124130976', NULL, '2034161062130991106', 'Eddy', 'Eddy\n19957842610\n浙江省宁波市海曙区柳汀街297号（星悦中心8号楼）2309   eddy 19957842610\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP1013DLY，客户希望在该版本上做最后一版加青绿调整\n只需提供20g香精即可\n需求时间：7.28\n需求价格400\n\n------------------- 之前信息 -------------------------\nLYP1013ALY  尾调增加油柑的青绿木质涩感，减少水生感，增加香气的层次;\n价格在400以内，需要15%香水加香产品，07/03 之前，个护', 'LYP1013BLY-仙人掌1（香水）LYP1013CLY-仙人掌2（香水）\nLYP1013DLY-仙人掌3（香水）\n\nLYP1013ELY-仙人掌4（香水）', 'SF1574204101657', '2026-07-27 00:00:00', NULL, NULL, '梁皓,彭佳庆', '浙江省宁波市海曙区柳汀街297号（星悦中心8号楼）2309 eddy 19957842610\n根据客户提供标样进行对香推荐\n原CPL香型市场反馈不佳，现找其他市场产品进行参考优化升级已有产品\n客户选取仙人掌元素身体用样品\n销售推荐\nLYP1013ALY\nLYP1388ELY\n香气类似芦荟\n优先推荐有库存的样品\n需求价格：300\n需求时间：6.24\n需要15%香水加香产品\n香精10g', '回家本能--仙人掌对香推荐20260622', '', '', NULL, NULL, NULL);
