INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069687789137416193', '0', '0', '17253690046572896', '周宇', '2026-06-24 15:43:17', '17201757871959617', '赵倩', '2026-07-07 16:59:30', '1', '2069687789451984898', 'RUNNING', '运行中', '909783222', '评香部', '20', 'YPGD-20260624-0009', '2068967005670592514', '愈料精油--木质香型推荐20260622', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2026-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '350左右', '16466317325076496,113845370124130976', NULL, '2068965950618587137', '吴小姐', '吴小姐\n19865577525\n广州市白云区同泰路颐和山庄涵虚阁1座903，吴小姐，19865577525\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2130BLY，LCP1383BLC  -- 价格已超350；\nIFRA 请客户明确使用品类后确认；\n\n06/30 天津寄样 (有两款价格微超350，销售表示可接受）\nLYP2175BLY  -- IFRA 10A 6.5%\nLYP1422BLY\nLCB2065ALC  鹅梨帐中香\n\n06/30 SH 寄样\nLYP1415BLY  -- IFRA 10A 13%\nLYP1585BLY -- IFRA 10A 6.7%', NULL, '74100603680999', '2026-07-07 00:00:00', NULL, NULL, '梁皓,彭佳庆', '广州市白云区同泰路颐和山庄涵虚阁1座903，吴小姐19865577525\n根据客户线下拜访选中香型进行推荐\nLYP1680BLY\nLYP1560BLY\nLYP2130BLY\nLCP1383BLC\n寄样10~20g如天津有库存天津出样20g，如无库存，上海直接寄样10g\n产品用于家具香氛&个护产品内\n需求价格：350左右\n需求时间：6.23', '愈料精油--木质香型推荐20260622', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069697113150705666', '0', '0', '16825006662777257', '齐钰', '2026-06-24 16:20:20', '17201757871959617', '赵倩', '2026-06-29 11:49:54', '1', '2069697113368805377', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260624-0011', '2069656558861537281', '东莞洋葱-推荐香水-20260624', NULL, '1', '需求明确', '3', '双马香精升级', '301', '个人香氛', '2027-06-24 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王鑫,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '130元以内', '0549274114954944,17400514601408872', NULL, '2059828267505901570', '元宝', '元宝\n18520094776\n广州市花都区夏花六路6号嘉汇城东区东17栋1904房\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5110608633547', NULL, NULL, NULL, '王鑫,于姗姗', '推荐130元以内 香水香型\n用于香水\n类似于 毒药 coco  黑鸦片 乌木玫瑰 栀子花  香奈儿 桂花 古龙 檀香 海洋 水蜜桃  草莓蛋糕 浆果\n各10克', '洋葱-草莓蛋糕', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2069712124078182402', '0', '0', '17253690046572896', '周宇', '2026-06-24 17:19:58', '17201757871959617', '赵倩', '2026-07-23 17:13:50', '1', '2069712124367585282', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260624-0013', '2069333851070517249', '星宇昊海--新品蜡烛推荐&修改20260623', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500以内', '113845370124130976,16466317325076496', NULL, '2034161061669617665', '李俊', '李俊\n18117207858\n上海市黄浦区淮海中路 627号WeWork 4F， 18117207858    李俊\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5113156377915', NULL, NULL, NULL, '彭佳庆,梁皓', '1.  蜜瓜+微量的葡萄（不想有化工感）+玫瑰。\n蜜瓜推荐：LYP485ALY、JKC1246DJK、LJC1226BLJ\n\n 2.苔洇碧染，你试试看再给我的两个苔藓味道里，加点青草和雨后泥土的味道吧，现在没有雨后的感觉，只有凉意，没有水汽和湿气。     \n苔藓推荐：LCC1236ALC、LYP1504ALY\n番茄叶推荐：LYC2065ALY、LYP1142BLY\n\n3.  馕与核桃：新疆美食调\n核桃香型推荐：LJP1190ALJ\n\n4.  胡杨红柳： 模拟意象中的胡杨和红柳的味道吧。        大漠苍凉感的木质调+顽强的生命力的感觉（就是干燥中又带着点清新感，类似沙漠绿洲的感觉 ）\n胡杨红柳：LYP2375BLY\n\n5. 生生不息：水润生瓜+竹笋+青涩瓜藤+大地，或者加点之前的松针的味道+藤（那种有点青涩的藤，，加青草或者菊花的那个味道？），  松柏+岩兰草+苔藓+荷花\n瓜香推荐：LYP1555ALY\n\n6. 秦简汉牍：药感墨香木质调（少量的香芒+少量花椒；松烟墨（如何实现？松焦油，松香油？  ）+麝香+丁香；  干燥木质调（柏木、创愈木可以带一点淡淡的干竹子香）\n秦简汉牍：LYP735ALY、LYP1159BLY\n竹香：LYP1652ALY\n\n7. 苍松翠柏  松木+柏树 松针+柏叶 加点松果 松子的味道，也是木质调。\n松针推荐：LYP1468BLY\n优先提供有库存版本\n产品用于蜡烛产品内\n需求价格：500以内\n先推荐香型确认后需要修改\n需求时间：6.26\n寄样地址：上海市黄浦区淮海中路 627号WeWork 4F， 18117207858 李俊', '星宇昊海--新品蜡烛推荐&修改20260623', '1', '无', NULL, NULL, NULL);
