INSERT INTO `w_bo_gd_20250707155940` VALUES ('2071414030970376194', '0', '0', '17253690046572896', '周宇', '2026-06-29 10:02:45', '113845370124130976', '彭佳庆', '2026-07-21 14:18:21', '1', '2071414031352053762', 'RUNNING', '运行中', '909783222', '评香部', '10', 'YPGD-20260629-0007', '2070342259387125762', '东方鼻子--果香、栀子、紫苏薄荷推荐&修改20260626', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,16466317325076496', NULL, '2059530607158845442', '黄子晨', '黄子晨\n17608026017\n浙江省杭州市滨江区长河古镇泽街23-2 黄子晨 17608026017\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP599BLY 夏风苦艾 优化，\n需要在25%香水加香产品中的表现力与香精相似，加浓 加厚度，整体表现线性呈现，与香精感受保持同步。\n\n价格500以内，7/20\n需 25%香水加香产品\n------------------------------之前信息 ----------------------\nLYP612ALY 西柚，LYP1006BLY 柑橘薄荷\n以上两个样【无库存】', 'LYP2471ALY-夏风苦艾5（香水）', 'SF1574204101532', '2027-06-21 00:00:00', NULL, NULL, '彭佳庆,梁皓', '浙江省杭州市滨江区长河古镇泽街23-2 黄子晨 17608026017\n-\n客户需要推荐干净偏纯粹的果香、柑橘香以及栀子香气\n推荐：\nLYP611ALY 葡桃\nLYP612ALY 西柚\nLYP745ALY 杏李黄皮\nLYF867ALY 柳橙\nLYF875ALY 橘子\nLYP1006BLY 柑橘薄荷\nLYP1517BLY 香橼\nLYP1524ALY 绿叶青桔\nYQA007AYQ 夏日栀子\nLYP740ALY 清香栀子\nLYP1684BLY 风神（仿香）\nLYP599BLY 夏风苦艾\n客户产品用于喷雾\n需求价格：400以内\n需求时间：推荐的样品6.30寄出，修改的薄荷紫苏7.8寄出', '东方鼻子--果香、栀子推荐20260626', '', '', NULL, NULL, NULL);
