INSERT INTO `w_bo_gd_20250707155940` VALUES ('2071869773838274561', '0', '0', '17253690046572896', '周宇', '2026-06-30 16:13:42', '113845370124130976', '彭佳庆', '2026-07-01 16:02:00', '1', '2071869774039597057', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260630-0034', '2071869051604291585', '湖北申泰--芦荟、万寿菊产品升级20260630', NULL, '1', '需求明确', '1', '客户新品开发', '207', '其他个人护理', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '87 & 117', '113845370124130976,16466317325076496', NULL, '2034161062143574018', '卢芳', '卢芳\n18565697548\n湖北省咸宁市赤壁市中伙铺镇产业园横二路与纵四路交汇处湖北申泰医疗用品有限公司\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '不需要寄样，优化配方\n-- 桂醛与芳樟醇超出欧标婴儿湿巾用品限用范围，先出配方号 请翟工出法规单即可；', 'LYS1081CLY-芦荟3（水质）\nLYS1082CLY-洋甘菊3（水质）', 'SF1574204101241', '2026-07-01 00:00:00', NULL, NULL, '彭佳庆,梁皓', '不需要寄样\n需求紧急！！！！！！！\n万寿菊（水质）LYP1082ALY \n芦荟（水质）LYP1081ALY\n客户产品使用在婴儿湿巾产品内\n添加量0.1%\n目前桂醛与芳樟醇超出欧标婴儿湿巾用品限用范围需要优化升级该产品\n需求价格：\n芦荟售价：87元\n万寿菊售价：117元\n优化升级版需在该价格内\n需求时间：7.1（需求紧急）', '湖北申泰--芦荟、万寿菊产品升级20260630', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2071895981707743234', '0', '0', '17253690046572896', '周宇', '2026-06-30 17:57:51', '050363634136321790', '逯柏松', '2026-09-20 17:29:10', '1', '2071895981955203074', 'SUCCESS_END', '成功结束', '909783222', '评香部', '6', 'YPGD-20260630-0035', '2071807393464832002', '西屿洗护的主题推荐', NULL, '6', '输单', '1', '客户新品开发', '202', '身体洗护', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '113845370124130976,050363634136321790', NULL, '2059907565130571778', 'Bella', 'Bella\n15257009611\n浙江省杭州市萧山区盈丰街道永晖路233号杭州湾智慧谷10楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '修改推荐，首先查看是否有代表性 天然油，再加香基；\n玫瑰 -- LYP1706ELY	法哈尔玫瑰\n茶 -- LYP958BLY      高贵茉莉\n沉香 -- LYP1115ALY	皇家檀香（性价）\n沉香 -- YMB2004CYM	乌木织锦（个护）\n栀子 -- LYP848ALY	香柠栀子\n佛手 -- LYP1678BLY	香柠檬22\n松 -- LYP770ALY	白松香根\n松 -- LYB662ALY	冷松映月', 'LYB1706HLY-法哈尔玫瑰8（个护）LYB2460ALY-花茶1（个护）LYB1115BLY-皇家檀香2（个护）LYB2179FLY-栀子花1（香水）LYB1678HLY-香柠檬22-7（个护）LYB2457BLY-雪松1（个护）', 'SF1574204101408', '2026-07-10 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '西屿洗护的主题（重要）：\n玫瑰、茶、沉香、栀子、佛手、松木；\n要求：从以往新品洗护推荐套系中选气味合适的，要是没有可自行推荐；要求有爆香香精和留香香基还有有天然油添加\n价格：300\n香精：10ml\n时间：7月8号前寄出\n备注：加香成品打签1.5%，实际加2%\n香精和加香成品一起寄出\n寄bella', '西屿洗护的主题推荐_20260630', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2071897012919324673', '0', '0', '17253690046572896', '周宇', '2026-06-30 18:01:57', '050363634136321790', '逯柏松', '2026-08-12 12:01:11', '1', '2071897013154201602', 'SUCCESS_END', '成功结束', '909783222', '评香部', '7', 'YPGD-20260630-0038', '2071888721757589506', '西屿茉莉无火+洗护（重要）推荐', NULL, '6', '输单', '1', '客户新品开发', '202', '身体洗护', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200--400', '113845370124130976,050363634136321790', NULL, '2059907565130571778', 'Bella', 'Bella\n15257009611\n浙江省杭州市萧山区盈丰街道永晖路233号杭州湾智慧谷10楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYA1597GLY（无火版） -- 爆香香基 + 天然油\nDH160220E (洗护版）-- 爆香香基 + 留香香基 + 天然油\n', 'LYA2459ALY-茉莉花絮1（藤条）LYB2459BLY-茉莉花絮2（个护）\nLYA1597HLY-岭右茉莉1（藤条）LYB1597ILY-岭右茉莉2（个护）', 'SF1574204101408', '2026-07-10 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '西屿茉莉无火+洗护（重要）：\nLYP703ALY（需要改无火版+洗护版）和LYA1597GLY（无火版）DH160220E(洗护版）要求有爆香香基和留香香基还有广西横州小花茉莉天然油添加\n价格：无火200以内，洗护400以内\n香精：10ml\n时间:7月10号前寄出\n备注：无火加香成品打签10%，实际加香12%；洗护加香成品打签1.5%，实际加香2%\n香精和加香成品一起寄出\n寄bella', '西屿茉莉无火+洗护（重要）修改_20260630', '1', '无', NULL, NULL, NULL);
