INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072491809564512257', '0', '0', '17253690046572896', '周宇', '2026-07-02 09:25:27', '113845370124130976', '彭佳庆', '2026-07-23 15:30:03', '1', '2072491809774223362', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260702-0001', '2071845677503074305', '挚物志--果香、茶香香水创香20260630', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"浴见-醒山桃.xlsx\",\"timestamp\":\"89l6uzsH808Is32BeI16\",\"size\":16068,\"secret\":null,\"fileId\":\"503570eb-875f-4cb7-9ce1-028d1b9e1e8d\",\"showSize\":\"16KB\",\"fileClass\":\"iconBox excelBox\"}]', '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '350~650', '113845370124130976,16466317325076496', NULL, '2034161061262770177', '夏甦*', '夏甦*\n13817346604\n上海市闵行区中春路7001号明谷科技园A栋511 夏甦 13817346604\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '两个创香需求\n- 果香，醒山桃 >>> 进样仿香\n- 茶香，小青柑', 'LYP2138CLY-小青柑1（香水）\nLYP1357DLY-西瓜玫瑰1（香水）', '74100603681623', '2026-07-23 00:00:00', NULL, NULL, '彭佳庆,梁皓', '寄样地址：上海市闵行区中春路7001号明谷科技园A栋511 夏甦 13817346604\n\n注意！该项目有两个创香需求！！！！！！！\n\n需求1：客户果香类香水创香\n客户会提供浴见-醒山桃市场样品需要该类型感受的果香香水创香\n具体水果类型可在客户样品提供后确定\n需求价格：350元\n需求时间：暂定7.15（主要看实际香氛的质感）\n需要15%香水加香产品\n\n需求2：茶类香水创香\n该创香为高定线香水，会有出口欧美市场需求，需确认法规！！！！！！！！！\n客户需要小青柑以及滇红茶香香水创香\n先做小青柑以下为小青柑创香思路\n需要有中式感以及香水的层次感以及需要一小部分的大众接受度愉悦度\nLYP1495ALY or LYA2138ALY or LYP1492ALY\n可加重红茶感与青绿感需要体现出中式香氛情节与青绿自然的联结感\n需求价格：650以内\n需求时间：暂定7.17（主要看实际香氛的质感）\n需要15%香水加香产品', '挚物志--果香、茶香香水创香20260630', '1', '无', NULL, NULL, NULL);
