INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072513363220353025', '0', '0', '16455177663846080', '常晓爽', '2026-07-02 10:51:06', '16455177663846080', '常晓爽', '2026-07-21 16:08:03', '1', '2072513363526533122', 'SUCCESS_END', '成功结束', '909783222', '评香部', '2', 'YPGD-20260702-0012', '2072126375019401217', '亿达-调整C30024-0701', NULL, '99', '关闭', '3', '双马香精升级', '201', '头发洗护', '2027-07-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '邢芬,郭治爽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '16855125875633810,04476151371724', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '邢芬,郭治爽', 'C30024 ，调整配方\n客户反映加到洗发水里边稀了，看看能不能修改一版\n  洗发水加香量是0.5%    150元以内\n\n高知朋 17329976779\n广州市白云区钟落潭镇金盆村政农路6号广州亿达化妆品有限公司(实验室收)', 'C30024', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072515640609984513', '0', '0', '16455177663846080', '常晓爽', '2026-07-02 11:00:09', '17201757871959617', '赵倩', '2026-07-10 17:30:04', '1', '2072515640878415873', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260702-0014', '2071979612245577730', '嘉丹婷   复配姜香洗护重新推荐', NULL, '1', '需求明确', '1', '客户新品开发', '201', '头发洗护', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200以内', '1638968357988946,0549274114954944', NULL, '2060194079324463105', '梁小姐', '梁小姐\n18578550060\n肇庆市大旺高新区正隆一街2号 澳雪国际\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5113640769650', NULL, NULL, NULL, '何家文,王鑫', '客户反馈：\nSYB2301ASY客户反馈复合后姜味的特色基本闻不到。客户把半亩花田的一款姜香洗护产品寄到天津，可以参考这款产品的姜气味表现，同时加入搭配果香、姜搭花香这些方向，但整体气味还是以姜为主，不能是其他气味强于姜的气味。', '嘉丹婷姜', '1', '无', NULL, NULL, NULL);
