INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072517074852237314', '0', '0', '16455177663846080', '常晓爽', '2026-07-02 11:05:51', '17201757871959617', '赵倩', '2026-07-10 16:08:18', '1', '2072517075078725634', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260702-0018', '2071977787194855426', '嘉丹婷   洗护香型新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '201', '头发洗护', '2027-06-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '180元/1kg', '1638968357988946,0549274114954944', NULL, '2060194079324463105', '梁小姐', '梁小姐\n18578550060\n肇庆市大旺高新区正隆一街2号 澳雪国际\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5113640769650', NULL, NULL, NULL, '何家文,王鑫', 'DXP2452BDX，加强参考样品柚见雪松\n（1）价格：限制在180元/1kg \n（2）添加量：预计0.4~0.6% \n（3）香型需求：不要找纯果香，纯木质香，要复合型花香型的，必须要有花香调；要爆一点愉悦度高的香型。\n（4）应用产品：澳雪精油香氛系列。前期先落地控油/柔顺洗发水各1款、2款沐浴露、1款发膜（与柔顺洗发水共用香型）；后续考虑延伸至身体乳、手霜。\nPS:寄来4款客户目前内部入选的香型，其中柚见雪松是嘉丹婷老板目前最喜欢的，可供参考，但不要推荐跟这4款风格一样的香型，避免重叠。寄出前需要和王鑫确认没问题再寄出。', '嘉丹婷新品推荐', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072521414329487362', '0', '0', '16275212368889684', '赵文雅', '2026-07-02 11:23:05', '17201757871959617', '赵倩', '2026-07-15 11:32:42', '1', '2072521414555975681', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260702-0019', '2072518114347569154', '金王-仿香项目-雪蕾样品20260702', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-06-29 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"雪蕾.xlsx\",\"timestamp\":\"3sO7XyASPdWmSzjRrr2F\",\"size\":15063,\"secret\":null,\"fileId\":\"c75767e9-d8b0-4326-90aa-7227de29a8c5\",\"showSize\":\"15KB\",\"fileClass\":\"iconBox excelBox\"}]', '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200元/公斤', '17400514601408872,05035817437137', NULL, '2034161064601436162', '京京', '京京\n18354293315\n山东青岛市市南区福泰广场B座24层金王\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5157347319748', NULL, NULL, NULL, '于姗姗,宣二鹏', '仿香项目：\n1.价格200元/公斤以下，客户采购价格180元/公斤。\n2.香精100克\n3.用途挥发液\n4.收件人：京京', '仿香', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072529746117251073', '0', '0', '16455177663846080', '常晓爽', '2026-07-02 11:56:12', '16455177663846080', '常晓爽', '2026-07-02 11:56:12', '1', '2072529746331156481', 'RUNNING', '运行中', '909783222', '评香部', '1', 'YPGD-20260702-0021', '2072221931406348290', 'Yili--山下有松--桂花乌龙沉香香水修改20260701', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2028-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '10000', '113845370124130976,16466317325076496', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '彭佳庆,梁皓', '寄北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n根据客户寄样香精先给客户做25%和20%两个浓度的香水加香产品，做3~5g的香水成品\n取部分香精进GC分析谱图与仿香标样，剩余需寄回给客户\n目前该版本不是最终确认版本Yili会有新的优化版本，此为山下有松第3支香水\n客户目前感觉香气有些甜需要减甜增加桂花花韵，需求有两个方向优化版\n需求1：减甜增桂花，做增加茶感方向\n需求2：减甜增桂花，做增加檀香木方向\n（暂未需要我们先做调整，有该需求可能）\n山下有松品牌方老板喜欢精油感的香气可参考黎明香根草的感觉\n整体香气是桂花+乌龙+沉香+木质\n后续定版后会由我司仿香做成品出货\n需求价格：暂无（预计10000元/kg）\n需求加香量20% 25%两个\n产品用于香水内\n目前该工单为后续项目做准备以及给客户提供加香产品用', 'YILI桂花乌龙', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072568395047358465', '0', '0', '16455177663846080', '常晓爽', '2026-07-02 14:29:46', '17201757871959617', '赵倩', '2026-07-03 16:30:14', '1', '2072568395244486657', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260702-0022', '2066455166567043073', '（非常紧急）北京丽质华堂香精推荐26-06-15', NULL, '1', '需求明确', '1', '客户新品开发', '205', '面部护肤', '2027-06-15 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '80000', '02461210300720808373', NULL, '2066452775822151682', 'fiona', 'fiona\n15010510565\n北京朝阳区紫檀大厦17层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5117620453540', NULL, NULL, NULL, '余鹏程', '1：圣木+沉香 2： 圣木+檀香\n3：寻踪+檀香\n希望在此基础上檀香气味稍微再明显一些~', '紫檀面霜修改', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072570242751516674', '0', '0', '16275212368889684', '赵文雅', '2026-07-02 14:37:07', '16275212368889684', '赵文雅', '2026-07-13 17:10:56', '1', '2072570242990587905', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260702-0025', '2072318064103247874', '（非常紧急）金华百秘圣诞香型推荐26-07-01', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-07-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '02461210300720808373', NULL, '2046836324672954369', '程东', '程东\n17585442263\n浙江省金华市金东区孝顺镇低田工业区学智路721号2栋4楼，金石纸品厂\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5118819682255', NULL, NULL, NULL, '余鹏程', '南瓜 、肉桂、 肉豆蔻 、丁香、南瓜印度奶茶、姜饼、热红酒、橙子丁香、冷杉雪松、薄荷、圣诞甜饼\n以上香型尽可能根据库存做推荐，务必在本周寄出\n其中：南瓜香型，需要尽可能还原美食感，需要透发一些，尽量推荐3款\n用于蜡烛，价位300左右，低了更好', '推荐圣诞香型', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072570417687547906', '0', '0', '16275212368889684', '赵文雅', '2026-07-02 14:37:49', '17201757871959617', '赵倩', '2026-07-03 11:22:48', '1', '2072570417918230530', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260702-0026', '2072318666531131393', '金华百秘宠物友好香氛推荐26-07-01', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-07-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '02461210300720808373', NULL, '2046836324672954369', '程东', '程东\n17585442263\n浙江省金华市金东区孝顺镇低田工业区学智路721号2栋4楼，金石纸品厂\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5118819682255', NULL, NULL, NULL, '余鹏程', '请推荐我厂【宠物友好型香氛】，可参考余和宣之前的项目\n用于无火香氛，价格可以不考虑\n样品标签请备注清楚“宠物友好”\n请注意：三调中不能出现柑橘类、薰衣草、桉叶等元素', '推荐', '1', '无', NULL, NULL, NULL);
