INSERT INTO `w_bo_gd_20250707155940` VALUES ('2072919042284310529', '0', '0', '16455177663846080', '常晓爽', '2026-07-03 13:43:07', '17201757871959617', '赵倩', '2026-07-03 14:26:48', '1', '2072919042506604545', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260703-0007', '2072889259475324930', '广州仙迪   37款独特艾琳仿香', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体清洁', '2027-07-03 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '无', '1638968357988946', NULL, '2034161064022622209', '林丽', '林丽\n13715045975\n广州市从化区太平镇新兴路398号6栋，广州市仙迪生物（上坡保安室）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5114820362443', NULL, NULL, NULL, '何家文', '独特艾琳仿香项目37款、\n艾克斯假期、塞班假日、耳畔铃兰、鎏金之梦、浮靡之光、炽热记忆、雨后桃金娘、游子吟、杜乐丽花园、孜瑰诗集、清澈泉涌、清澈岛屿、你最珍桂、我的少年、苏里南柠、宇宙星辰、漫步初春、北岛流光、春日旷野、光影倾城、清茶琥珀、浮靡之水、灌璨流星、琥珀之钥、空山雪茶、心跳回响、大地森林、繁华花园、橡木苔的夏、欲望宇宙、日落少女、加州柚里、布列塔尼、仲夏和歌山、莱茵河白昼、雨季绿地、纯净之檀\n要求：仙迪未来重点推广的项目，要求相似必须高，价格尽可能控制，不要太高。\n时间：客户希望月底能完成一部分，麻烦安排加急一下。\n\n地址：仙迪林丽收', '独特艾琳仿香', '1', '无', NULL, NULL, NULL);
