INSERT INTO `w_bo_gd_20250707155940` VALUES ('2073983577229348866', '0', '0', '16455177663846080', '常晓爽', '2026-07-06 12:13:12', '17201757871959617', '赵倩', '2026-07-10 14:32:24', '1', '2073983577468420097', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260706-0022', '2072882638380584962', '戈海（屈臣氏）  DH-G812355--DXB2539ADX粉韵樱花  版本修改', NULL, '1', '需求明确', '3', '双马香精升级', '205', '面部护肤', '2027-07-03 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '170', '1638968357988946,0549274114954944', NULL, '2034161061858361346', '居居', '居居\n13922118445\n广州市天河区珠江新城华夏路富力盈通2810室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5115639342187', NULL, NULL, NULL, '何家文,王鑫', 'DH-G812355--DXB2539ADX粉韵樱花 分别用于精华油水相、精华油油相、修颜防晒霜和焕活防晒霜，一共4款产品；\n客户反馈：现在客户反馈两款精华油产品中的香精加在“油相”基体后就出现变蒙，两款防晒霜添加香精都会出现香精气味与防晒剂气味分层的情况（香精压不住防晒剂味道，但是也有香精气味冒出）；\n修改需求：均使用客户提供的基料进行调配和做加香测试\n1、两款香精都要做成亲油版本，溶于基体不浑浊，香精符合法规不含屈臣氏禁用物质（禁用物质在附件）；\n2、水相和油相精华油，油/水/香精的比例为：13%油+87%水+0.2%的香精，就是0.2g的油加在13G的油里，正常工艺操作是香精加到油相，然后油相再倒入水相使用前摇晃均匀即可，所以需要把香精修改成在油相中不浑浊变蒙；\n3、两款防晒霜，香精添加量0.3%，修改后香精能盖住基料的味道，不出现气味分层，尽量香气不要跟原版变化太大；\n4、客户希望交版时间在7月15日前', '粉韵樱花修改', '1', '无', NULL, NULL, NULL);
