INSERT INTO `w_bo_gd_20250707155940` VALUES ('2074378447446069249', '0', '0', '16455177663846080', '常晓爽', '2026-07-07 14:22:17', '17201757871959617', '赵倩', '2026-07-07 16:33:46', '1', '2074378447668363265', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260707-0015', '2059879779334578178', '述之有味--大地之母创香20250528', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-05-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000', '113845370124130976,16466317325076496', NULL, '2034161061422153730', '肖小姐', '肖小姐\n18566186055\n四川省成都市锦江区锦官驿街道 详细地址: 青莲上街5号附10号述之有味\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20-25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5114632615211', NULL, NULL, NULL, '彭佳庆,梁皓', '四川省成都市锦江区锦官驿街道  青莲上街5号附10号 述之有味  肖小姐 18566186055\n气味想象：\n山西的麦子，黄土高坡阳光充足，充满了小麦的甘香；\n木头与膏腴：姥姥的家有种木头黑黑、油腻，那是常年生活留下的膏腴，是岁月的油脂，气味像酥油、也\n像羊脂羊膏。\n气味颜色是红色，大地母亲的画像会联想到寺庙佛像，充满慈悲地看着众生。\n可以有山茶花、红枣和普洱茶的融合。\n香精价位：2000 左右，售价跟浮沉浪和过乌一致。\n需要20%香水加香产品\n需求时间：5.28\n需求价格：2000', '大地之母修改版', '2', '加香', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2074379458826981378', '0', '0', '16455177663846080', '常晓爽', '2026-07-07 14:26:18', '17201757871959617', '赵倩', '2026-07-20 14:34:16', '1', '2074379459107995650', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260707-0016', '2073963801656414209', '东莞汶乐  洗衣液香型推荐', NULL, '1', '需求明确', '5', '香精库推荐', '101', '传统织物洗护', '2027-07-06 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '100-150元/公斤', '1638968357988946,0549274114954944', NULL, '2073961950995271681', '叶小姐', '叶小姐\n13988996888\n中堂镇槎滘恒丰路1号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5113654212355', NULL, NULL, NULL, '何家文,王鑫', '产品：洗衣液（添加量： 0.7%）  \n价格：100-150元/公斤\n需求：檀木、雪松、紫鸢尾、白花调、佛手柑  注意变色问题。同时客户不要果香味的香精，重要要留香，客户重点是非常关注留香问题', '汶乐洗衣液推荐', '1', '无', NULL, NULL, NULL);
