INSERT INTO `w_bo_gd_20250707155940` VALUES ('2075117748475645954', '0', '0', '17253690046572896', '周宇', '2026-07-09 15:20:00', '113845370124130976', '彭佳庆', '2026-07-14 12:26:21', '1', '2075117748718911489', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260709-0026', '2074802529203376129', '粉合--茶香手霜、洗手液推荐&修改20260708', NULL, '1', '需求明确', '5', '香精库推荐', '203', '身体护肤', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200左右', '113845370124130976,16466317325076496', NULL, '2056975729211432961', 'Gary', 'Gary\n13701974151\n上海市长宁区愚园路锦园805弄15号 Gary13701974151\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYA2281CLY 茶瀑，LYP2282BLY 琼轮，降价到200块\n07/13', 'LYS2281ELY-茶瀑5（面霜）LYS2281FLY-茶瀑6（面霜）\nLYS2282DLY-琼轮4（面霜）LYS2282ELY-琼轮5（面霜）\n', '销售送样', '2026-07-14 00:00:00', NULL, NULL, '彭佳庆,梁皓', '销售线下拜访\n根据客户需求LYA2281CLY 茶瀑，LYP2282BLY 琼轮\n做降价至200左右\n需要两个方向修改\n方向1：降价至200左右\n方向2：降价至200左右+茶香爆香香基\n\n另需推荐禅茶、白茶香型各一款\n前期推荐按有库存递样上海办Gary收\n后期修改需求价格：250以内\n客户加香量0.8%\n需求时间：7.13销售自提见客户', '粉合--茶香手霜、洗手液推荐&修改20260708', '1', '无', NULL, NULL, NULL);
