INSERT INTO `w_bo_gd_20250707155940` VALUES ('2076845104689041410', '0', '0', '16275212368889684', '赵文雅', '2026-07-14 09:43:54', '113845370124130976', '彭佳庆', '2026-07-15 17:25:22', '1', '2076845105028775938', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260714-0003', '2076844061485944834', '川函香氛  LYP2375BLY 柳叶与琥珀调整版本（准项目）', NULL, '1', '需求明确', '3', '双马香精升级', '302', '空间香氛', '2027-07-14 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300-330元之间', '1638968357988946', NULL, '2077321183623106561', '张启川', '张启川\n13192751223\n清远市清城区高新技术产业开发区科技创新园创兴大道18号天安智谷智造基地T1栋3楼309A\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, 'LYA2375CLY-柳叶与琥珀3（藤条）\nLYA2375DLY-柳叶与琥珀4（香卡）', '74100603681613', '2026-07-15 00:00:00', NULL, NULL, '何家文', '准项目，客户已选中该型号：LYP2375BLY 柳叶与琥珀\n根据客户需求做两个版本（标签备注：香挂片版本和无火香薰版本），注意这两个调整版本的整体香韵不能有特别大的变化。\n需求一：做一个留香时间更久的版本，客户是要用在是车载纸质香片、皮革香挂、纳米钙香片，要求是一个月内车里任然有香味，同时产品主要投放在新马地区高温\n需求二：做一个爆发力更好的版本。客户是用在无火香薰，用的溶剂是ACM。\n时间：周五前17号需要寄出\n地址：清远市清城区高新技术产业开发区科技创新园创兴大道18号天安智谷智造基地T1栋3楼309A  张启川13192751223', '调整配方', '1', '无', NULL, NULL, NULL);
