INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077280676389834754', '0', '0', '16825006662777257', '齐钰', '2026-07-15 14:34:42', '17201757871959617', '赵倩', '2026-07-22 13:01:32', '1', '2077280676637294593', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260715-0037', '2077265788644872194', '嘉美-推荐香精-20260715', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-07-15 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '17400514601408872,0549274114954944', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5114357475419', NULL, NULL, NULL, '于姗姗,王鑫', '【底儿：紫邂逅】\n客户创香需求：\n魏紫 原生香气特征\n药感甜香 + 紫罗兰粉质 + 木质冷香，香气温润厚重、贵气成熟、辨识度极高。\n香水定位\n东方紫花香 EDP（晚宴高端线）\n•风格：端庄、成熟、贵气、神秘紫韵\n•人群：30 + 女性、晚宴、商务正式场合\n•季节：秋冬最佳，春秋微凉天气也很绝\n\n留香（15% 香精 EDP）\n•皮肤：9–11 小时（厚重留香）\n•衣物：13–17 小时（紫香 + 药感持久）\n•尾调：2–3 天（木质琥珀残留强）\n\n意境文案\n「魏紫・紫宸凝芳」\n紫为贵，沉为尊。\n千瓣凝霞，暗香沉郁，是宫廷深处的端庄，亦是岁月沉淀的从容华贵。\n\n调香配方思路\n•前调：紫罗兰叶、葡萄柚、丁香（冷润开场）\n•中调：魏紫牡丹、鸢尾、玫瑰（紫调粉质甜香）\n•尾调：广藿香、沉香、檀香、龙涎、麝香（厚重贵气底）\n香水定位\n东方紫花香 EDP（晚宴高端线）\n•风格：端庄、成熟、贵气、神秘紫韵\n•人群：30 + 女性、晚宴、商务正式场合\n•季节：秋冬最佳，春秋微凉天气也很绝\n\n留香（15% 香精 EDP）\n•皮肤：9–11 小时（厚重留香）\n•衣物：13–17 小时（紫香 + 药感持久）\n•尾调：2–3 天（木质琥珀残留强）\n\n意境文案\n「魏紫・紫宸凝芳」\n紫为贵，沉为尊。\n千瓣凝霞，暗香沉郁，是宫廷深处的端庄，亦是岁月沉淀的从容华贵。\n\n调香配方思路\n•前调：紫罗兰叶、葡萄柚、丁香（冷润开场）\n•中调：魏紫牡丹、鸢尾、玫瑰（紫调粉质甜香）\n•尾调：广藿香、沉香、檀香、龙涎、麝香（厚重贵气底）\n用途香水\n各10克', '创香', '1', '无', NULL, NULL, NULL);
