INSERT INTO `w_bo_gd_20250707155940` VALUES ('2077692515091206145', '0', '0', '17253690046572896', '周宇', '2026-07-16 17:51:12', '17201757871959617', '赵倩', '2026-07-22 17:00:13', '1', '2077692515447717890', 'RUNNING', '运行中', '909783222', '评香部', '12', 'YPGD-20260716-0038', '2077319989106298881', '轩芷--中东香水推荐20260715', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400左右', '113845370124130976,16466317325076496', NULL, '2034161062818856962', '郑娇易*', '郑娇易*\n15900583253\n上海市徐汇区桂平路333号6号楼306室，郑娇易 15900583253\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '法规已查看，暂时不用考虑Hala', NULL, 'SF5119557107414', NULL, NULL, NULL, '彭佳庆,梁皓', '寄：Joy\n客户需要推荐香水用香精\n一共有木质、东方、柑橘、花香+ 粉红胡椒四个主题\n每个主题需要推荐2~3款，额外lattafa也可推荐几款符合需求的\n留香期望8h以上\n不喜欢的香味：刺鼻感、过甜、动物感、药感！！！！\n优先推荐今年内研仿香能匹配的香型做推荐\n客户加香量20~35%\n需求价格：400左右\n需要20%香水加香产品\n客户要出口中东，需确认符合欧盟法规！！！！！！\n后期潜在halal认证\n需求时间：7.22前寄出\n需求价格：400左右', '轩芷--中东香水推荐20260715', '2', '加香', NULL, NULL, NULL);
