INSERT INTO `w_bo_gd_20250707155940` VALUES ('2079399211807248386', '0', '0', '17253690046572896', '周宇', '2026-07-21 10:53:00', '113845370124130976', '彭佳庆', '2026-10-21 17:25:29', '1', '2079399212088229889', 'RUNNING', '运行中', '909783222', '评香部', '14', 'YPGD-20260721-0005', '2079110741012500482', '芬寸--翡翠青柚、伊塔克香水油调整20260720', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000以内', '113845370124130976,16466317325076496', NULL, '2112834980622090242', '周雯倩', '周雯倩\n15664110927\n上海市奉贤区环城西路3111号8号璞菏（放入丰巢边上的蓝色专用框）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LYP2327CLY -- IFRA 5A 15%', 'LYP2327CLY-翡翠青柚3（香水）\nLYP2322CLY-永恒之乡伊塔克3（香水）\nLYP2322DLY-永恒之乡伊塔克4（香水）', 'SF1572353133221', '2026-10-21 00:00:00', NULL, NULL, '彭佳庆,梁皓', '寄：Peggie\n客户目前对该两款香型需要应用于香水油内\n\n01/ 翡翠青柚LYC2327BLY\n需求保留原本香气内的果肉多汁感增加果皮的涩感\n需要突出香气的层次感\n\n02/ LYC2322BLY 伊塔克\n需要两个方向修改\n\n方向1：\n增强目前版本内的青花椒感做  辛香浆果  方向调整！！！\n\n方向2：\n增强目前版本内的青花椒感做  草本木质  方向调整！！！\n\n\n客户香水油最大添加量35%需注意法规\n需求价格：1000以内\n需求时间：最晚7.31寄出\n【2026.10.20更新：LYP2322CLY客户基础油base修改目前与香精适配度不符需优化极性适配度\n已联系客户提供base\n需求时间：10.21\n需要30g香精】', '芬寸--翡翠青柚、伊塔克香水油调整20260720', '1', '无', NULL, NULL, NULL);
