INSERT INTO `w_bo_gd_20250707155940` VALUES ('2079838304932433921', '0', '0', '16455177663846080', '常晓爽', '2026-07-22 15:57:48', '17201757871959617', '寄样员', '2026-10-10 17:21:22', '1', '2079838305163083778', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260722-0022', '2079470475091611650', '26年报H2主动产品开发', NULL, '1', '需求明确', '4', '主动产品开发', '301', '个人香氛', '2026-12-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '王晔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '不限', '17127345845433575', NULL, '2100880544085561346', '双马', '双马\n15692282990\n自提\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '内研，不寄样', NULL, NULL, NULL, '王晔', '主品类香水，第二品类个护\n26AW气味上海主题：另辟蹊径\n年报洞察衍生主题：重建美好关系之活色生香\n在2026年度洞察主题之上，以“生命力”为核心主题，探索生命是如何通过不同形式被感知与表达：一方面回望人的内在世界，从万物果实所承载的不同生命气质中，映照人在与世界相遇、交融与体验过程中产生的情绪、欲望，探索这些复杂而真实的生命经验如何塑造自我、彰显人的存在力量。另一方面重新连接自然万物，从难以被定义和驯化的野性生命状态中，发现人与自然殊途同归的原始能量。\n20260721——目前确定下来概念的来自两个系列的4款香型。系列概念、产品概念、香气与风格参考均在以下链接的钉钉表格中。后续会补充。\nhttps://alidocs.dingtalk.com/spreadsheetv2/lxBXz5zluz389l2Y/edit?docKey=vBPlN5jdzrVP3OdG&dentryKey=lxBXz5zluz389l2Y&type=s', '万味之果-青木瓜', '1', '无', NULL, NULL, NULL);
