INSERT INTO `w_bo_gd_20250707155940` VALUES ('2080212041578024962', '0', '0', '17253690046572896', '周宇', '2026-07-23 16:42:54', '17201757871959617', '寄样员', '2026-08-03 10:40:07', '1', '2080212041905143810', 'RUNNING', '运行中', '909783222', '评香部', '8', 'YPGD-20260723-0029', '2079407555544584193', 'KKV--洗护个护香氛推荐20260721', NULL, '1', '需求明确', '5', '香精库推荐', '203', '身体护肤', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '250~400', '113845370124130976,16466317325076496', NULL, '2079404102499930113', '赵怡', '赵怡\n18586537710\n东莞市南城街道袁屋边隐山路35号KK集团4楼 赵怡 18586537710 （收）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'IFRA 需明确具体应用品类后，再查看确认；', NULL, 'SF5118568999620', NULL, NULL, NULL, '彭佳庆,梁皓', '寄：东莞市南城街道袁屋边隐山路35号KK集团4楼 赵怡 18586537710 （收）\n需要推荐30~40款香型\n【产品人群信息】\n人群：一线、新一线25~40岁独立女性。\n香型偏好：花香木质调、花果香（偏果香但不要太甜腻）、芳香、纯木质调\n其他关键词：天然、疗愈、质感、高级、层次感。\n香精价格：250~400元/kg\n应用产品：护发精油、沐浴油、身体油、护手霜。\n注意溶剂以及适配性和IFRA法规\n最终会选2~3款香作为主推串联个护产品，备选3~5款作为扩展sku。\n需要寄样30g~50g统一寄出量\n需求时间：分两批寄样，有库存的优先寄出，无库存的排单大样统一寄出\n\nLYP1670BLY 伊甸之果\nLYP1680BLY 木韵稻香\nLYP1681BLY 郁金花园\nLYP2175BLY 自我\nLYP2281BLY 茶瀑\nLYP2282BLY 琼轮\nLYP2375BLY 柳叶与琥珀\nLJP2468BLJ 紫罗兰30\nLYP2376BLY 克罗地亚\nLYP2386BLY 化蝶\nSYB2563ASY 芒果叶\nDXB2535AJK 鎏金蜜脂\nDXB2449ADX 檀木薄荷\nYMB2004CYM 乌木织锦\nDXP2286BDX 雾境琥珀\nDXB2472ADX 红梨与克什米尔木\n绯红无界 LJB2396BLJ\n桃粉花座 JKP2414AJK\n浮木苦橙 LCC2153ALC\n春绿 LYP851GLY\n游廊木兰 JKP1463FJK\n惊鸿茉莉 LYP958BLY\n粉桃葡萄 LCB2178ADH\n天竺青提 DXB2402BDX\n气泡柑橘 ZXB2037AZX\n奶油玫瑰 LCP2049BLC\n周末派对 YMP2001BYM\n落日可可 JKP2306AJK\n昂蒂布之夏 LYP1678BLY\n爱丁堡砂岩 HDB2340AHD\n远山辛绿 LYP2015BLY\n琥珀香根 LYP1732BLY\n绒花暖木 SYB2412CSY\n荆棘礼赞 DXP2166BDX', 'KKV--洗护个护香氛推荐20260721', '1', '无', NULL, NULL, NULL);
