INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081636077906399233', '0', '0', '16275212368889684', '赵文雅', '2026-07-27 15:01:31', '17201757871959617', '赵倩', '2026-07-27 16:59:21', '1', '2081636078187380737', 'RUNNING', '运行中', '909783222', '评香部', '3', 'YPGD-20260727-0033', '2081592568511959041', '厦门宫老板香精推荐26-07-27', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-07-27 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '02461210300720808373', NULL, '2081592138797125633', '蔡总', '蔡总\n15985917874\n福建省厦门市集美区软件园c01\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '自提', NULL, NULL, NULL, '余鹏程', '样品库有现货的、线香新品各准备10g，今天由销售带走\n4-8款就行', '厦门宫老板', '1', '无', NULL, NULL, NULL);
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2081637029258432513', '0', '0', '16825006662777257', '齐钰', '2026-07-27 15:05:17', '16825006662777257', '齐钰', '2026-08-06 17:06:52', '1', '2081637029463916546', 'SUCCESS_END', '成功结束', '909783222', '评香部', '12', 'YPGD-20260727-0034', '2081630740692307969', '广州锦鲤--沙龙香氛推荐20260727', NULL, '99', '关闭', '5', '香精库推荐', '301', '个人香氛', '2027-07-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '3500以内', '113845370124130976,16466317325076496', NULL, '2081979411610963969', '吴先生', '吴先生\n17688493910\n广州市天河区体育东横街南雅苑小区52号102房\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5111264712355', NULL, NULL, NULL, '彭佳庆,梁皓', '寄：吴先生\n需要推荐12~15款沙龙香水or原版大牌仿香\n可推荐客户我们目前已有的自主创香系列\n也可推荐客户举例的市场大牌香氛\nChanel ：5号、19号、法式别墅、康朋街31号、22号、力度\n娇兰： 午夜飞行、阵雨过后、蓝调时光、一千零一夜、6号鸢尾\nJacomo 积歌蒙： 寂静、心脏\nDiptyque 蒂普提克： 肌肤之花\n卢丹氏： 银霭鸢尾花\nMarc-Antoine 马克·安托万·巴罗斯： 伽倪墨得 Ganymede\nNaomi Goodsir： 灰烬鸢尾、胶木之夜、骏马之躯\nLes Indemodables 非凡之香： 珍珠鸢尾、听觉西普\nXerjoff 希爵夫：鸢尾、都灵21\nSanta Maria Novella 圣塔玛利亚诺维拉：Melograno 石榴\nGrossmith 格罗史密斯：嗅闻微风、金色西普、女王钻禧、日本莲花与百合、婚约\n\n客户产品用于香水内，香水加香量15~20%\n需求价格：3500以内\n需求时间：8.7\n需要香水加香产品', '锦鲤香水推荐', '1', '无', NULL, NULL, NULL);
