INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085554280961396737', '0', '0', '16455177663846080', '常晓爽', '2026-08-07 10:31:03', '17201757871959617', '寄样员', '2026-08-07 16:26:03', '1', '2085554281259098113', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260807-0006', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '自提', NULL, NULL, NULL, '梁皓,彭佳庆', '根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '杭州云韵', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085563533331779585', '0', '0', '16455177663846080', '常晓爽', '2026-08-07 11:07:49', '17201757871959617', '寄样员', '2026-08-12 17:31:59', '1', '2085563533583343617', 'RUNNING', '运行中', '909783222', '评香部', '8', 'YPGD-20260807-0007', '2085561360879439873', '重要  加急  戈海（曼秀雷敦）  LCP031DLCA--DH-A09536云荒大陆剔除铃兰醛', NULL, '1', '需求明确', '3', '双马香精升级', '202', '身体洗护', '2027-08-07 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '无', '1638968357988946,0549274114954944', NULL, '2034161061858361346', '居居', '居居\n13922118445\n广州市天河区珠江新城华夏路富力盈通2810室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5111477954640', NULL, NULL, NULL, '何家文,王鑫', '重要重要重要重要  加急加急加急加急\n型号：LCP031DLCA--DH-A09536云荒大陆\n背景：曼秀雷敦选中的项目，测试了半年，准备要下单，目前发现有铃兰醛，需要紧急做一个不含铃兰醛的版本，同时需要气味尽可能做到和原版一致。\n产品：洗护沐', 'LCP031DLCA剔除铃兰醛', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085564098669432834', '0', '0', '16455177663846080', '常晓爽', '2026-08-07 11:10:04', '17201757871959617', '寄样员', '2026-08-07 15:26:05', '1', '2085564098895831041', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260807-0009', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '自提', NULL, NULL, NULL, '梁皓,彭佳庆', 'DXS2119DDX，换溶剂为藤条\n根据客户需求进行推荐递样\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '杭州云韵推荐', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085566709514620929', '0', '0', '17253690046572896', '周宇', '2026-08-07 11:20:26', '17201757871959617', '寄样员', '2026-08-18 14:42:37', '1', '2085566709787156482', 'RUNNING', '运行中', '909783222', '评香部', '14', 'YPGD-20260807-0011', '2084856782135480322', '弗止--阴阳师ip联名家居香氛推荐20260805', NULL, '1', '需求明确', '5', '香精库推荐', '3022', '挥发液', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '16466317325076496,113845370124130976', NULL, '2055159748134658049', 'jiojio', 'jiojio\n15178065377\n上海市静安区江场路1447号云芯科创中心T1号楼19楼DO事业部 jiojio，15178065377\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'DXP685BDX	裁缝 -- IFRA 10A 法规调整至 15%', NULL, 'SF5119782708546', NULL, NULL, NULL, '梁皓,彭佳庆', '寄：jiojio\n根据客户5位角色需求推荐角色香\n需要每位角色推荐2支\n由于该客户品类用于香薰类故需要优化香气表现力：香气强度与扩香能力\n客户市场参照样如无仿香可提供类似香气感受的大牌香氛\n寄出前请确认加香产品强度与香气表现\n\n1、帝释天\n前调：香柠檬、杜松子、醛香\n中调：薰衣草、小豆蔻、小苍兰/莲花/忍冬\n后调： 雪松、琥珀、白麝香\n对标大牌香氛：艾克卡帕-白苔、古特尔-忍冬\n销售推荐：紫罗兰30\n\n2、阿修罗\n前调： 苦艾、生姜、藏红花\n中调： 黑胡椒、没药、焚香\n后调： 广藿、麝香/皮革、沉香\n对标大牌香氛：解放橘郡-情水（龙与玫瑰）、TF-隐秘没药\n\n3、酒吞童子\n前调：柚子、花椒、小豆蔻\n中调：酒香元素、烟草、李子\n后调： 橡木、皮革、劳丹脂\n对标大牌香氛：Byredo-最后一刻，帝国之香-俄罗斯琥珀\n销售推荐：单一麦芽、巴塔哥尼（草原落鲸）\n\n4、茨木童子\n前调： 柑橘、青椒、灰烬/火药\n中调： 玫瑰、肉桂、公丁香\n后调： 冷杉、乳香、雪松\n对标大牌香氛：川久保玲-惊艳绿、4711-原始森林古龙\n销售推荐：近期做过的香樟木\n\n5、鬼切\n前调：金属、臭氧、血橙\n中调：鸢尾根、黑胡椒、茶叶\n后调：橡木苔、白麝香、广藿\n对标大牌香氛：潘海利根-裁缝、帝门特-暴风雨\n\n需求价格：200~300元\n需要10%无火加香产品50g，香精3g左右感受一下即可\n需求时间：8.19前寄出', '弗止--阴阳师ip联名家居香氛推荐20260805', '2', '加香', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085567329726353410', '0', '0', '17253690046572896', '周宇', '2026-08-07 11:22:54', '113845370124130976', '彭佳庆', '2026-08-11 15:30:24', '1', '2085567329965334530', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260807-0013', '2085286168265478146', '赫艾迩--咖啡香型面膜用推荐20260806', NULL, '1', '需求明确', '1', '客户新品开发', '204', '面部洗护', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300~400', '16466317325076496,113845370124130976', NULL, '2085285337755537410', 'Gia', 'Gia\n18851900552\n上海上海市黄浦区瑞金二路街道 详细地址: 瑞金大厦-南侧楼6楼 Gia 18851900552\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '01/ 参考 LYP2210ALY 咖啡豆\n02/ 花香咖啡--参考瑰夏：清新橙花香 与明亮卡曼橘，以及咖啡坚果尾韵🌰', 'LYS2210FLY-咖啡6（水质）\nLYS2210GLY-咖啡7（水质）', '74100603681649', '2026-08-11 00:00:00', NULL, NULL, '梁皓,彭佳庆', '根据客户需求进行递样\n需要2款咖啡水性香型推荐\n用咖啡香基作为主题\n产品用于面膜内\n价格需求：300~400\n需求时间：8.12\n寄样10g香精即可', '赫艾迩--咖啡香型面膜用推荐20260806', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2085568979044126721', '0', '0', '16455177663846080', '常晓爽', '2026-08-07 11:29:27', '17201757871959617', '寄样员', '2026-08-07 16:44:47', '1', '2085568979325050881', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260807-0014', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '自提', NULL, NULL, NULL, '梁皓,彭佳庆', 'ZXB2037AZX，替换溶剂+香水柠檬base\n根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '云韵藤条推荐', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
