INSERT INTO `w_bo_gd_20250707155940` VALUES ('2087769482180153346', '0', '0', '16455177663846080', '常晓爽', '2026-08-13 13:13:28', '17201757871959617', '寄样员', '2026-08-18 17:26:26', '1', '2087769482372997122', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260813-0007', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5112383081990', NULL, NULL, NULL, '梁皓,彭佳庆', 'LJP294DLJ加点壤香，可以提高到300以内\n根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', 'LJP294DL加点壤香', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2087769660513570818', '0', '0', '16455177663846080', '常晓爽', '2026-08-13 13:14:11', '17201757871959617', '寄样员', '2026-08-18 17:26:10', '1', '2087769660718997506', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260813-0008', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5112383081990', NULL, NULL, NULL, '梁皓,彭佳庆', 'FLC2399CFL加点壤香，减点酚类物质\n根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '听雨FLC2399CFL加点壤香，减点酚类物质', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2087770172109606914', '0', '0', '16455177663846080', '常晓爽', '2026-08-13 13:16:13', '17201757871959617', '寄样员', '2026-08-18 17:53:40', '1', '2087770172298256385', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260813-0009', '2085305490958438401', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', 'LCP2018ALC 降价到300 场景：茶室 气味需求有明显的茶调，又不要太单一。既可以是西湖龙井的香，也可以是潮汕单从或是铁观音的香，也可以是广西茉莉花茶的..让人仿佛在茶园或者是茶室，在亲身接触茶叶亦或是在烹制一壶茶，茶香萦绕，只觉得舒心宁静', NULL, 'SF5112383081990', NULL, NULL, NULL, '梁皓,彭佳庆', '根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '空清推荐', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
