INSERT INTO `w_bo_gd_20250707155940` VALUES ('2091729322191605761', '0', '0', '05035817329389', '刘畅', '2026-08-24 11:28:28', '050358172196', '刘扬', '2026-09-18 17:15:05', '1', '2091729322434781185', 'RUNNING', '运行中', '12377314', 'DHFF', '21', 'YPGD-20260824-0013', '2091710182273830914', '逐云檀2.0仿香-逐本', NULL, '1', '需求明确', '1', '客户新品开发', '2071', '其他', '2026-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"云檀-2.0.xlsx\",\"timestamp\":\"evmbjcUJHnmNrk1RrVSS\",\"size\":20974,\"secret\":null,\"fileId\":\"7b696221-cbaf-4d5c-b5fc-d4ca6b7fd2fa\",\"showSize\":\"20KB\",\"fileClass\":\"iconBox excelBox\"}]', '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '650', '050363634136321790,113845370124130976', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, 'LYS2487DLY-云檀2.0-4（膏霜）\nLYS2487ELY-云檀2.0-5（膏霜）\nLYS2487FLY-云檀2.0-6（膏霜）    \n LYS2487GLY-云檀2.0-7（膏霜）9月18号刘畅逯柏松送样', '销售自提', '2026-09-04 00:00:00', NULL, NULL, '逯柏松,彭佳庆', '云檀2.0香精仿香，要求相似度\n价格：650\n香精：10ml\n应用：卸妆油\n时间：8月28号\n【2026.9.8更新：\n两版寄过来的云檀香精我们复配成云檀2.0香的配方，加在云檀膏里测试了下，还是要在透发度、特征花香以及整体香气的高级感上优化一下：\n1、香精和复配好的云檀膏2.0香，改进版和天然版整体调性与原香精是相似的，但透发性、天然感和高级感都不如原香精；\n2、加在卸妆膏里改进版透发性差，闻着很闷；天然版透发性较好，但不如原香精，且两版的花香特征都不如原香精。】\n【2026.9.14更新：DH-L170233云檀（改进2#）-LYS2487FLY，新的云檀还是有点闷，而且后调散的太快了，原香精一直到后续都有很明显的花香，咱们这个后面只有淡淡的木质味了】', '逐本-云檀仿香', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2091729773947506690', '0', '0', '05035817329389', '刘畅', '2026-08-24 11:30:15', '17201757871959617', '寄样员', '2026-08-27 14:04:17', '1', '2091729774186487809', 'RUNNING', '运行中', '12377314', 'DHFF', '7', 'YPGD-20260824-0014', '2091073383243436034', '初柬--车载香氛礼赠用推荐20260822', NULL, '1', '需求明确', '5', '香精库推荐', '3025', '车载香薰', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '100以内', '16466317325076496,113845370124130976', NULL, '2057285879998668801', '刘生', '刘生\n18666825218\n广东省深圳市龙岗区南湾街道富通海智科技园3栋1803 刘生18666825218\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF6048530117861', NULL, NULL, NULL, '梁皓,彭佳庆', '应客户车载香氛需求进行推荐or优化\n方向1：柑橘茶香\n方向2：雪松檀木\n方向3：柑橘木质\n方向4：清新自然\n客户该产品用于车载香氛，直接用香精浸泡香片需要确认ifra添加量是否为100%\n每个方向需要推荐2~3款，可推荐大牌仿香、天然植萃感类香氛\n需求价格：100以内\n香精需要20~30g\n需求时间：8.26', '初柬--车载香氛礼赠用推荐', '1', '无', NULL, '', '');
