INSERT INTO `w_bo_gd_20250707155940` VALUES ('2091741409299124226', '0', '0', '17804235042843764', '陈赛', '2026-08-24 12:16:29', '17201757871959617', '寄样员', '2026-08-27 10:37:44', '1', '2091741409496162306', 'RUNNING', '运行中', '909783222', '评香部', '9', 'YPGD-20260824-0021', '2091738181979328513', '船王-桂花香型-20260824', NULL, '1', '需求明确', '5', '香精库推荐', '1026', '皂', '2027-08-24 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '75-100元之间', '17400514601408872,05035817437137', NULL, '2091736366877495297', '梁瑶', '梁瑶\n13097992317\n浙江省杭州市滨江区上峰电商产业园世包大楼B310\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1222303304801', NULL, NULL, NULL, '于姗姗,宣二鹏', 'LJB1367BLJ 去变色，降价到100\n香型 桂花香型\n用途 洗衣皂/香皂\n香味要求\n1.香味浓烈好闻不刺鼻，需要留香稍微持久一点的，\n无劣质化工气味\n2.距离鼻子5-10cm处仍可感知香味\n3.香精无变色因素\n添香量  洗衣皂0.6%    香皂1.2%\n香型数量  推荐1-2款香精\n样品需求 \n每款香精各10ml左右，各打一小块皂选香/闻香用\n先寄样后做稳定性测试', '船王-不变色桂花香型-20260824', '2', '加香', NULL, '', '');
