INSERT INTO `w_bo_gd_20250707155940` VALUES ('2091783536796225538', '0', '0', '16455177663846080', '常晓爽', '2026-08-24 15:03:53', '05035817305203', '苏妍', '2026-08-31 14:07:33', '1', '2091783536984875009', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260824-0031', '2085301461922598914', '杭州云韵--超级种子--个护香型推荐20260806', NULL, '1', '需求明确', '1', '客户新品开发', '202', '身体洗护', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"云韵-超级种子.xlsx\",\"timestamp\":\"v8BtanG8jtE7VxZ3coCn\",\"size\":21046,\"secret\":null,\"fileId\":\"c5ad2dd5-8528-4c06-a21f-c7bbc88ed308\",\"showSize\":\"21KB\",\"fileClass\":\"iconBox excelBox\"}]', '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '16466317325076496,113845370124130976', NULL, '2085295280546107394', 'Gia', 'Gia\n15058351217\n浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '梁皓,彭佳庆', '根据客户需求进推荐递样\n浮木苦橙、春绿、粉桃葡萄、天竺青提、气泡柑橘、昂蒂布之夏、青橙、杨桃\n产品用于沐浴露、洗发水、护发素\n后续客户会提供个护base加香后再寄出\n每款需要20~30g\n需求时间：8.10带上海办，确认后再寄样', '菠萝香水仿香', '1', '无', '8.10评香会带样品至上海办，后续销售安排寄出', '', '');
