INSERT INTO `w_bo_gd_20250707155940` VALUES ('2092525360657715201', '0', '0', '16455177663846080', '常晓爽', '2026-08-26 16:11:38', '17201757871959617', '寄样员', '2026-08-26 17:44:38', '1', '2092525360976388097', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260826-0028', '2090281935011041281', 'Eios--苹果、蜜瓜洗护用推荐&优化20260820', NULL, '1', '需求明确', '1', '客户新品开发', '2', '个人护理', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆,王晔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300~400', '16466317325076496,113845370124130976,17127345845433575', NULL, '2087448295386370049', '林琳', '林琳\n13636428501\n上海科黛生物科技有限公司 沪青平公路3938号8号楼 林琳 13636428501\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1223303176941，SF5115989615095两个地址两套样品上海市长宁区长宁国际T4栋12层 李先生 15061883002', NULL, NULL, NULL, '梁皓,彭佳庆,王晔', '应客户需求推荐或优化苹果和蜜瓜两个主题洗护产品\n每个主题需要提供2~3款样品\n客户希望不要单纯的果香香气，需要保持高级沙龙香氛感\n类似Kilian--苹果白兰地这类有高级香氛质感的香气\n客户用于洗护产品内\n加香量0.2~0.3%，需确认香气强度以及ifra法规\n需求价格：300~400\n需求时间：8.26', '蜜瓜&苹果推荐', '1', '无', NULL, '', '');
