INSERT INTO `w_bo_gd_20250707155940` VALUES ('2094258908565590018', '0', '0', '16455177663846080', '常晓爽', '2026-08-31 11:00:08', '17201757871959617', '寄样员', '2026-09-11 16:36:54', '1', '2094258908771016705', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260831-0009', '2094254758494720002', '戈海  DH-A26122白苔雪松--SYB2070ASY8B  优化调整', NULL, '1', '需求明确', '2', '客户老品升级', '202', '身体洗护', '2027-08-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '155元', '1638968357988946', NULL, '2034161061858361346', '居居', '居居\n13922118445\n广州市天河区珠江新城华夏路富力盈通2810室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1229462505939', NULL, NULL, NULL, '何家文', '型号：SYB2070ASY8B-- DH-A26122白苔雪松\n反馈一：目前用在沐浴露产品（添加量：2%），OEM客户反馈有一股洗洁精的感觉，麻烦看看是不是柠檬调多了导致有洗洁精的感觉，优化一下整体气味。\n反馈二：SYB2070ASY8B 有点遮盖不住沐浴露基料味，麻烦同时把香精浓度再提高一点，客户的沐浴露产品添加量为2%，先用我们自己的基料做测试就可以。\n产品：沐浴露（添加量2%）\n价格：155元\n中文标签：白苔雪松（DH-A26122优化版）', '白苔雪松修改', '1', '无', NULL, '', '');
