INSERT INTO `w_bo_gd_20250707155940` VALUES ('2094610555053527042', '0', '0', '05035817329389', '刘畅', '2026-09-01 10:17:27', '05035817426372', '王东辉', '2026-09-29 16:23:36', '1', '2094610555422531586', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '13', 'YPGD-20260901-0003', '2094607102302474242', '舒彩--逐本-活力系列水果卸妆膏', NULL, '1', '需求明确', '1', '客户新品开发', '2', '个人护理', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,050363634136321790', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '销售自提', '2026-09-04 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '详见附件biref\n活力系列水果卸妆膏\n逐本第一批4款香型brief，按照客户需求实现，每个香型2-3款\n香精：15ml\n价格：400以内\n时间：9-4（本周五）寄出\n寄李玲\n【2026.9.7更新：根据HDB2004GHD修改\n1.需要清凉的水润感，不能有草本感，可以尝试其他薄荷类原料\n2.整体香气太甜\n3.茉莉香气感知不到】', '舒彩--逐本-活力系列水果卸妆膏——茉莉冰荔枝', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2094612773798400002', '0', '0', '05035817329389', '刘畅', '2026-09-01 10:26:16', '113845370124130976', '彭佳庆', '2026-09-18 14:07:49', '1', '2094612773987049474', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '15', 'YPGD-20260901-0005', '2094607102302474242', '舒彩--逐本-活力系列水果卸妆膏', NULL, '1', '需求明确', '1', '客户新品开发', '2', '个人护理', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '113845370124130976,050363634136321790', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '销售自提', '2026-09-17 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '详见附件biref\n活力系列水果卸妆膏\n逐本第一批4款香型brief，按照客户需求实现，每个香型2-3款\n香精：15ml\n时间：9-4（本周五）寄出\n寄李玲\n【2026.9.7更新：根据DXB2181GDX改进，整体来说青苹果的酸甜感是2号更好，但是两款加在base里都存在洗发水那种廉价香精感，需要改进。同时需要增加气泡感和青苹果的酸甜，要清新一点。】\n价格：400以内', '舒彩--逐本-活力系列水果卸妆膏——气泡青苹果', '1', '无', NULL, '', '');
