INSERT INTO `w_bo_gd_20250707155940` VALUES ('2096845293998821377', '0', '0', '05035817329389', '刘畅', '2026-09-07 14:17:30', '17201757871959617', '寄样员', '2026-09-09 16:09:45', '1', '2096845294229413889', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '3', 'YPGD-20260907-0022', '2095769937028042754', 'KKV-果香个护产品推荐20260904', NULL, '1', '需求明确', '5', '香精库推荐', '2', '个人护理', '2027-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '120~200', '16466317325076496,113845370124130976', NULL, '2079404102499930113', '赵怡', '赵怡\n18586537710\n东莞市南城街道袁屋边隐山路35号KK集团4楼 赵怡 18586537710 （收）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1229436251231', NULL, NULL, NULL, '梁皓,彭佳庆', '【香精需求】\n人群：16～25岁年轻女性。\n价格：120～200元\n1️⃣磨砂膏：\nsku1果香：苹果＞葡萄＞蜜瓜=荔枝\nsku2果复合花香/水生调/茶香调 -  如葡萄茉莉、 荔枝水生、苹果大红袍等\n2️⃣身体精华露：\nsku1果香：苹果＞葡萄＞蜜瓜=荔枝\nsku2果复合花香/水生调/茶香调 -  如葡萄茉莉、 荔枝水生、苹果大红袍等\n3️⃣素颜霜：\nsku1主调需是果香， 建议- 葡萄＞蜜瓜=荔枝，香型建议同上可以复合花香or双果香\nsku2果复合花香/水生调/茶香调 -  如葡萄茉莉、 荔枝水生、苹果大红袍等\n\n最好能提供三个需求通用的香精，如果有香气表现优异但有品类限制须在品名后备注适用品类\n单一果香主题4个需求每个主题推荐3~5款\n复合果香主题3个需求每个主题推荐3~5款\n如需修改可分批寄样，优先寄库存推荐样品，再统一寄修改样品\n身体精华露加香量：预估0.8% \n素颜霜加香量：预估0.6%\n磨砂膏油溶体系加香量：预估1%\n需要提前确认法规\n该产品26年底需完成采购上市需求时间紧急\n需要香精10~20g\n需求价格：120~200\n需求时间：库存推荐9.8寄出，修改产品9.14寄出', 'KKV-果香个护产品推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2096845801308278785', '0', '0', '05035817329389', '刘畅', '2026-09-07 14:19:31', '050358172196', '刘扬', '2026-09-17 09:49:41', '1', '2096845801547259906', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '3', 'YPGD-20260907-0024', '2096771641735368705', 'Jijide调香重点项目-Riso 20260907', NULL, '1', '需求明确', '2', '客户老品升级', '3011', '香水', '2027-01-01 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '郭治爽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2500', '04476151371724', NULL, '2056950508387524609', 'Adam James Cavallari c/o Jijide', 'Adam James Cavallari c/o Jijide\n+393931111644\nVia California 12  Milano 20144  Italy\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '郭治爽', '老板对接客户 Jijide 项目：\n客户更换香料供应商，新厂复刻不出 RISO、TERRA，样品香气偏差大。\n已有 Zimo Luo、Adill Ali 原始配方，原配方不满足 IFRA51/52，需做合规修改，RISO 为客户爆款优先。历史单价约 300 欧 / 升。\nTERRA 注意 Pharanbee 40Y 沉香为 25% DPG 稀释。\n请评香、调香评估下我们这边能否承接该两款香复刻，给出评估意见。附件为Riso配方，老板指定刘畅，刘扬参与，并会有交待。', 'Jijide调香重点项目-Riso', '1', '无', '自提', '', '');
