INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099351320552001537', '0', '0', '16275212368889684', '赵文雅', '2026-09-14 12:15:34', '17201757871959617', '寄样员', '2026-09-17 12:17:00', '1', '2099351320744845314', 'RUNNING', '运行中', '909783222', '评香部', '7', 'YPGD-20260914-0015', '2097507572440354817', '9.9新品推荐', NULL, '1', '需求明确', '5', '香精库推荐', '1053', '其他', '2027-09-09 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何佳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '04476151361985', NULL, '2034161060126113794', '戚慧芳', '戚慧芳\n15822125457\n天津西青区微电子工业区微二路6号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5151255119270', NULL, NULL, NULL, '何佳', '冰箱净味\n橙香：\n1.青皮鲜橙：突出新鲜青橙剥开的果皮清冽气息，带极淡果皮微苦，压低果肉甜感，追求原生橙皮真实感，气味通透不闷。\n\n2. 阳光蜜橙：成熟蜜橙温和果香，甜酸均衡、甜而不齁，香气柔和友好，大众高适配，不抢味，为主流走量香型。\n\n3. 苦橙清净化：苦橙果皮调，甜感压至低位，体现清冽洁净感，仅微量苦感点缀，严禁明显药苦味道，适配霉闷潮湿环境。\n', 'LJA1101CLJ 调整配方', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099351495370592258', '0', '0', '16275212368889684', '赵文雅', '2026-09-14 12:16:15', '17201757871959617', '寄样员', '2026-09-17 12:16:25', '1', '2099351495617961985', 'RUNNING', '运行中', '909783222', '评香部', '6', 'YPGD-20260914-0016', '2097507572440354817', '9.9新品推荐', NULL, '1', '需求明确', '5', '香精库推荐', '1053', '其他', '2027-09-09 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何佳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '04476151361985', NULL, '2034161060126113794', '戚慧芳', '戚慧芳\n15822125457\n天津西青区微电子工业区微二路6号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5151255119270', NULL, NULL, NULL, '何佳', '冰箱净味\n青柠鲜柚：\n1. 青柠主导·柚皮衬底（清锐功能款）\n青柠香作为主体头香，突出冷榨青柠果皮鲜活清锐青香，带轻微果皮涩感；白蜜柚皮作为底调衬底，柔化青柠的尖锐感；压低果汁甜感，几乎无甜。整体通透干净，异味压制力强，适合剩饭、腥腻异味偏重冰箱；禁止出现酸败感。\n\n2. 柚香主导·青柠提香（温润大众走量款）\n白蜜柚果皮香为主调，保留柚子皮特有的甘润微苦草本感；青柠作为头香提亮，只做点缀，赋予鲜活气息，不抢柚香主体。整体香气柔和圆润，刺激性低，久闻不闷，兼容性强，不易产生客诉，作为主力大货香型。\n\n3. 西柚（葡萄柚）+青柠双苦柑·净化冷调款\n葡萄柚（西柚）为主，搭配少量冷榨青柠；双果皮复配，甜感压至极低，强化洁净干爽的净化感；二者自带的微苦仅做气息点缀，严禁明显药苦感。调性冷静克制，适配高湿度、容易产生霉闷味的冰箱、储物空间，面向排斥甜果香的消费群体。\n', 'DHR861BDH', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099351836912766978', '0', '0', '16275212368889684', '赵文雅', '2026-09-14 12:17:37', '17201757871959617', '寄样员', '2026-09-16 10:46:48', '1', '2099351837206274049', 'RUNNING', '运行中', '909783222', '评香部', '4', 'YPGD-20260914-0017', '2097883337136787457', '森熹堂-蜡烛里面的家具香氛-0910', NULL, '1', '需求明确', '5', '香精库推荐', '3', '高级香氛', '2027-09-10 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '邢芬,郭治爽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '16855125875633810,04476151371724', NULL, '2090624826409472002', '紀善傑', '紀善傑\n+886 0905 095 538\n台灣 台北市士林區士商路12號4樓\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5151676881430-陳柏志 手機(+86) 18926523597 所在地區 广东省深圳市宝安区福永街道 詳細地址 (F3387)兴益路兴益工业城A1栋1A(0986985823)', NULL, NULL, NULL, '邢芬,郭治爽', '除了這次的白茶、黑茶、紫蘇、香桃木之外，我們也想再多評估一些比較有辨識度、不是市場上太常見的香氣方向。\n\n如果你們有合適的香型，可以再幫我們推薦一些，例如：\n\n冷木質：檜木、柏木、冷杉、雪松這類比較乾淨、偏冷感的木質；\n\n礦物冷石：濕石、礦物、雨後石板、海鹽、漂流木這類比較安靜、有空間感的氣味；\n\n葉綠草本：無花果葉、番茄葉、艾草、鼠尾草、羅勒這類偏葉片與植物莖葉感的香氣；\n\n茶香：除了白茶、黑茶之外，也想看看焙茶、玄米茶、烏龍、普洱或帶一點煙燻感的茶香；\n\n樹脂焚香：乳香、沒藥、欖香脂、岩薔薇這類，但希望是比較乾淨、現代、偏冷感的方向，不要太濃厚或傳統寺廟感；\n\n另外如果有苔蘚、蕨類、濕森林、樹皮這類比較自然、有森林地表感的香型，也可以推薦給我們。\n\n整體還是希望以「自然、低甜度、有層次、有辨識度」為主，不需要太大眾或太商業化的香型。\n\n如果其中有天然精油比例比較高，或是以天然植物原料為主體的香型，也可以優先推薦給我們。', '推荐', '1', '无', NULL, '', '');
