INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099391352251863041', '0', '0', '16275212368889684', '赵文雅', '2026-09-14 14:54:38', '17201757871959617', '寄样员', '2026-09-17 12:16:05', '1', '2099391352461484033', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260914-0042', '2097507572440354817', '9.9新品推荐', NULL, '1', '需求明确', '3', '双马香精升级', '103', '空清、消杀与熏香', '2027-09-09 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何佳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '04476151361985', NULL, '2034161060126113794', '戚慧芳', '戚慧芳\n15822125457\n天津西青区微电子工业区微二路6号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5151255119270', NULL, NULL, NULL, '何佳', '空调净味\n青柠海盐：\n1.青柠主调·矿物海盐衬底（清爽功能款）\n冷榨青柠果皮香作为头香主体，突出青柠鲜活清锐果皮青香，带轻微果皮涩感；海盐仅用微弱干净矿物干爽感做底层衬托，提升通透度，完全不表现海洋气息；几乎无甜香。整体通透干爽，对冰箱腥腻、剩饭菜异味压制力强；严禁发酸、发腥，密闭环境不能冲鼻。\n\n2. 矿物清感主导·青柠提亮（温润大众走量款）\n以柔和干净的矿物清透感为基底（无任何海洋/海水意象）；青柠果皮香作为头香提亮点缀，赋予鲜活柑橘气息，青柠不浓烈。整体气味清淡松弛，刺激性极低，久闻不闷不腻，兼容性强，差评风险低，适合作为大货走量香型。\n\n3. 冷感青柠矿物净调（差异化高级款）\n冷榨青柠果皮搭配矿物型海盐清透感，全程规避水生海洋调；甜感压到最低，营造柑橘+矿物复合干爽洁净感；青柠涩感、矿物咸感均为意象点缀，二者不得过量。调性冷静克制，适配高湿度、霉闷感重的冰箱、储物抽屉，面向排斥甜果香的用户；杜绝药感、腥咸异味，冷感物质不可过量，避免薄荷刺鼻感。\n', '推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099391662764576770', '0', '0', '16275212368889684', '赵文雅', '2026-09-14 14:55:52', '17201757871959617', '寄样员', '2026-09-17 12:16:50', '1', '2099391662986780673', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260914-0043', '2097507572440354817', '9.9新品推荐', NULL, '1', '需求明确', '5', '香精库推荐', '103', '空清、消杀与熏香', '2027-09-09 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何佳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '04476151361985', NULL, '2034161060126113794', '戚慧芳', '戚慧芳\n15822125457\n天津西青区微电子工业区微二路6号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5151255119270', NULL, NULL, NULL, '何佳', '冰箱净味\n竹香海盐：\n1. 竹香主导·微量矿物海盐衬底（清雅功能款）\n以鲜嫩青皮竹的清润竹香作为主体头香，突出新鲜竹材的清鲜草本气息，规避浓重老竹、烟熏竹、苦竹药味；海盐仅以极淡矿物干爽感做底调衬托，强化净化通透感，海盐气息不显露。整体干净素雅，对冰箱剩饭、轻度腥腻异味适配；密闭环境不会闷浊，无杂味。\n\n2. 矿物清感打底·竹香提亮（柔和大众走量款）\n干净柔和的矿物清透感作为基底（无任何海洋意象）；竹香作为头香点缀提亮，竹香清淡温润，不厚重，不出现草木闷感。整体气味清淡松弛，刺激性极低，和熟食、果蔬气味兼容性好，久闻无压迫感，客诉风险低，适合作为主力大货香型。\n\n3. 冷调竹萃·矿物净感（差异化高级款）\n清冽嫩竹萃取调性，甜感压至最低，搭配克制的矿物海盐清透感；竹香的草本感、矿物干爽感均为意象点缀，两者均不过量输出；营造冷静干爽的净化氛围。适配高湿度、霉闷味明显的冰箱、储物抽屉；严禁出现薄荷冲凉感、药草味、海水腥感，气味保持素雅内敛。', 'LJR389ALJ', '1', '无', NULL, '', '');
