INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099431277122801666', '0', '0', '05035817329389', '刘畅', '2026-09-14 17:33:17', '17201757871959617', '寄样员', '2026-09-22 16:22:07', '1', '2099431277374365698', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '5', 'YPGD-20260914-0061', '2099343784683753473', '旷世--图个心安系列藤条产品优化&推荐20260914', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200以内', '16466317325076496,113845370124130976', NULL, '2036362719833079809', '吴千妤', '吴千妤\n13252221512\n浙江省宁波市海曙区气象路827号旷世智源工艺设计有限公司  吴千妤  13252221512\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1226656855002', NULL, NULL, NULL, '梁皓,彭佳庆', '图个心安系列藤条香氛/车载/精油/香包等\n优先考虑藤条香氛选香。要求扩香好、爆发力和透发性不错，挥发速度尽量均匀，避免出现挥发到后面完全挥发不了的情况\n香味方向：\n1.柚好运：柚子叶+佛手柑+柑橘香气，适配柚子叶的概念：\n芦荟+柑橘\n2.有钱花：复合花香（可以考虑牡丹）等带有吉利寓意的花香；\n优先推荐符合需求的大牌香氛仿香优化\n3.接福禄：草本+绿叶，复合葫芦概念；需求价格：200以内：\n注意：香精溶剂不要蜡烛常用溶剂，不要isopar\n需求价格：200以内\n需求时间：直接推荐的9.17出，需要优化修改的9.24前出\n需要香精50g', '旷世--图个心安系列藤条产品优化&推荐', '1', '无', NULL, '', '');
