INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099704450858864641', '0', '0', '05035817329389', '刘畅', '2026-09-15 11:38:46', '17201757871959617', '寄样员', '2026-09-21 12:23:30', '1', '2099704451085262849', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '3', 'YPGD-20260915-0007', '2099369274832310273', '欣满和--宠物香波推荐20260914', NULL, '1', '需求明确', '1', '客户新品开发', '401', '宠物护理', '2027-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '500以内', '16466317325076496,113845370124130976', NULL, '2061654667732934657', '张健', '张健\n13818862672\n上海市徐汇区曲靖路38号汇创谷4号楼505，张健，13818862672\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5153487679045', NULL, NULL, NULL, '梁皓,彭佳庆', '推荐客户5~8款草本木质香型和今年大牌仿香适用于宠物香波\n香气方向1：草本药香，中药感一些的\n香气方向2：大牌香氛偏木质或伪体香一些的\n客户产品用于宠物香波以及毛发柔顺剂\n产品内会添加0.5%鱼肝油导致base会有些腥感\n客户香波加香量0.8~1%\n容量300ml 6万瓶\n该系列共4款产品已选中\nDH-M146471 LYA2427ALY	寐岚1\nDH-S603850 LYA2426BLY	凝思2\n可作为香气参考方向\n需考虑香气的遮盖力\nbase已寄少量给销售感受\n需求价格：500以内\n需求时间：9.17', '欣满和--宠物香波推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2099704997330538498', '0', '0', '05035817329389', '刘畅', '2026-09-15 11:40:57', '17201757871959617', '寄样员', '2026-09-30 16:54:28', '1', '2099704997544353793', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '10', 'YPGD-20260915-0008', '2099379746394591234', 'Wildsniff--苹果、桃子、山茶花无火藤条香型推荐20260914', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300~400', '16466317325076496,113845370124130976', NULL, '2041784676787404802', '董女士', '董女士\n15088641093\n浙江省杭州市西湖区转塘街道孵鸡湾38号白桦林手作园2210室 董女士 15088641093\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1220745595331，SF1227767901093', NULL, NULL, NULL, '梁皓,彭佳庆', '根据客户需求推荐苹果、桃子、山茶花三个方向香型\n产品用于车载香氛以及无火扩香石内\n需要特别注意扩香能力和香气和谐度\n以及其品类适用法规\n每个方向需推荐3~5款\n方向1：苹果\n可推荐Kilian-苹果白兰地、青苹果脆以及其他好闻的苹果香型\n方向2：桃子\n可推荐桃子-LYP2453ALY\n方向3：山茶花\n需要绿叶花香型，带一些柑橘感在\n需要10%香水加香产品\n需求价格：300~400\n需求时间：9.18', 'Wildsniff--苹果、桃子、山茶花无火藤条香型推荐', '2', '加香', NULL, '', '');
