INSERT INTO `w_bo_gd_20250707155940` VALUES ('2100470215820169217', '0', '0', '16275212368889684', '赵文雅', '2026-09-17 14:21:39', '17201757871959617', '寄样员', '2026-10-08 17:44:11', '1', '2100470216168202241', 'RUNNING', '运行中', '909783222', '评香部', '15', 'YPGD-20260917-0019', '2100174560237178882', '（紧急）金华百秘“圣诞”类香精推荐26-09-16', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-09-16 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200-380', '02461210300720808373', NULL, '2046836324672954369', '程东', '程东\n17585442263\n浙江省金华市金东区孝顺镇低田工业区浦莘路142号3号楼6楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5149011643047', NULL, NULL, NULL, '余鹏程', '请推荐类似焦糖苹果、威士忌焦糖风格的香型，各1款；\n类似南瓜  肉桂  焦糖这类的，每种风格推荐3款左右；\n符合“万圣节”主题的香型2-3款\n用于出口欧美的蜡烛，客户特别要求香精不能阻燃，不要影响火苗燃烧稳定性\n价位可控制在200-380内\n要求寄出日期：9.24前\n因百秘此轮需求样品数量较多，每个工单下的样品，在寄出前需要用自封袋收集齐并装好', '推荐（圣诞）', '2', '加香', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2100470565281189889', '0', '0', '16275212368889684', '赵文雅', '2026-09-17 14:23:02', '17201757871959617', '寄样员', '2026-10-08 17:41:27', '1', '2100470565524365314', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260917-0020', '2100176049097658370', '金华百秘“宠物类”香精推荐26-09-16', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-09-16 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '02461210300720808373', NULL, '2046836324672954369', '程东', '程东\n17585442263\n浙江省金华市金东区孝顺镇低田工业区浦莘路142号3号楼6楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5149011643047', NULL, NULL, NULL, '余鹏程', '客户下半年开新品。请推荐宠物友好系列香氛，注意三调中不要出现“柑橘、薰衣草、桉叶”类的宠物敏感原料，并且要求香气不要“大地、蔚蓝、粉邂逅”等这种街香，尽量“偏”一点，新奇一点，用于无火&晶石产品；\n样品需10款左右\n样品标签请备注清楚，属于宠物香氛系列；\n此工单下的样品，寄出前需要用自封袋收集装好，便于客户收到样品时区分系列；', '推荐宠物友好系列香氛', '1', '无', NULL, '', '');
