INSERT INTO `w_bo_gd_20250707155940` VALUES ('2100480064599609345', '0', '0', '05035817329389', '刘畅', '2026-09-17 15:00:47', '17906565377856558', '张婧悦', '2026-10-29 17:48:51', '1', '2100480064888922113', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '11', 'YPGD-20260917-0024', '2100047910782619650', '诗肤理--时序线膜霜仿香20260916', NULL, '1', '需求明确', '2', '客户老品升级', '2', '个人护理', '2027-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"NATURE BOUQET PASSION.xlsx\",\"timestamp\":\"kphDRZ9MPTZVuFzlwOUj\",\"size\":16192,\"secret\":null,\"fileId\":\"b9ed0de3-182a-4e48-8796-527b63885353\",\"showSize\":\"16KB\",\"fileClass\":\"iconBox excelBox\"}]', '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '5000~8000', '16466317325076496,113845370124130976', NULL, '2034161060537155586', 'Elaine*', 'Elaine*\n18621746130\n上海市闵行区申长路1588弄中骏广场一期01号楼平安财富中心3A07室  Elaine 18621746130\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, 'LYS2509ALY-柑橘橙花2（面霜）LYS2509BLY-柑橘橙花3（面霜）LYS2509CLY-柑橘橙花4（面霜）', 'SF1572353133803', '2026-10-29 00:00:00', NULL, NULL, '梁皓,彭佳庆', '根据客户提供纯天然精油产品进行仿香\n原产品供应商断供目前由我们仿香进行替换\n该产品为纯天然精油产品\n需注意法规包括：SDS、IFRA、闪点、客户需要全开配方，\n可能存在出口需求需注意出口法规\n需求价格：5000~8000\n需求时间：9.18\n加香量：0.08%~0.2%根据遮盖力判断，如遮盖力弱可提升至0.5%\n无需寄样，销售自提\n【2026.10.23更新：\nLYS2509ALY 客户需要在该版本上增加花香脂粉感更接近原版仿香的橙花感，\n需要提供两个版本\n1、依兰/晚香玉\n2、白兰\n需求价格：6000以内】', '诗肤理--时序线膜霜仿香', '1', '无', '无需寄样，销售自提', '', '');
