INSERT INTO `w_bo_gd_20250707155940` VALUES ('2100536438121549825', '0', '0', '05035817329389', '刘畅', '2026-09-17 18:44:48', '17201757871959617', '寄样员', '2026-10-23 09:50:30', '1', '2100536438322782209', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '14', 'YPGD-20260917-0044', '2094622073446977537', '舒彩--逐本--不染轮廓油、精粹水降本（重要）', NULL, '1', '需求明确', '2', '客户老品升级', '2', '个人护理', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '彭佳庆,逯柏松', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '3000', '113845370124130976,050363634136321790', NULL, '2064892343747596290', '李玲', '李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, 'LYS2498CLY-玫瑰茉莉3（面霜），按客户要求增强玫瑰与香根部分', 'SF1572353142847，SF5146495039066', '2026-09-24 00:00:00', NULL, NULL, '彭佳庆,逯柏松', '不染轮廓油/精粹水香气成分\n茉莉35-50/墨红玫瑰20-30/二氢茉莉酮酸甲酯20-30/香根油2-6/白兰花1-5/乳香1-5/广藿香1-5 /  以上是天然油的配方和比例\n需要把配方中比较贵的天然油，按照以上配方比例进行香精化（降本），同时在base中和全天然油香气表现相似\n一：部分天然油香精化（乳香、白兰、玫瑰、香根），价格需要天然油成本的三分之一\n二：全部香精化，价格需要天然油成本的二分之一（备选方案，已方案一为主）\n应用：面部精华油\n香精：15ml\n时间：9-15前寄出\n价格：3000', '舒彩--逐本--不染轮廓油、精粹水降本（重要）', '1', '无', NULL, '', '');
