INSERT INTO `w_bo_gd_20250707155940` VALUES ('2102569456600338433', '0', '0', '16275212368889684', '赵文雅', '2026-09-23 09:23:17', '17201757871959617', '寄样员', '2026-09-24 11:32:20', '1', '2102569456948371457', 'RUNNING', '运行中', '909783222', '评香部', '5', 'YPGD-20260923-0001', '2102300573876342786', '天津宝隆包装-需要换溶剂-20260922', NULL, '1', '需求明确', '3', '双马香精升级', '401', '宠物护理', '2027-09-22 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '17400514601408872,05035817437137', NULL, '2056209939889610754', '陈可心', '陈可心\n15767887534\n广州市黄埔区观达路17号达意隆前台\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5153520565163', NULL, NULL, NULL, '于姗姗,宣二鹏', 'DH-Q832221 绯境花园（+燕麦）这款香精能替换成其他溶剂，因为我们之前小批量的测试了一批，反馈提到使用后出现比较黏腻的问题，需要换溶剂i，宠物香氛的法规和香波的法规。\n用途 宠物香波和香氛 样品需要100g', 'LJB2306BLJ', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2102573812229853186', '0', '0', '05035817329389', '刘畅', '2026-09-23 09:40:35', '17201757871959617', '寄样员', '2026-10-14 09:59:34', '1', '2102573812535943170', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '4', 'YPGD-20260923-0002', '2102291432663404545', '宋朝香氛出口香型选香-', NULL, '1', '需求明确', '1', '客户新品开发', '1', '家庭护理', '2026-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '050363634136321790,113845370124130976', NULL, '2069339637448429569', '马女士', '马女士\n15988856039\n杭州市滨江区长河街道塘子堰路159号笨鸟园区D幢6楼马女士15988856039\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5147169804595', NULL, NULL, NULL, '逯柏松,彭佳庆', '他们需要在扫地机器里面加香，客户对香精有几点要求：\n1️⃣主要出口，香精符合多国法规，销售区域包括国内，欧洲，美国，东南亚，日本，韩国，俄罗斯，中东，以色列，土耳其，印度，澳洲\n\n2️⃣宠物友好型香精（宠物对一些香精很敏感）安全\n\n3️⃣需要耐高温70度，有些香精在扫地机器人里面会高温发生香气改变\n\n4️⃣香精稳定性要好，不变色。\n\n5️⃣香精也需要耐低温零下30度\n麻烦帮忙推荐匹配\n6：加香方式是香薰片，通过电加热扩散香气\n7：香精里面不要HCA（甲位己基肉桂醛）\n推荐5-8款\n应用：空间香氛\n价格；150以内\n香精：30ml\n时间：9月28寄出', '宋朝香氛出口香型选香', '1', '无', NULL, '', '');
