INSERT INTO `w_bo_gd_20250707155940` VALUES ('2108118908912254977', '0', '0', '17804235042843764', '陈赛', '2026-10-08 16:54:49', '17201757871959617', '寄样员', '2026-10-14 14:17:12', '1', '2108118909147111425', 'RUNNING', '运行中', '909783222', '评香部（天津）', '8', 'YPGD-20261008-0026', '2108104065471725570', '红卫-香皂木质香东方香20261008', NULL, '1', '需求明确', '1', '客户新品开发', '2023', '香皂', '2027-09-29 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '宣二鹏,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '190-200', '05035817437137,17400514601408872', NULL, '2087446166613512194', '胡少康', '胡少康\n18147223870\n包头市东河区铝业园区红卫日用化工有限公司\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1.5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5148165426164', NULL, NULL, NULL, '宣二鹏,于姗姗', '藏红花檀木 LJC2344ALJ 去溶剂，价格尽量在200以内\n香皂项目：\n1.客户需要木质风格，香东方香型\n2.香精价格190元-200元/公斤，尽量做到不含溶剂或含有效溶剂\n3.香精各需要10克\n4.带送样单，送样单：型号+名称+香气描述+精油添加+灵感来源（大牌仿香）\n5.推荐3-5种\n6.香皂加香量1.5%\n7.尽可能做到不变色，如果变色送样单请注明变色因素\n8.不含禁用和现用原料\n9.同步质检部配方，需要SDS,IFRA，COA ，需求时间寄出样品后三个工作日内。\n10.预计客户收到时间10月16日前\n备注：先寄样品，同步做稳定性测试', '红卫-香皂木质香东方香20261008', '2', '加香', NULL, '', '');
