INSERT INTO `w_bo_gd_20250707155940` VALUES ('2108403323391426561', '0', '0', '05035817329389', '刘畅', '2026-10-09 11:44:59', '17906565377856558', '张婧悦', '2026-10-16 10:14:02', '1', '2108403323655643138', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '5', 'YPGD-20261009-0017', '2108104347886796802', '旷世--慵懒周末PE香片优化20261008', NULL, '1', '需求明确', '2', '客户老品升级', '302', '空间香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2036362719833079809', '吴千妤', '吴千妤\n13252221512\n浙江省宁波市海曙区气象路827号旷世智源工艺设计有限公司  吴千妤  13252221512\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, 'LYP1479ELY-慵懒周日4（香片）', 'SF1574204113207', '2026-10-13 00:00:00', NULL, NULL, '梁皓,彭佳庆', '慵懒周末仿香香味\n做的车载pe片，现有的产品车里通风的情况下香气很淡\n原品由我司做替换升级\n客户车载外壳为塑料金色材质，需考虑溶剂适配性！！\n同时香气强度需要着重考虑！！！！！\n需求价格：300以内\n需求时间：最晚10.13必须寄出\n需要至少30g香精最好能提供50g', '旷世--慵懒周末PE香片优化', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2108403781136793602', '0', '0', '17804235042843764', '陈赛', '2026-10-09 11:46:48', '17201757871959617', '寄样员', '2026-10-14 14:17:25', '1', '2108403781396815874', 'RUNNING', '运行中', '909783222', '评香部（天津）', '8', 'YPGD-20261009-0018', '2108104065471725570', '红卫-香皂木质香东方香20261008', NULL, '1', '需求明确', '5', '香精库推荐', '2023', '香皂', '2027-09-29 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '宣二鹏,于姗姗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '190元-200元', '05035817437137,17400514601408872', NULL, '2087446166613512194', '胡少康', '胡少康\n18147223870\n包头市东河区铝业园区红卫日用化工有限公司\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1.5%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5148165426164', NULL, NULL, NULL, '宣二鹏,于姗姗', 'LJF1030ELJ,去溶剂\n香皂项目：\n1.客户需要木质风格，香东方香型\n2.香精价格190元-200元/公斤，尽量做到不含溶剂或含有效溶剂\n3.香精各需要10克\n4.带送样单，送样单：型号+名称+香气描述+精油添加+灵感来源（大牌仿香）\n5.推荐3-5种\n6.香皂加香量1.5%\n7.尽可能做到不变色，如果变色送样单请注明变色因素\n8.不含禁用和现用原料\n9.同步质检部配方，需要SDS,IFRA，COA ，需求时间寄出样品后三个工作日内。\n10.预计客户收到时间10月16日前\n备注：先寄样品，同步做稳定性测试', '红卫-香皂木质香东方香20261008', '2', '加香', NULL, '', '');
