INSERT INTO `w_bo_gd_20250707155940` VALUES ('2108815444851802113', '0', '0', '16455177663846080', '常晓爽', '2026-10-10 15:02:37', '17201757871959617', '寄样员', '2026-10-10 16:50:18', '1', '2108815445157961730', 'RUNNING', '运行中', '909783222', '评香部（天津）', '5', 'YPGD-20261010-0009', '2102688680626868226', '广州之间   圣诞主题 护手霜新品推荐', NULL, '1', '需求明确', '5', '香精库推荐', '202', '身体洗护', '2027-09-23 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300-500元不等', '1638968357988946', NULL, '2034161065083781122', '刘斯', '刘斯\n13560005895\n广东省广州市天河区南雅苑小区內体育东路6号103 【黑色建筑】\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1229901326581', NULL, NULL, NULL, '何家文', '需求一：温暖感的木香；希望成分可以包括：小豆蔻、松针叶、松果、雪松，这几个元素。整体感觉有雪地，冬天、圣诞、火炉等等的感觉。\n需求二：苹果树 / 苹果木香；客户不要常规的苹果香，希望能推荐以木头或绿植为主，苹果果香为辅助的香，带点清新的绿意的苹果香，尽量推荐2-3款给客户选择。\n需求三：树莓、蓝莓 / 车厘子为主题；和苹果一样，希望车厘子的香气只是陪衬，不然显得太甜，但需要有这个水果的存在的。也是可以带点绿芽、冬天的气息，甚至是像木桶里面装着果酱，浓厚深层一点的香气。\n需求四：柑橘调为主题（柚子、柑橘等等）；想要突出是清新感，但可以跳出只有柑橘的框框，再偏向绿色一些的感觉。带有叶子、果皮剖开的清爽感。当然也是有别以往的感觉。\n产品：护手霜\n价格：300-500元不等', '护手霜推荐', '1', '无', NULL, '', '');
