INSERT INTO `w_bo_gd_20250707155940` VALUES ('2109464238987657218', '0', '0', '05035817329389', '刘畅', '2026-10-12 10:00:41', '17201757871959617', '寄样员', '2026-10-19 17:58:18', '1', '2109464239197347841', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '9', 'YPGD-20261012-0009', '2108072628462796802', '云壹--纯白拥抱、隐衫之欲推荐20261008', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300左右', '16466317325076496,113845370124130976', NULL, '2101881153181962242', '韩-高尚领域', '韩-高尚领域\n13818000683\n上海市普陀区曹杨路1788号高尚领域T9栋212室 韩 13818000683\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5141392691211', NULL, NULL, NULL, '梁皓,彭佳庆', '根据客户需求推荐纯白拥抱、隐衫之欲\n产品用于无火、蜡烛、水性喷雾、护手霜内\n需要加香产品无火和蜡烛\n无火加香量15%需要确认ifra法规，蜡烛加香量10%\n需求价格：300左右\n后续客户收到样品后会需要一个两款的结合版待客户进一步沟通确认\n需求时间：10.10', '云壹--纯白拥抱、隐衫之欲推荐', '2', '加香', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2109465091580608514', '0', '0', '05035817329389', '刘畅', '2026-10-12 10:04:04', '17201757871959617', '寄样员', '2026-10-12 17:07:49', '1', '2109465091811270657', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '3', 'YPGD-20261012-0010', '2108085915023818753', '面膜香型开发-懿奈', NULL, '1', '需求明确', '1', '客户新品开发', '2', '个人护理', '2026-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '350', '050363634136321790,113845370124130976', NULL, '2108085551079866370', '蓝蓝', '蓝蓝\n13971511226\n上海市黄浦区淮海中路2-8号（淮海中路西藏南路）兰生大厦20楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5145172279652', NULL, NULL, NULL, '逯柏松,彭佳庆', '产品：贴片面膜\n\n美白嫩肤功效，敏肌可用，人群年龄20-40岁之间\n香味目标：清新、淡雅、天然感强的青香木质调 / 木香芳香调。\n情绪联想：晨雾森林、雪后柏木、干净棉麻、沉静修护高级感。适合美白抗老线，不老气、不沉闷、不厚重、不药感。\n不要方向：不要年轻甜花香、不要浓烈香水感、不要药味重、不要酸味、不要粉感、不要皂感、不要廉价日化香。\n\n需要一款青香木质芳香调，味道参考：\n前调：柏树、竹叶、杜松子，冷绿微辛但不酸；\n中调：竹叶、绿叶、极淡白玉兰，清透柔软；\n后调：雪松、岩兰草、莎草、微量广藿香。干净、天然、沉静；\n\n整体要清新淡雅、修护和抗老高端感，香味低强度、贴肤、干净、舒适，敷面时若有若无，揭下后只留一点淡淡的香味。\n\n商业参考：闻献 杉间淡香精版\n香型推荐2-3款\n\n价格：350\n香精：10ml\n时间：10月10号寄出\n寄件地址：蓝蓝 13971511226 上海市黄浦区淮海中路2-8号（淮海中路西藏南路）兰生大厦20楼', '面膜香型开发-懿奈', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2109465451489640450', '0', '0', '05035817329389', '刘畅', '2026-10-12 10:05:30', '17201757871959617', '寄样员', '2026-10-12 16:55:59', '1', '2109465451774828545', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '3', 'YPGD-20261012-0011', '2108097636429971458', '欧印--运动品牌空间香氛推荐20261008', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '16466317325076496,113845370124130976', NULL, '2099432787290345474', '陈雯汐', '陈雯汐\n13052055259\n上海市长宁区仙霞路750弄10号204室，陈雯汐 13052055259\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5145142539415', NULL, NULL, NULL, '梁皓,彭佳庆', '客户户外跑步店需要空间香氛推荐\n需要推荐：5~10款\n表现竞速、科技感、东方力量、精英跑者、要利落、通透、带一点点力量感，不能软、不能甜，兼顾东方简约+赛场清爽. \n客户意向香调类型\n香调：青柠+鲜罗勒+岩兰草+雪松\n香调：柏木+苦橙叶+薄荷+白麝香\n香调：龙井绿茶+佛手柑+白檀\n偏柑橘调\n需求价格：200~300\n需求时间：最晚10.12需寄出', '欧印--运动品牌空间香氛推荐', '1', '无', NULL, '', '');
