INSERT INTO `w_bo_gd_20250707155940` VALUES ('2110220681932161025', '0', '0', '16275212368889684', '赵文雅', '2026-10-14 12:06:31', '17201757871959617', '寄样员', '2026-10-14 13:40:50', '1', '2110220682213154817', 'RUNNING', '运行中', '909783222', '评香部（天津）', '3', 'YPGD-20261014-0007', '2110218275039199233', '美蜜找香-身体喷雾和房间喷雾出口美国-1014', NULL, '1', '需求明确', '5', '香精库推荐', '103', '空清、消杀与熏香', '2027-10-14 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '邢芬,余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '230', '16855125875633810,02461210300720808373', NULL, '2033448164891017217', '黄志军', '黄志军\n18057925210\n浙江省金华市义乌市义亭镇相宜路86号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF1222956042074', NULL, NULL, NULL, '邢芬,余鹏程', '做身体喷雾和房间喷雾出口美国\n- 尤加利留兰香：融合尤加利精油，清脑醒神；搭配留兰香精油，提振情绪。\n- 薰衣草香草：薰衣草精油营造静谧舒缓感，香草原精安定心绪。\n- 柑橘生姜：甜橙精油唤醒活力，生姜精油刺激感官、焕发元气。\n- 尤加利清茶：尤加利精油帮助放松，茶萃取物舒缓不安的情绪。\n- 黑洋甘菊：配方主打舒缓，助力养成安稳的睡眠习惯。\n- 复古玫瑰：玫瑰精油调香，唤起自爱之心，接纳自我情绪。\n这些香味本周五一定要帮我寄出来', '推荐', '1', '无', NULL, '', '');
