INSERT INTO `w_bo_gd_20250707155940` VALUES ('2112368941966802946', '0', '0', '16825006662777257', '齐钰', '2026-10-20 10:22:56', '17201757871959617', '寄样员', '2026-10-26 15:10:49', '1', '2112368942180687873', 'RUNNING', '运行中', '909783222', '评香部（天津）', '11', 'YPGD-20261020-0005', '2112124298649911297', '一三制香--高定香氛推荐&修改20261019', NULL, '1', '需求明确', '5', '香精库推荐', '3011', '香水', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000~4000', '16466317325076496,113845370124130976', NULL, '2112118946592178177', '杨爽', '杨爽\n18811360696\n北京市石景山区鲁谷街道长安悦玺小区7-2-2101，杨爽，18811360696\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5148574309313', NULL, NULL, NULL, '梁皓,彭佳庆', '客户产品主要用于香水内\n后续有出口需求\n调整阶段需要注意法规需求以及IFRA需求（最高35%添加量）\n\n阶段1：根据客户提供香水参考表进行第一轮推荐\n需要原版贵价版本\n提供香精和加香产品，加香量30%\n推荐10~12支，如表格内数量不够可根据客户喜好进行自行推荐\n需求时间：10.29寄出\n\n阶段2：客户同步寄出需要我们仿香修改的大牌香氛\n根据客户提供标样进行GC分析并根据修改方向进行优化\n需要提供原版和优化版各一支\n需要香精和加香产品香水30%\n该需求需要考虑后续法规以及出口需要\n\n阶段3：客户根据阶段1选香进行反馈优化\n\n需求价格：2000~4000\n有出口海外需要\n加香量30~35%\n目前阶段1直接递样即可阶段2、3销售根据需求可能会自提', '一三制香 指定香精', '2', '加香', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2112370858126196738', '0', '0', '05035817329389', '刘畅', '2026-10-20 10:30:33', '17201757871959617', '寄样员', '2026-10-20 17:39:31', '1', '2112370858331693057', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '6', 'YPGD-20261020-0007', '2112023098109706241', '艾理德--展会及新品推荐20261019', NULL, '1', '需求明确', '5', '香精库推荐', '301', '个人香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '370以内', '16466317325076496,113845370124130976', NULL, '2112016961247363074', '刘文婷', '刘文婷\n15067591516\n浙江省金华市义乌市 银海路399号国际商务中心2407 刘文婷 15067591516\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5144351584288', NULL, NULL, NULL, '梁皓,彭佳庆', '客户为巴西香水出口客户，故此需格外注意出口法规适用性\n需求时间：10.20需寄出需求1及需求2所需产品\n只需要寄20%香水加香产品即可\n需求1：推荐展会选中藤条产品\nLYA2429ALY 木姜子椒果\nLYA2008CLY 沙姜柠檬叶\nLJA2059BLJ 阿拉伯水烟\nLYP2112BLY 夜雨峡湾\nLJA1824CLJ 白兰巷\n只需要做成20%香水加香产品寄样即可，由于客户为外贸客户需确认出口法规，以及IFRA\n法规\n\n需求2：由于客户为巴西出口香水客户，需推荐至少15款适合南美、阿拉伯、中东的东方香型\n核心要求：东方香尾调要有木质调、带粉感，整体香气要有沉淀感\n\n需求3：推荐展会特调香水\nDXP2594BDX 青木瓜 · 情欲\nFLP2434AFL 青椒 · 反叛\nLYP2250FLY 山葵 · 锋芒\nLYP2495ALY 青花椒 · 上瘾\nFLP2431AFL 原野群鸣\nLCP2245ALC 浮游蒲公英\nFLP2437BFL 比邻有貉\nSYP2649ASY 天地野花\nDXP2382ADX 人类祖母Lucy | 取暖\nLP2014BFL 人类祖母Lucy | 迁徙\nLYP2348ALY 战壕里的平安夜 | 1914\nJKP2428AJK 战壕里的平安夜 | 礼物\nSYP2459ASY 700年后的空气 | Walle\nLCP2179ALC 700年后的空气 | Eve\n\n该项目已需求1、需求2最为紧急\n需求时间：10.20需寄出\n只需要寄20%香水加香产品即可', '艾理德--展会及新品推荐', '2', '加香', '只寄加香产品', '', '');
