INSERT INTO `w_bo_gd_20250707155940` VALUES ('2112391468076220417', '0', '0', '16275212368889684', '赵文雅', '2026-10-20 11:52:27', '17201757871959617', '寄样员', '2026-10-21 09:58:00', '1', '2112391468403351554', 'RUNNING', '运行中', '909783222', '评香部（天津）', '6', 'YPGD-20261020-0009', '2112381345161265154', '新蔡香霁线香香精推荐26-10-20', NULL, '1', '需求明确', '5', '香精库推荐', '103', '空清、消杀与熏香', '2027-10-20 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '120内', '02461210300720808373', NULL, '2099428788910673922', '韩旭（临时）', '韩旭（临时）\n18071139715\n河南省驻马店市新蔡县 月亮湾街道 产业聚集区文化路军旅时代院内4号厂房办公室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '自提', NULL, NULL, NULL, '余鹏程', '请推荐我司卖的好的热门的、强度高的檀香香型，用于线香，价位80-120以内，需要3-5款；\n另推荐3-5款其他热门香型，用于线香；\n客户属于抖音线上拜拜香品牌，面向国内市场，香精用量很大 每月1吨+；\n以上香型准备需现货，尽可能越多越好，销售周三带走', '推荐', '1', '无', '销售自提', '', '');
