INSERT INTO `w_bo_gd_20250707155940` VALUES ('2113080842216521729', '0', '0', '17906565377856558', '张婧悦', '2026-10-22 09:31:47', '17201757871959617', '寄样员', '2026-10-26 15:03:20', '1', '2113080842430406657', 'RUNNING', '运行中', '1122259561', '评香部（上海）', '5', 'YPGD-20261022-0003', '2112421391302115329', '莫凡香氛--空间香氛&展会产品推荐20261020', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '100~300', '16466317325076496,113845370124130976', NULL, '2112399578148880385', '宝宝', '宝宝\n17376513620\n浙江省杭州市西湖区融科瑷骊山15幢1单元501室 宝宝 17376513620\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5148534624816', NULL, NULL, NULL, '梁皓,彭佳庆', '需求1：展会香型推荐\nLJA2059BLJ 阿拉伯水烟\nDXA2166CDX 摩洛哥夜宴\nHDA1159DHD 夜幕沙丘\nLYP2112BLY 夜雨峡湾\nDXB2535AJK 桂月蜜藏\nYMB2004CYM 乌木织锦\nJKP1463FJK 花境\nLJA1824CLJ 白兰巷\n\n需求2：空间香氛香型推荐\n方向1.木质调（有层次感 不沉闷 不要太重太冲的 稍微柔和又有辨识度的  ）；这个可以多选点味道\n方向2.琥珀/东方/花香/皮革（温暖大气柔和）\n方向3.果香（清新柔和舒服 不要有攻击性的）\n方向4.其他（生姜 椰奶香 青瓜甜瓜）\n方向1&2需要推荐5~10款现有香型\n方向3&4需要推荐3~5款现有香型\n需要确认一下溶剂体系是否适配，一般香氛机溶剂偏挥发类（类似异构、MMB这类）\n需求2推荐价格：100~300\n需求时间：10.23\n需要香精20~30g统一寄出量即可（可分批寄出，现有的可优先寄）', '莫凡香氛--空间香氛&展会产品推荐20261020', '1', '无', NULL, '', '');
