INSERT INTO `w_bo_gd_20250707155940` VALUES ('2113463241031008257', '0', '0', '17804235042843764', '陈赛', '2026-10-23 10:51:18', '17201757871959617', '寄样员', '2026-10-27 16:22:05', '1', '2113463241282641922', 'RUNNING', '运行中', '909783222', '评香部（天津）', '7', 'YPGD-20261023-0013', '2091739695955300353', '船王-白茶松露-20260824', NULL, '1', '需求明确', '1', '客户新品开发', '2023', '香皂', '2027-08-23 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '75-100元', '17400514601408872,05035817437137', NULL, '2056212053172903938', '梁瑶', '梁瑶\n13097992317\n浙江省杭州市滨江区上峰电商产业园世包大楼B310\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1.2%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5142684581122', NULL, NULL, NULL, '于姗姗,宣二鹏', 'LJF2544BLJ 价格不变，调整增强留香，寄10克，做小块手捏皂加向量1.2%。\n\n香型 白茶松露\n用途 洗衣皂/香皂\n香味要求\n1.清新白茶香调，裹挟淡淡的木质/泥土气息，香味\n浓烈好闻不刺鼻，无劣质化工气味\n2.距离鼻子5-10cm处仍可感知香味\n3.需要留香稍微持久一点的\n4.香精无变色因素\n添香量  洗衣皂0.6%    香皂1.2%\n香型数量  推荐1-2款香精\n样品需求 \n每款香精各10ml左右，各打一小块皂选香/闻香用\n先寄样后做稳定性测试', '船王-白茶松露-20260824', '2', '加香', NULL, '', '');
