INSERT INTO `w_bo_gd_20250707155940` VALUES ('2114978349838221314', '0', '0', '16825006662777257', '齐钰', '2026-10-27 15:11:48', '050363634136321790', '逯柏松', '2026-11-10 11:35:47', '1', '2114978350081466370', 'SUCCESS_END', '成功结束', '909783222', '评香部（天津）', '7', 'YPGD-20261027-0014', '2114968563109314561', '6120时尚修改溶解度-雨姿', NULL, '5', '赢单', '3', '双马香精升级', '3011', '香水', '2026-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,邢芬', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '130', '050363634136321790,16855125875633810', NULL, '2059899734998343682', '吴甜甜', '吴甜甜\n18184257882（务必打电话联系）\n浙江省金华市东阳市六石街道长松岗工业功能区兴业街191号北楼（大门进去右边直走到三层楼办公楼左边的卷帘门）东阳市雨姿化妆品有限公司，\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '不邮寄', NULL, NULL, NULL, '逯柏松,邢芬', '6120因为有酮麝香，导致整体香精配成香水的溶解度变差，甚至析出\n保证香不变的前提下，替换\n应用：香水\n时间：10月28\n香精：15ml', '6210 雨姿调整', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2114989044361314305', '0', '0', '16825006662777257', '齐钰', '2026-10-27 15:54:17', '17906565377856558', '张婧悦', '2026-10-30 18:00:26', '1', '2114989044625530882', 'RUNNING', '运行中', '909783222', '评香部（天津）', '5', 'YPGD-20261027-0015', '2109479532393119745', '嘉美方总    够姜香水', NULL, '1', '需求明确', '1', '客户新品开发', '3011', '香水', '2027-10-12 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何家文,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '1000-3000', '1638968357988946,0549274114954944', NULL, '2059623287356350465', '方生', '方生\n18122445258\n广州市白云区均禾街新石路114号 嘉美智造园F栋二楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, 'LYP2525ALY-够姜1（香水）\nLYP1560JLY-够姜2（香水）', 'SF1572353133858', '2026-10-30 00:00:00', NULL, NULL, '何家文,王鑫', '这个项目麻烦给到上海调香师做，做好一版后可以先给乐总闻一下，乐总会给部分意见，然后没问题再寄出给客户。\n主题:够姜，在广东话就是\"有胆\"\"有种\"的意思。\n想法:整体的味道希望是能够闻起来清新提神的感觉，姜是主要的味道，上次那个沙姜精油就挺不错的，不会太冲；\n可以加一些姜花，寓意：不仅够姜，钱也要够花；同时也可以有一点橙子的味道，寓意大吉大利，如果可以的话，也可以再加一些水仙花的感觉，因为水仙花是广东春节特有的花香\n留香要求：这支香不要出现甜腻，沉闷跟脂粉感，皮肤留香时间最好是能够做到5~8小时\n产品：香水\n价格：1000-3000（可以不用太考虑价格问题）\n数量：50克', '够姜', '1', '无', NULL, '', '');
