INSERT INTO `w_bo_gd_20250707155940` VALUES ('2115267778263891969', '0', '0', '16455177663846080', '常晓爽', '2026-10-28 10:21:53', '17201757871959617', '寄样员', '2026-11-03 16:55:31', '1', '2115267778649743362', 'RUNNING', '运行中', '909783222', '评香部（天津）', '8', 'YPGD-20261028-0015', '2112447061235318786', 'Offrelax--展会香氛&Q3新品推荐20261020', NULL, '1', '需求明确', '5', '香精库推荐', '201', '头发洗护', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '16466317325076496,113845370124130976', NULL, '2112431019519885314', '王嘉岚', '王嘉岚\n18810916250\n杭州市西湖区留下街道西溪路588号珀莱雅大厦 王嘉岚 18810916250\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5147800884176', NULL, NULL, NULL, '梁皓,彭佳庆', '客户为个护洗护类头部品牌\n需要着重考虑气味以及法规适配性\n如以下推荐气味优秀但需要修改可推荐但需同步销售信息方便后续沟通\n\n需求1：根据客户展会选中产品进行推荐\nSYA2521BSY 听风眠\n需要香精30g\n\n需求2：需要自主推荐天然植萃或柑橘清爽类香型\n可推荐主题：仙人掌主题、柑橘/柑橘皮、树木森林青草、\n需要推荐：5~8款\n\n需求3：自主推荐Q3新品\nHDP2441AHD 胡萝卜花\nLCP2213ALC 樟木25\nDXP2657ADX 摇曳人参\nSYP2696BSY 迷失伊甸\nSYP2610BSY  绝漾炽橙\nLCP2248ALC  序忆\nFLP2430BFL  原点\nLJP2575ALJ  黄金比例618\nFLP2418CFL  香蕉热恋\nJKP2580AJK  寒冰伏特加\nDXP2554ADX  牛奶麝香39\nFLP2421BFL  心花茧语\nLCP2186BLC  青金石\n\n自主推荐需求价格：400以内\n需要香精20~30g\n需求1&2是最为紧急需求需要优先寄出\n需求3可全部准备后再寄出', 'offrelax展会推荐', '1', '无', NULL, '', '');
