INSERT INTO `w_bo_gd_20250707155940` VALUES ('2115387771433500674', '0', '0', '05035817329389', '刘畅', '2026-10-28 18:18:41', '16466317325076496', '梁皓', '2026-11-10 12:35:18', '1', '2115387771710300161', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '7', 'YPGD-20261028-0040', '2113225011052396545', '至外--城市系列香水香氛创香20261022', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,王晔,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '城市系列1000左右，祛味喷雾500以内', '16466317325076496,17127345845433575,113845370124130976', NULL, '2113219696059727873', '文木', '文木\n13777431504\n上海市杨浦区黄兴路221号T1栋2楼221室 文木 13777431504\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '销售自提', '2026-11-09 00:00:00', NULL, NULL, '梁皓,王晔,彭佳庆', '需求1：提供客户展会选中产品\nFLP2431AFL 原野群鸣\n\n需求2：城市系列特调-武汉&郑州两个城市系列\n武汉\n方向1：江木与汗\n雪松丝柏为主题核心\n增加海洋矿物感需要一些海盐感\n尾调增加一些麝香，增加海洋流动感\n一定不能甜，主题还是以清爽感为表现\n\n方向2：落日码头\n前调：柚子皮/陈皮+海盐模拟江风的感受\n中调：苔藓+土壤感（类似胡萝卜籽或香根草的壤香）\n尾调：香根草+膏甜\n\n郑州\n方向1：五色土\n陶土与矿物感为核心进行创香\n需要后土壤的厚重感，另外可以增加一些粉尘感\n以香根草叠加些许广藿\n前中调需要乳香和焚香感\n\n方向2：河沉积\n前调需要干燥谷物感（类似小麦或麦麸）\n中调需要矿物感与烟草灰尘\n尾调以琥珀膏甜收尾\n\n需求3：祛味喷雾\n方向1：柑橘木质\n香柠檬+草本绿叶（鼠尾草/迷迭香）+雪松/香根\n需要有洁净感联想\n\n方向2：绿木与矿物\n类似大地的矿物感+无花果叶/番茄叶+尾调苔藓、雪松、些许广藿\n\n方向3：洁净木质\n皂感伪体香（类似卡朗-自己或隐衫之欲）+开司米木/愈创木的干燥粉感木质\n\n需求价格：城市系列1000左右，祛味喷雾500以内\n需求时间：10.30\n创香完成后销售确认是否需要线下拜访\n城市系列需要20%香水加香\n祛味喷雾需要10%香水加香', '至外--城市系列创香', '1', '无', NULL, '', '');
