INSERT INTO `w_bo_gd_20250707155940` VALUES ('2115622296583389185', '0', '0', '05035817329389', '刘畅', '2026-10-29 09:50:37', '17201757871959617', '寄样员', '2026-11-16 13:53:38', '1', '2115622296931491841', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '12', 'YPGD-20261029-0004', '2114546879847972865', '厚念--新香需求推荐20261026', NULL, '1', '需求明确', '5', '香精库推荐', '2', '个人护理', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300~500', '16466317325076496,113845370124130976', NULL, '2114540981335343106', '徐梦晴', '徐梦晴\n18340532005\n浙江省杭州上城区杭州祥生中心5幢1015室  徐梦晴  18340532005\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5140960219763，SF5167733142971', NULL, NULL, NULL, '梁皓,彭佳庆', '根据客户提供brief进行推荐\n客户产品用于织物喷雾、车载香氛、无火香氛品类内\n推荐产品如不通用需备注适配类型\n客户产品需要有较高的层次感与沙龙感\n需要每个主题推荐3~5款\n主题1：秋梨\n果香木质调-可类似JKC2164AJK	黄花梨香精\n\n主题2：抹茶阳光玫瑰\n需要绿意清透果香主题，不要传统葡萄的甜腻感\n\n主题3：小雏菊\n可推荐莫洁-小雏菊 以及皂感花香，类似铃兰的香气\n\n主题4：牛奶浴\n可推荐奶感檀香-类似大米檀香 或 奶香伪体香类型\n\n主题5：椰林酒店\n需要推荐无花果奶感香气 或 无花果叶带些奶感的香气\n\n需求价格：300~500\n需求时间：10.30\n【2026.11.10更新：客户选中该款\n椰林酒店#2	SYC2136DSY\n需要在该版本上做无溶剂版本\n增强香气强度\n需求价格300左右】', '厚念--新香需求推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2115623766758244353', '0', '0', '17906565377856558', '张婧悦', '2026-10-29 09:56:27', '17906565377856558', '张婧悦', '2026-11-11 18:05:04', '1', '2115623766993100801', 'RUNNING', '运行中', '1122259561', '评香部（上海）', '6', 'YPGD-20261029-0006', '2114658465090617346', '海宁氛悦--酒店香氛仿香20261026', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, '[{\"fileName\":\"品睿.xlsx\",\"timestamp\":\"Fev0LOnkZXOFCa83EMAI\",\"size\":15276,\"secret\":null,\"fileId\":\"9a0a288d-8fc5-4f19-93ce-e9d2b0abb5a6\",\"showSize\":\"15KB\",\"fileClass\":\"iconBox excelBox\"}]', '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '高', '1', '暂定300以内，如无法达到高相似度可联系销售', '16466317325076496,113845370124130976', NULL, '2114657515399528450', '任冰', '任冰\n13671938562\n上海市徐汇区零陵路899-1号飞洲国际大厦12H  任冰  13671938562\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5169316001533', '2026-11-11 00:00:00', NULL, NULL, '梁皓,彭佳庆', '根据客户提供标样进行仿香\n汉庭\n前调：木兰、橙花、香水柠檬、香梨\n中调：桂花、玫瑰、忍冬\n后调：橡木、橡苔\n\n品睿\n前调\n中国薄荷、青柠、嫩草、露水水汽\n\n中调\n云南腾冲苔藓（顶空萃取）、白玉兰、春日野花、青竹\n后调\n柏木、香根草、橡木苔、湿润泥土、微量松脂\n\n核心需求相似度高！！！！！！！！！\n客户产品用于酒店香氛内\n需求价格：暂定300以内，如无法达到高相似度可联系销售\n需求时间：11.4', '海宁氛悦--酒店香氛仿香--品睿20261026', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2115623934584930305', '0', '0', '16455177663846080', '常晓爽', '2026-10-29 09:57:07', '17201757871959617', '寄样员', '2026-11-03 17:28:45', '1', '2115623934823981058', 'RUNNING', '运行中', '909783222', '评香部（天津）', '6', 'YPGD-20261029-0005', '2113225011052396545', '至外--城市系列香水香氛创香20261022', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,王晔,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '城市系列1000左右，祛味喷雾500以内', '16466317325076496,17127345845433575,113845370124130976', NULL, '2113219696059727873', '文木', '文木\n13777431504\n上海市杨浦区黄兴路221号T1栋2楼221室 文木 13777431504\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '寄上海，刘畅收', NULL, 'SF5147821212199，寄到上海办刘畅', NULL, NULL, NULL, '梁皓,王晔,彭佳庆', 'LJB1828BLJ，降价至500，并添加祛味原料，做祛味喷雾\n\n需求1：提供客户展会选中产品\nFLP2431AFL 原野群鸣\n\n需求2：城市系列特调-武汉&郑州两个城市系列\n武汉\n方向1：江木与汗\n雪松丝柏为主题核心\n增加海洋矿物感需要一些海盐感\n尾调增加一些麝香，增加海洋流动感\n一定不能甜，主题还是以清爽感为表现\n\n方向2：落日码头\n前调：柚子皮/陈皮+海盐模拟江风的感受\n中调：苔藓+土壤感（类似胡萝卜籽或香根草的壤香）\n尾调：香根草+膏甜\n\n郑州\n方向1：五色土\n陶土与矿物感为核心进行创香\n需要后土壤的厚重感，另外可以增加一些粉尘感\n以香根草叠加些许广藿\n前中调需要乳香和焚香感\n\n方向2：河沉积\n前调需要干燥谷物感（类似小麦或麦麸）\n中调需要矿物感与烟草灰尘\n尾调以琥珀膏甜收尾\n\n需求3：祛味喷雾\n方向1：柑橘木质\n香柠檬+草本绿叶（鼠尾草/迷迭香）+雪松/香根\n需要有洁净感联想\n\n方向2：绿木与矿物\n类似大地的矿物感+无花果叶/番茄叶+尾调苔藓、雪松、些许广藿\n\n方向3：洁净木质\n皂感伪体香（类似卡朗-自己或隐衫之欲）+开司米木/愈创木的干燥粉感木质\n\n需求价格：城市系列1000左右，祛味喷雾500以内\n需求时间：10.30\n创香完成后销售确认是否需要线下拜访\n城市系列需要20%香水加香\n祛味喷雾需要10%香水加香', '祛味喷雾-方向A改进', '1', '无', NULL, '', '');
