INSERT INTO `w_bo_gd_20250707155940` VALUES ('2116112335641755650', '0', '0', '05035817329389', '刘畅', '2026-10-30 18:17:51', '17201757871959617', '寄样员', '2026-11-12 11:43:38', '1', '2116112335897583618', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '14', 'YPGD-20261030-0027', '2115331558477905922', '杭州远夏--蜡烛藤条通用版推荐', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '120-200', '050363634136321790,113845370124130976', NULL, '2115329546650632193', '周聪', '周聪\n15888949546\n浙江省金华市东阳市六石街道曙光街995号（思科二期西门）\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5140915639113，	SF5162712054198，SF5167219994590', NULL, NULL, NULL, '逯柏松,彭佳庆', '一、以下几款是我们日常通用版精油，用于蜡烛和无火等居家香薰的香精\n小苍兰、栀子花、蓝风铃、威斯汀白茶、白桃乌龙、乌木沉香、苹果、凤梨、芭乐、柠檬\n1、适配蜡烛的，我们蜡的比例是大豆蜡60，酥油20，石蜡20，香精添加量8-15%，\n2、适配无火类型的，我们的比例是20%酒精，70%水，10%的香精\n价位：120-200，分别提供油性和水性的精油样品，\n二、热销的一些香型， 例如古龙 、希尔顿 还有一些花香类 果味的香精，水性的比例是20%酒精，70%水，10%的香精。蜡烛的比例是大豆蜡60，酥油20，石蜡20，香精添加量8-15%\n香精：50ML\n时间：11-5之前\n寄：周聪', '杭州远夏--蜡烛藤条通用版推荐', '1', '无', NULL, '', '');
