INSERT INTO `w_bo_gd_20250707155940` VALUES ('2117498089055961090', '0', '0', '16275212368889684', '赵文雅', '2026-11-03 14:04:20', '17201757871959617', '寄样员', '2026-11-05 16:54:31', '1', '2117498089303400449', 'RUNNING', '运行中', '909783222', '评香部（天津）', '7', 'YPGD-20261103-0017', '2117076832284033025', '11.2源达荔枝推荐', NULL, '1', '需求明确', '3', '双马香精升级', '302', '空间香氛', '2027-11-02 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '何佳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '150', '04476151361985', NULL, '2034161060126113794', '戚慧芳', '戚慧芳\n15822125457\n天津西青区微电子工业区微二路6号\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5144921369871', NULL, NULL, NULL, '何佳', '香精需求：荔枝香型，用于香氛除湿袋，偏油性、可浸润EVA粒子。\n香气基调：清新自然荔枝果香，拒绝厚重甜腻的蜜甜果肉款。\n使用场景：衣柜+浴室高湿环境，优先选清爽、不易闷浊的香型。\n请按下面4个方向分开送样：百香果有没有新的香型？他那边还提提出了百香果，但是优选荔枝\n1. 清新纯水润荔枝（单香，汁水感，低糖）\n2. 荔枝+绿茶/乌龙（压甜，干净通吃衣柜、浴室）\n3. 荔枝+佛手柑（少量柑橘提亮，水灵清爽）\n4. 荔枝+海盐/淡白麝香（洁净凉感，浴室抑味效果好）', '源达荔枝调整LJB2654DLJ', '1', '无', NULL, '', '');
