INSERT INTO `w_bo_gd_20250707155940` VALUES ('2117900010380050433', '0', '0', '05035817329389', '刘畅', '2026-11-04 16:41:26', '17201757871959617', '寄样员', '2026-11-06 15:17:33', '1', '2117900010631684098', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '7', 'YPGD-20261104-0026', '2101601276159578114', '西双版纳项目--文化背景特色选香推荐20260920', NULL, '1', '需求明确', '1', '客户新品开发', '2', '个人护理', '2027-09-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆,王晔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '320以内', '16466317325076496,113845370124130976,17127345845433575', NULL, '2101584844520673282,2101585077992411137', '叶珍利,徐丹青', '叶珍利,15752372107,云南省西双版纳傣族自治州景洪市 详细地址：勐泐大道55号西双版纳ISC漫方商业中心  叶珍利  15752372107\n\n徐丹青,18611706977,山东青岛市崂山区 详细地址：银丰玖玺城南区3号楼1单元1502  徐丹青  18611706977\n\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5144910073139，SF5144910370418', NULL, NULL, NULL, '梁皓,彭佳庆,王晔', '客户首批产品用于：皂、香包、线香\n客户市场对标品牌：万物香铺\n需要确认法规合规性！！！！！！！！\n第一阶段优先推荐5个主要主题香型推荐，还需要一个主题外推荐\n方向1：糯米饭（斑斓、糯米、米香、粽子、红枣糯米饭）\n方向2：果香（傣柚，菠萝，百香果，树番茄）\n方向3：花香（缅栀花、默红玫瑰、\n方向4：木质（雨林、木姜子、香茅、楠木、樟木）\n方向5：咖啡\n方向6：其他（符合消费客群对西双版纳的联想类香型）\n每个方向需要推荐3~5款尽可能多推荐\n方向6其他品类需要5~8款\n需要寄两个地址：每个地址5~10g香精以及10%香水加香产品\n需求时间：最晚10.9寄出\n需求价格：320以内\n\n第二阶段会由阶段一反馈的方向或香型基础上做优化\n预计时间为十月中下旬', '回眸-青木瓜', '1', '无', NULL, '', '');
