INSERT INTO `w_bo_gd_20250707155940` VALUES ('2118543488164282370', '0', '0', '05035817329389', '刘畅', '2026-11-06 11:18:23', '17201757871959617', '寄样员', '2026-11-13 11:17:24', '1', '2118543488378167298', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '4', 'YPGD-20261106-0010', '2117113084110684162', '回家本能--棉花香型推荐20261102', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400以内', '16466317325076496,113845370124130976', NULL, '2034161062130991106', 'Eddy', 'Eddy\n19957842610\n浙江省宁波市海曙区柳汀街297号（星悦中心8号楼）2309   eddy 19957842610\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5164523336087', NULL, NULL, NULL, '梁皓,彭佳庆', '客户产品用于EVA香珠以及香氛喷雾内\n对应棉花主题\n需要推荐艾克卡帕--白苔\n需要确认适配性和法规！！！\n需要一款高相似度版和一款IPM版本\n需要20g样品\n需求价格：400以内\n需求时间：11.6', '回家本能--棉花香型推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2118550502848315393', '0', '0', '17906565377856558', '张婧悦', '2026-11-06 11:46:15', '17906565377856558', '张婧悦', '2026-11-06 11:47:34', '1', '2118550503099949058', 'RUNNING', '运行中', '1122259561', '评香部（上海）', '2', 'YPGD-20261106-0011', '2117521933984579585', '春季新香需求brief-赤翎', NULL, '1', '需求明确', '1', '客户新品开发', '3012', '香水油', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000', '050363634136321790,113845370124130976', NULL, '2087468994553434114', '柳兰若', '柳兰若\n13701266645\n中国上海市虹口区东长治路505号雷士德工学院旧址，放快递室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '逯柏松,彭佳庆', '1. 风筝：自由，风的味道（沙尘、泥土、草味、阳光味、苔藓味）\n2. 整体香调要偏清新，有种“春”高气爽感\n3. 避开非常明确、常见的春天花香和果香，不要甜腻感\n4. 尾调留香要足够长，但不要存在感太强，最好是贴皮肤才能闻得见的那种若有若无的感觉\n\n目标成本区间：1000-2000元/kg，预计成品价格300-400/15ml香水油，偏中性香，20-40年龄段群体均覆盖\n应用：香水油12%（需要上脸）\n时间：11月16号前', '赤翎-春季新香', '1', '无', NULL, '', '');
