INSERT INTO `w_bo_gd_20250707155940` VALUES ('2118601871038857217', '0', '0', '05035817329389', '刘畅', '2026-11-06 15:10:22', '05035817329389', '刘畅', '2026-11-06 15:10:22', '1', '2118601871298879490', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '1', 'YPGD-20261106-0022', '2117498578401214465', '弗止--鸣潮角色香织物喷雾20261103', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~300', '16466317325076496,113845370124130976', NULL, '2055159748134658049', 'jiojio', 'jiojio\n15178065377\n上海市静安区江场路1447号云芯科创中心T1号楼19楼DO事业部 jiojio，15178065377', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '梁皓,彭佳庆', '鸣潮角色香氛喷雾\n共三个人物香氛\n每个需求需要推荐3款，可在推荐上修改更接近客户需求内容\n上线预计在初夏，香气需要偏清爽\n需注意10A类法规加香量！！！！\n\n需求1：景燃\n参考三调\n前调：佛手柑 杜松子 粉红胡椒\n中调：马黛茶 紫罗兰叶 快乐鼠尾草 梨\n后调：雪松 白麝香 绿色皮革 岩兰草\n市场产品参考\nMEMO 爱尔兰皮革\n\n需求2：爱弥斯\n参考三调\n前调：梨 橙花 香柠檬 粉红胡椒\n中调：玫瑰 牡丹 榛子 铃兰\n后调：开司米木 雪松 杜松 琥珀\n市场产品参考\n馥阁 我可否将你比作一个夏日/creed\n银雾玫瑰\n\n需求3：绯雪\n前调：柚子 杜松子\n中调：醛 樱花 小苍兰 雪\n后调：日本桧木 白麝香 雪松 一点点点点\n点藏红花（需要一点辛辣)\n市场产品参考\n安南之香\n樱吹雪\n\n需求4：心\n前调：甜橙 荔枝 粉红胡椒 秦艽\n中调：白茶 玫瑰 鸢尾花 焚香\n后调：冷杉 雪松 琥珀 白麝香\n市场产品参考\n妩媚版本的雪白龙胆\n\n主要是做织物香氛和香氛挂件，需要考虑舒适程度以及扩香效果\n游戏定位：本身是男性向ml（master love）二游，游戏整体风格（包含剧情、女npc的服设\n等）还是偏向于男性受众。\n玩家性别比：男女比约为9：1\n考虑到受众，香气最好是稍微中性一点的\n需求价格：200~300\n需要15%香水加香产品\n需求时间：11.20', '弗止--鸣潮角色香织物喷雾', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2118610279272005634', '0', '0', '05035817329389', '刘畅', '2026-11-06 15:43:47', '17201757871959617', '寄样员', '2026-11-16 17:42:40', '1', '2118610279557193729', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '4', 'YPGD-20261106-0023', '2117465829711790081', '无火香薰推荐-阿迪纳兰', NULL, '1', '需求明确', '5', '香精库推荐', '302', '空间香氛', '2026-12-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200', '050363634136321790,113845370124130976', NULL, '2117463542939500546', '深白', '深白\n17300967619\n浙江省杭州市西湖区古天巷8号云州国际中心1号楼A区阿迪纳兰701室\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '已打包', NULL, NULL, NULL, '逯柏松,彭佳庆', '推荐一些表现力比较好的空间香薰香型-10款-价格：200以内\n再推荐一些香型比较新颖的空间香薰香型-10款-价格-250-以内\n先不考虑溶剂，可直接推荐\n应用:空间香氛\n时间：11月12号前寄出\n香精：15ml', '无火香薰推荐-阿迪纳兰', '1', '无', NULL, '', '');
