INSERT INTO `w_bo_gd_20250707155940` VALUES ('2119614072017010690', '0', '0', '16825006662777257', '齐钰', '2026-11-09 10:12:30', '17201757871959617', '寄样员', '2026-11-17 16:14:43', '1', '2119614072314892289', 'RUNNING', '运行中', '909783222', '评香部（天津）', '4', 'YPGD-20261109-0007', '2118643231196356609', '北京尚潮香膏香精推荐26-11-06', NULL, '1', '需求明确', '5', '香精库推荐', '3013', '香膏', '2027-11-06 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '余鹏程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '400内', '02461210300720808373', NULL, '2061985820599869441', '章迈', '章迈\n15532315641\n北京市 东城区 详细地址:科林大厦A座5层\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '已打包', NULL, NULL, NULL, '余鹏程', '1、香膏品类-玫瑰香膏\n·香调参考：祖玛珑 红玫瑰（Red Roses）、保罗史密斯 玫瑰之约（Paul Smith Rose）、梵诗柯香 盛放玫瑰（À la rose，MFK）、雅芮 格拉斯玫瑰（Rose de Grasse Pour Filles）、迪奥 玫舞轻旋（Miss Dior Rose N\'Roses）\n·香味描述：轻柔花香，主香调，玫瑰花香\n·目标人群：：女性，送礼向\n·需求量：5kg\n·价格：300-500/公斤 品质可以更好些\n\n\n2、香膏品类-爱心形香膏\n·香味描述：木质调：柠檬、柑橘、桂花、；花香调+绿调：香柠檬、玫瑰、茉莉、沉香、琥珀、白麝香；\n·目标人群：：女性，送礼向\n·需求量：5kg\n·价格：300-500/公斤 品质可以更好些\n\n4、工厂推荐香：我司新品香型推荐3-5款\n\n注意！请在样品标签上注明属于哪个分类，如“玫瑰香膏”、“爱心形香膏”、还是“工厂推荐香”\n1号需求、2号需求尽量按客户提供的每个元素对应一款香精', '尚潮推荐', '1', '无', NULL, '', '');
