INSERT INTO `w_bo_gd_20250707155940` VALUES ('2120408988842344450', '0', '0', '16275212368889684', '赵文雅', '2026-11-11 14:51:13', '16275212368889684', '赵文雅', '2026-11-12 10:47:17', '1', '2120408989106671618', 'RUNNING', '运行中', '909783222', '评香部（天津）', '4', 'YPGD-20261111-0015', '2120360787179356162', '金王-推荐品牌4款香味的仿香-20261111', NULL, '1', '需求明确', '3', '双马香精升级', '302', '空间香氛', '2027-11-11 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,宣二鹏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '价格200以内', '17400514601408872,05035817437137', NULL, '2034161064601436162', '京京', '京京\n18354293315\n山东青岛市市南区福泰广场B座24层金王\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '于姗姗,宣二鹏', '应用产品：香薰油&蜡，价格200以内，麻烦给安排50g样品，文件是客户自己整理的香调也可以参照这个前中后调\nSHIRO 皂香 SAVON\n刚洗完澡、白 T 恤那种干净伪体香，带一点点清甜果香，不是老式肥皂味\n前调：柠檬、甜橙、黑加仑、荔枝 → 明亮清爽，淡淡的果汁甜，不腻\n中调：玫瑰、茉莉、铃兰、李子 → 柔和小白花，衬出皂感\n后调：麝香、琥珀、淡淡的木质甜感 → 落地成很贴皮肤的干净皂香，软乎乎的', '金王 SHIRO 皂香', '1', '无', NULL, '', '');
