INSERT INTO `w_bo_gd_20250707155940` VALUES ('2120731256000757762', '0', '0', '16825006662777257', '齐钰', '2026-11-12 12:11:47', '17906565377856558', '张婧悦', '2026-11-12 15:58:16', '1', '2120731256218947586', 'RUNNING', '运行中', '909783222', '评香部（天津）', '5', 'YPGD-20261112-0016', '2112124298649911297', '一三制香--高定香氛推荐&修改20261019', NULL, '1', '需求明确', '1', '客户新品开发', '3011', '香水', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '2000~4000', '16466317325076496,113845370124130976', NULL, '2112118946592178177', '杨爽', '杨爽\n18811360696\n北京市石景山区鲁谷街道长安悦玺小区7-2-2101，杨爽，18811360696\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5169220508750', '2026-11-12 00:00:00', NULL, NULL, '梁皓,彭佳庆', '客户产品主要用于香水内\n后续有出口需求\n调整阶段需要注意法规需求以及IFRA需求（最高35%添加量）\n\n阶段1：根据客户提供香水参考表进行第一轮推荐\n需要原版贵价版本\n提供香精和加香产品，加香量30%\n推荐10~12支，如表格内数量不够可根据客户喜好进行自行推荐\n需求时间：10.29寄出\n\n阶段2：客户同步寄出需要我们仿香修改的大牌香氛\n根据客户提供标样进行GC分析并根据修改方向进行优化\n需要提供原版和优化版各一支\n需要香精和加香产品香水30%\n该需求需要考虑后续法规以及出口需要\n\n阶段3：客户根据阶段1选香进行反馈优化\n\n需求价格：2000~4000\n有出口海外需要\n加香量30~35%\n目前阶段1直接递样即可阶段2、3销售根据需求可能会自提', '佳吉列夫', '1', '无', NULL, '', '');
