INSERT INTO `w_bo_gd_20250707155940` VALUES ('2120796088477564929', '0', '0', '16455177663846080', '常晓爽', '2026-11-12 16:29:25', '17201757871959617', '寄样员', '2026-11-16 16:43:04', '1', '2120796088649617410', 'RUNNING', '运行中', '909783222', '评香部（天津）', '4', 'YPGD-20261112-0030', '2113209067018108930', '林清轩--纯精油香氛推荐20261022', NULL, '1', '需求明确', '5', '香精库推荐', '2081', '芳疗精油', '2027-10-31 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,王晔,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '无', '16466317325076496,17127345845433575,113845370124130976', NULL, '2112805997390053378', '赵', '赵\n13105380027\n上海松江区林清轩碳中和科研智造基地研发楼3楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5165434774874', NULL, NULL, NULL, '梁皓,王晔,彭佳庆', '无需寄样！！！销售预约线下拜访\n推荐目前库存现有能全开配方的纯精油体系\n以及目前香气表现出色的香精个护产品\n需要纯精油推荐5款\n需要香精推荐5~8款\n产品用于高端面霜和油膏体系\n本次推荐已气味为主要表现！！！！\n同步需要关于我司对情绪功效宣称背书或报告案例！！！！！！！\n另外需要准备我司东方原料小盒\n与客户预约线下拜访\n需求价格：无，已香气表现为主\n需求时间：10.30\n需要加香产品膏霜个护类，加香量按我司推荐添加即可，用于展示用\n需要配套ppt支持', '林清轩香精推荐', '1', '无', '寄上海，梁皓收', '', '');
