INSERT INTO `w_bo_gd_20250707155940` VALUES ('2122499946497064961', '0', '0', '16825006662777257', '齐钰', '2026-11-17 09:19:56', '16825006662777257', '齐钰', '2026-11-17 09:20:20', '1', '2122499946727837697', 'RUNNING', '运行中', '909783222', '评香部（天津）', '2', 'YPGD-20261117-0001', '2122263585563230209', '嘉美-静骨 DH-U241220 感觉整体都是木质调太木了-20261116', NULL, '1', '需求明确', '2', '客户老品升级', '3011', '香水', '2027-11-16 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '于姗姗,王鑫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '-', '17400514601408872,0549274114954944', NULL, '2059564522166771713', '郭思敏', '郭思敏\n19966281017\n州市白云区均禾街新石路114号 嘉美智造园F栋2楼\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '于姗姗,王鑫', '第一版：静骨（DH-U241220）感觉整体都是木质调，太木了；第二版：静骨（#改进）DH-G174695，与第一版相比很极端，这一版的话直接是花香类型了，木的感觉没有了，因为其实静骨的魅力就是它的开场是小花茉莉的那种淡淡的花香，但茉莉不能太过于重，到中后调是偏木质的感觉，但木也不能太重。 希望综合再调整一下', '静骨调整', '1', '无', NULL, '', '');
