INSERT INTO `w_bo_gd_20250707155940` VALUES ('2122645186583347202', '0', '0', '05035817329389', '刘畅', '2026-11-17 18:57:04', '05035817329389', '刘畅', '2026-11-17 18:57:04', '1', '2122645186826702849', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '1', 'YPGD-20261117-0054', '2118256094349344769', '萨若之感--新品开发推荐20261105', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '200~1000', '16466317325076496,113845370124130976', NULL, '2082373331427758081', '马曼曼', '马曼曼\n18701794453\n上海市普陀区长寿路街道长寿路189号联合办公7楼712-1 马曼曼 18701794453', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '梁皓,彭佳庆', '客户产品用于环境香氛喷雾内\n\n需求1：仿香推荐\n推荐客户对标仿香过的产品\n观夏 苦尽橙（柑橘木质焚香）\n观夏 111号孤岛（茶香东方木质）\n观夏 南音芭乐（冰凉果香×桂花木质）\n蓦刻MO MAEK 南国芭乐（高还原果实）\n观夏 颐和金桂（桂花×桃果×琥珀麝香）\nDiptyque 杜桑（清冷晚香玉×海洋调）\n五分之山 杏与青藤（杏子果香木质）\n选择已仿香过的产品推荐即可\n需求价格：200~500\n\n需求2：新品开发推荐（可做优化）\n方向1：优先级高的产品\n海岸柑橘 / 香柠檬苦橙\n沉檀 / 焚香（东方木质）\n清茶 / 白茶\n雾感鸢尾\n干净皂感 / 白麝香（伪体香）\n现代沉香（绿意/香草调）\n焚香柑橘树脂（对标AENTOS坤元）\n乌木普洱·茶×焚香（对标屋闻大树）\n桂花（东方甜花）\n露水栀子（清新白花）\n铃兰（清幽山谷百合）\n改11款未高优先级开发主题需要重点挑选合适的\n每个主题需要推荐3款样品，可以库内有的优先寄出\n需求价格：200~1000\n\n无花果（绿叶向）\n柔和木质麝香（雪松+白麝香）\n地域植物志（地中海/岛屿）\n药感 / 根茎与树脂\n\n方向2：优先级次级产品\n无花果（绿叶向）\n柔和木质麝香（雪松+白麝香）\n地域植物志（地中海/岛屿）\n药感 / 根茎与树脂\n草本薄荷绿意（对标AENTOS生）\n冥想木质花香（对标AENTOS土也）\n烟熏篝火木质（对标卯时卯刻蜡烛）\n暖甜东方木质（对标屋闻零陵香豆）\n柚子叶（青绿草本）\n茉莉清茶（听泉茉莉向）\n兰花（东方馥郁兰）\n该系列主题推荐1~2款即可\n需求价格：200~500\n需要备注对应选品主题\n\n高优先级产品需要15%香水加香产品！！！！！！！！！！！\n需确认4类或10A类加香量\n需求时间：11.20全部选出寄出，高优先级需要11.13寄出', '萨若之感--新品开发推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2122648842707812353', '0', '0', '05035817329389', '刘畅', '2026-11-17 19:11:36', '17201757871959617', '寄样员', '2026-11-18 09:55:26', '1', '2122648842967945217', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '3', 'YPGD-20261117-0055', '2119625663592677378', '宜歌--27春夏新品沐浴露开发推荐20261109', NULL, '1', '需求明确', '5', '香精库推荐', '2', '个人护理', '2027-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2114679406260633602', 'vicky', 'vicky\n13951037656\n上海市静安区北京西路968号7层 vicky 13951037656\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, 'SF5169039782223', NULL, NULL, NULL, '梁皓,彭佳庆', '推荐5~8款适合春夏较为清爽的香型\n柑橘、自然、绿意、花香均可\n主要还是爆发力以及香气舒适清透感\n需求价格：300以内\n需求时间：11.13', '宜歌--27春夏新品沐浴露开发推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2122651202381299713', '0', '0', '05035817329389', '刘畅', '2026-11-17 19:20:58', '05035817329389', '刘畅', '2026-11-17 19:22:33', '1', '2122651202565935105', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '2', 'YPGD-20261117-0056', '2119635691192074242', '挚物志--柿子香薰优化推荐20261109', NULL, '1', '需求明确', '1', '客户新品开发', '302', '空间香氛', '2027-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300以内', '16466317325076496,113845370124130976', NULL, '2034161061262770177', '夏甦*', '夏甦*\n13817346604\n上海市闵行区中春路7001号明谷科技园A栋511 夏甦 13817346604\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '梁皓,彭佳庆', '需要选取清爽汁水感的香型作为base\n添加柿子元素类似清甜脆爽的汁水果香（微甜）\n需要应用于蜡烛、无火、香氛喷雾产品内\n需要15%无火以及10%蜡烛加香产品\n需求价格：300以内\n需求时间：11.18\n【LYC2411ALY柿子，提升柿子果香部分，同时增加一些汁水和甜感】', '挚物志--柿子香薰优化推荐', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2122652876747456514', '0', '0', '05035817329389', '刘畅', '2026-11-17 19:27:37', '05035817329389', '刘畅', '2026-11-17 19:27:37', '1', '2122652877028560897', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '1', 'YPGD-20261117-0057', '2119651387162640386', '挚物志--27年新品创香优化开发20261109', NULL, '1', '需求明确', '1', '客户新品开发', '3', '高级香氛', '2027-11-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '梁皓', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '300', '16466317325076496', NULL, '2034161061262770177', '夏甦*', '夏甦*\n13817346604\n上海市闵行区中春路7001号明谷科技园A栋511 夏甦 13817346604', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TJ', '天津样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '梁皓', '客户27年香水&香薰类产品开发\n需求1：茶Plus\n需要在中式or日式传统茶饮增加新鲜果蔬主题\n\n需求2：无糖果蔬\n需要选取具有地方特色代表或有话题性的水果（类似：木姜子、青芒、黄皮等）\n结合田园果蔬主题（类似胡萝卜、芫荽、黄瓜、罗勒等）\n\n需求3：花Plus\n花香（铃兰、茉莉、郁金香等偏柔的花香）＋伪体香\n\n需求4：轻量药材\n人参、陈皮、沉香、白檀等\n\n需求5纹理木质\n开司米木、香根草、橡木苔、桧木、焚香等\n\n上述5个需求均需选取大牌香氛为底在此基础上做优化\n每个方向需要提供2~3款\n优化方向可参考chloe-仙境花园系列\n整体以轻盈清透为主\n需要15%香水加香产品\n需求价格：300\n需求时间：11.25', '挚物志--27年新品创香优化开发', '1', '无', NULL, '', '');
INSERT INTO `w_bo_gd_20250707155940` VALUES ('2122653665159168002', '0', '0', '05035817329389', '刘畅', '2026-11-17 19:30:45', '05035817329389', '刘畅', '2026-11-17 19:30:45', '1', '2122653665389940737', 'RUNNING', '运行中', '621271385', '研发中心（上海）', '1', 'YPGD-20261117-0058', '2119720821990506498', '杜鹃品牌香创香-九色花', NULL, '1', '需求明确', '1', '客户新品开发', '301', '个人香氛', '2026-12-30 00:00:00', NULL, '', '', NULL, '', '', NULL, NULL, NULL, '逯柏松,彭佳庆', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, '', '', NULL, '', '', '600', '050363634136321790,113845370124130976', NULL, '2119720955545534465', '祁奕', '祁奕\n15821146928\n上海市浦东新区周浦镇周东路458弄7号101室', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SH', '上海样品库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, '逯柏松,彭佳庆', '新项目可以开始[呲牙]首批目标是30ml x 1000瓶。\n还是花香为主，果香调点缀，木质收尾，整只香，要花香里面叠加暖感，但还保留清凉感。\n春游时，风里面飘来花香的氛围感，不是粉感。像是清晨花瓣带露珠那种，清新的花香。\n粉色、红色的花，杜鹃主题。不追求写实，嗅感是花香、暖感、甜感。\n\n新香的安全标准参考欧盟化妆品法规及欧盟CLP标准。\n偏女香\n\nKG单价控制在600左右，预计（不晚于）2027年春节前完成备案，大货预计在2027年2月底前。\n应用：香水\n价格：600\n时间，11月底寄出\n香精：15ml；加香产品15%\n\n上海市浦东新区周浦镇周东路458弄7号101室\n祁奕 15821146928', '杜鹃品牌香创香-九色花', '1', '无', NULL, '', '');
